insert  into `lm_ai_chart`(`ID`,`USER_ID`,`DB_CONFIG_ID`,`INSTANCE_NAME`,`TITLE`,`SQL_TEXT`,`CHART_SPEC`,`CONVERSATION_ID`,`DEL_FLAG`,`CREATE_BY`,`CREATE_TIME`,`UPDATE_BY`,`UPDATE_TIME`,`DATASET_ID`,`SOURCE_TYPE`,`SPEC_VERSION`,`REVISION`,`DESCRIPTION`) values 
(1467948409119872,1,1,'lemon_demo','每年公告发布数量统计','SELECT YEAR(COALESCE(RELEASE_TIME, CREATE_TIME)) AS `年份`,\n       COUNT(*) AS `发布数量`\nFROM lm_cms_content\nWHERE DEL_FLAG = 0\n  AND COALESCE(RELEASE_TIME, CREATE_TIME) IS NOT NULL\nGROUP BY YEAR(COALESCE(RELEASE_TIME, CREATE_TIME))\nORDER BY `年份`','{\"chartType\":\"bar\",\"xField\":\"年份\",\"yFields\":[\"发布数量\"],\"seriesField\":null,\"stack\":null,\"xAxisLabel\":\"年份\",\"yAxisLabel\":\"发布数量\",\"valueFormat\":\"number\",\"sortBy\":\"asc\",\"sortOrder\":\"asc\",\"description\":\"按发布年份统计 CMS 公告（内容）发布数量，已排除软删除数据（DEL_FLAG=0），不区分栏目/子栏目。\"}',NULL,0,'yan','2026-09-05 23:48:41','yan','2026-09-05 23:48:41',NULL,'AI',1,1,NULL),
(1473510231262336,1,1,'lemon_cms','各栏目已发布公告数量','SELECT c.CHANNEL_NAME AS `栏目名称`,\n       IFNULL(cp.CHANNEL_NAME, \'-\') AS `上级栏目`,\n       COUNT(ct.ID) AS `已发布公告数`\nFROM lm_cms_channel c\nLEFT JOIN lm_cms_channel cp ON cp.ID = c.PARENT_ID\nLEFT JOIN lm_cms_content ct\n       ON ct.CHANNEL_ID = c.ID\n      AND IFNULL(ct.DEL_FLAG, 0) = 0\n      AND ct.RELEASE_TIME IS NOT NULL\nWHERE IFNULL(c.DEL_FLAG, 0) = 0\nGROUP BY c.ID, c.CHANNEL_NAME, cp.CHANNEL_NAME\nORDER BY `已发布公告数` DESC, `栏目名称` ASC\nLIMIT 100','{\"chartType\":\"bar\",\"xField\":\"栏目名称\",\"yFields\":[\"已发布公告数\"],\"stack\":false,\"xAxisLabel\":\"栏目\",\"yAxisLabel\":\"公告数量\",\"valueFormat\":\"number\",\"sortBy\":\"已发布公告数\",\"sortOrder\":\"desc\",\"description\":\"统计口径：以 lm_cms_channel（未删除栏目）为主表，左联 lm_cms_content 统计各栏目下 DEL_FLAG=0 且 RELEASE_TIME 非空（即已发布）的内容条数；上级栏目仅作辅助识别同名子栏目。\",\"appearance\":{\"fontSize\":10}}',NULL,0,'yan','2026-09-13 20:24:14','yan','2026-09-15 14:17:11',1474745388631168,'AI',1,2,NULL),
(1493846748415104,1,1,'lemon_demo','Demo - Monthly revenue','SELECT \'2026-07\' AS month, 44800 AS revenue\nUNION ALL SELECT \'2026-08\', 53600\nUNION ALL SELECT \'2026-09\', 64400\nORDER BY month','{\"chartType\":\"bar\",\"xField\":\"month\",\"yFields\":[\"revenue\"],\"valueFormat\":\"number\",\"stack\":false,\"sortOrder\":\"asc\",\"appearance\":{}}',NULL,0,'yan','2026-10-12 13:58:59','yan','2026-10-12 13:58:59',1493846748439680,'MANUAL',1,1,'');
