(1473510128272512,1473509926102144,10,'tool','{\"relationships\":[{\"from\":\"lm_cms_channel\",\"to\":\"lm_cms_channel_ext\",\"onSql\":\"lm_cms_channel.ID = lm_cms_channel_ext.ID\",\"joinType\":\"LEFT\",\"type\":\"ONE_TO_MANY\",\"canvasGroup\":null,\"description\":\"\"},{\"from\":\"lm_cms_content\",\"to\":\"lm_cms_content_txt\",\"onSql\":\"lm_cms_content.ID = lm_cms_content_txt.id\",\"joinType\":\"LEFT\",\"type\":\"ONE_TO_MANY\",\"canvasGroup\":null,\"description\":\"\"},{\"from\":\"lm_cms_content\",\"to\":\"lm_cms_channel\",\"onSql\":\"lm_cms_content.CHANNEL_ID = lm_cms_channel.ID\",\"joinType\":\"LEFT\",\"type\":\"ONE_TO_MANY\",\"canvasGroup\":null,\"description\":\"\"},{\"from\":\"lm_cms_channel\",\"to\":\"lm_cms_site\",\"onSql\":\"lm_cms_channel.SITE_ID = lm_cms_site.id\",\"joinType\":\"INNER\",\"type\":\"ONE_TO_MANY\",\"canvasGroup\":null,\"description\":\"\"},{\"from\":\"lm_cms_content\",\"to\":\"lm_cms_site\",\"onSql\":\"lm_cms_content.SITE_ID = lm_cms_site.id\",\"joinType\":\"LEFT\",\"type\":\"ONE_TO_ONE\",\"canvasGroup\":null,\"description\":\"\"},{\"from\":\"lm_cms_channel\",\"to\":\"lm_cms_model\",\"onSql\":\"lm_cms_channel.MODEL_ID = lm_cms_model.ID\",\"joinType\":\"INNER\",\"type\":\"ONE_TO_MANY\",\"canvasGroup\":null,\"description\":\"\"},{\"from\":\"lm_cms_model\",\"to\":\"lm_cms_content\",\"onSql\":\"lm_cms_model.ID = lm_cms_content.MODEL_ID\",\"joinType\":\"LEFT\",\"type\":\"ONE_TO_MANY\",\"canvasGroup\":\"默认画布\",\"description\":\"\"},{\"from\":\"lm_cms_model\",\"to\":\"lm_cms_channel\",\"onSql\":\"lm_cms_model.ID = lm_cms_channel.MODEL_ID\",\"joinType\":\"INNER\",\"type\":\"ONE_TO_MANY\",\"canvasGroup\":\"画布-2\",\"description\":\"\"},{\"from\":\"lm_cms_content\",\"to\":\"lm_cms_model\",\"onSql\":\"lm_cms_content.MODEL_ID = lm_cms_model.ID\",\"joinType\":\"LEFT\",\"type\":\"ONE_TO_ONE\",\"canvasGroup\":\"lemon_cms\",\"description\":\"\"}],\"note\":null}',NULL,NULL,'call_0d3b48de1abc46a29ffb4f4a','get_table_relationships',NULL,NULL,NULL,NULL,'2026-09