insert  into `lm_bi_dataset`(`ID`,`USER_ID`,`NAME`,`DB_CONFIG_ID`,`INSTANCE_NAME`,`SQL_TEXT`,`PARAM_SCHEMA_JSON`,`DEFAULT_PARAMS_JSON`,`MAX_ROWS`,`TIMEOUT_SECONDS`,`REVISION`,`DEL_FLAG`,`CREATE_BY`,`CREATE_TIME`,`UPDATE_BY`,`UPDATE_TIME`) values 
(1474305996031104,1,'各栏目已发布公告数量',1,'lemon_cms','SELECT c.CHANNEL_NAME AS `栏目名称`,\n       IFNULL(cp.CHANNEL_NAME, \'-\') AS `上级栏目`,\n       COUNT(ct.ID) AS `已发布公告数`\nFROM lm_cms_channel c\nLEFT JOIN lm_cms_channel cp ON cp.ID = c.PARENT_ID\nLEFT JOIN lm_cms_content ct\n       ON ct.CHANNEL_ID = c.ID\n      AND IFNULL(ct.DEL_FLAG, 0) = 0\n      AND ct.RELEASE_TIME IS NOT NULL\nWHERE IFNULL(c.DEL_FLAG, 0) = 0\nGROUP BY c.ID, c.CHANNEL_NAME, cp.CHANNEL_NAME\nORDER BY `已发布公告数` DESC, `栏目名称` ASC\nLIMIT 100',NULL,NULL,2000,30,1,0,'yan','2026-09-14 23:23:14','yan','2026-09-14 23:23:14'),
(1474306110710912,1,'每年公告发布数量统计',1,'lemon_demo','SELECT YEAR(COALESCE(RELEASE_TIME, CREATE_TIME)) AS `年份`,\n       COUNT(*) AS `发布数量`\nFROM lm_cms_content\nWHERE DEL_FLAG = 0\n  AND COALESCE(RELEASE_TIME, CREATE_TIME) IS NOT NULL\nGROUP BY YEAR(COALESCE(RELEASE_TIME, CREATE_TIME))\nORDER BY `年份`',NULL,NULL,2000,30,1,0,'yan','2026-09-14 23:23:28','yan','2026-09-14 23:23:28'),
(1474311469024384,1,'每年公告发布数量统计',1,'lemon_demo','SELECT YEAR(COALESCE(RELEASE_TIME, CREATE_TIME)) AS `年份`,\n       COUNT(*) AS `发布数量`\nFROM lm_cms_content\nWHERE DEL_FLAG = 0\n  AND COALESCE(RELEASE_TIME, CREATE_TIME) IS NOT NULL\nGROUP BY YEAR(COALESCE(RELEASE_TIME, CREATE_TIME))\nORDER BY `年份`',NULL,NULL,2000,30,1,0,'yan','2026-09-14 23:34:22','yan','2026-09-14 23:34:22'),
(1474311475004544,1,'每年公告发布数量统计',1,'lemon_demo','SELECT YEAR(COALESCE(RELEASE_TIME, CREATE_TIME)) AS `年份`,\n       COUNT(*) AS `发布数量`\nFROM lm_cms_content\nWHERE DEL_FLAG = 0\n  AND COALESCE(RELEASE_TIME, CREATE_TIME) IS NOT NULL\nGROUP BY YEAR(COALESCE(RELEASE_TIME, CREATE_TIME))\nORDER BY `年份`',NULL,NULL,2000,30,1,0,'yan','2026-09-14 23:34:22','yan','2026-09-14 23:34:22'),
(1474312154285184,1,'每年公告发布数量统计',1,'lemon_demo','SELECT YEAR(COALESCE(RELEASE_TIME, CREATE_TIME)) AS `年份`,\n       COUNT(*) AS `发布数量`\nFROM lm_cms_content\nWHERE DEL_FLAG = 0\n  AND COALESCE(RELEASE_TIME, CREATE_TIME) IS NOT NULL\nGROUP BY YEAR(COALESCE(RELEASE_TIME, CREATE_TIME))\nORDER BY `年份`',NULL,NULL,2000,30,1,0,'yan','2026-09-14 23:35:45','yan','2026-09-14 23:35:45'),
(1474628346938496,1,'各栏目已发布公告数量',1,'lemon_cms','SELECT c.CHANNEL_NAME AS `栏目名称`,\n       IFNULL(cp.CHANNEL_NAME, \'-\') AS `上级栏目`,\n       COUNT(ct.ID) AS `已发布公告数`\nFROM lm_cms_channel c\nLEFT JOIN lm_cms_channel cp ON cp.ID = c.PARENT_ID\nLEFT JOIN lm_cms_content ct\n       ON ct.CHANNEL_ID = c.ID\n      AND IFNULL(ct.DEL_FLAG, 0) = 0\n      AND ct.RELEASE_TIME IS NOT NULL\nWHERE IFNULL(c.DEL_FLAG, 0) = 0\nGROUP BY c.ID, c.CHANNEL_NAME, cp.CHANNEL_NAME\nORDER BY `已发布公告数` DESC, `栏目名称` ASC\nLIMIT 100',NULL,NULL,2000,30,1,0,'yan','2026-09-15 10:19:03','yan','2026-09-15 10:19:03'),
(1474628378231936,1,'每年公告发布数量统计',1,'lemon_demo','SELECT YEAR(COALESCE(RELEASE_TIME, CREATE_TIME)) AS `年份`,\n       COUNT(*) AS `发布数量`\nFROM lm_cms_content\nWHERE DEL_FLAG = 0\n  AND COALESCE(RELEASE_TIME, CREATE_TIME) IS NOT NULL\nGROUP BY YEAR(COALESCE(RELEASE_TIME, CREATE_TIME))\nORDER BY `年份`',NULL,NULL,2000,30,1,0,'yan','2026-09-15 10:19:07','yan','2026-09-15 10:19:07'),
