(1481211132347520,1,'每年公告发布数量统计',1,'lemon_demo','SELECT YEAR(COALESCE(RELEASE_TIME, CREATE_TIME)) AS `年份`,\n       COUNT(*) AS `发布数量`\nFROM lm_cms_content\nWHERE DEL_FLAG = 0\n  AND COALESCE(RELEASE_TIME, CREATE_TIME) IS NOT NULL\nGROUP BY YEAR(COALESCE(RELEASE_TIME, CREATE_TIME))\nORDER BY `年份`',NULL,NULL,2000,30,1,0,'yan','2026-09-24 17:31:46','yan','2026-09-24 17:31:46'),
(1493846748439680,1,'Demo - Monthly revenue',1,'lemon_demo','SELECT \'2026-07\' AS month, 44800 AS revenue\nUNION ALL SELECT \'2026-08\', 53600\nUNION ALL SELECT \'2026-09\', 64400\nORDER BY month',NULL,NULL,2000,30,1,0,'yan','2026-10-12 13:58:59','yan','2026-10-12 13:58:59');
