(1450948872324224,'cms公告内容查询',1,'',0,0,'visual',0,0,'yan','2026-08-12 23:23:02','yan','2026-08-26 10:10:26',6,'SELECT `lcc`.`CHANNEL_NAME` AS `栏目名称`, `lcc`.`CHANNEL_PATH` AS `栏目路径`, `lcc`.`SITE_ID` AS `所属站点`, `lcc`.`MODEL_ID` AS `模型`, `lcc2`.`CHANNEL_ID` AS `所属栏目`, `lcc2`.`TITLE` AS `标题`, `lcc2`.`PROJECT_CODE` AS `项目编号`, `lcc2`.`PROJECT_TYPE` AS `项目类型`, `lcm`.`MODEL_PATH` AS `模型路径`, `lcm`.`MODEL_NAME` AS `模型名称`, `lcm`.`SITE_ID` AS `所属站点`, `lcs`.`site_name` AS `站点名称`, `lcs`.`id` AS `主键`, `lcs`.`site_path` AS `站点资源路径`, `lcs`.`site_key` AS `站点标识`\nFROM `lemon_cms`.`lm_cms_channel` `lcc`\nLEFT JOIN `lemon_cms`.`lm_cms_content` `lcc2` ON `lcc2`.`CHANNEL_ID` = `lcc`.`ID`\nINNER JOIN `lemon_cms`.`lm_cms_model` `lcm` ON `lcc`.`MODEL_ID` = `lcm`.`ID`\nINNER JOIN `lemon_cms`.`lm_cms_site` `lcs` ON `lcc`.`SITE_ID` = `lcs`.`id`\nLIMIT 1000','2026-08-26 10:10:26','819486c860eeac1bebf6e6c011d3e465582897b7519d6eefb78f4ce61cefb174'),
(1459420543345792,'cms公告',1,'',0,0,'visual',0,0,'yan','2026-08-24 22:38:41','yan','2026-09-06 19:24:07',6,'SELECT `lcc`.`ID` AS `主键`, `lcc`.`CHANNEL_PATH` AS `栏目路径`, `lcc`.`CHANNEL_NAME` AS `栏目名称`, `lcc`.`MODEL_ID` AS `模型`, `lcc`.`SITE_ID` AS `所属站点`, `lcc`.`LINK` AS `外部链接`, `lcc`.`DISPLAY` AS `是否显示`, `lcc`.`ORDER_NUM` AS `排序`, `lcc`.`DESCRIPTION` AS `描述`, `lcc`.`CHANNEL_TYPE` AS `栏目分类`, `lcc`.`TYPE_DATA` AS `栏目分类值`, `lcc`.`BACKGROUND_IMG` AS `背景图`, `lcc`.`DEL_FLAG` AS `删除标识`, `lcc`.`CREATE_BY` AS `创建人`, `lcc`.`CREATE_TIME` AS `创建时间`, `lcc`.`UPDATE_BY` AS `更新人`, `lcc`.`UPDATE_TIME` AS `更新时间`, `lcc`.`PARENT_ID` AS `父节点id`, `lcc2`.`ID` AS `主键`, `lcc2`.`TITLE` AS `标题`, `lcc2`.`CHANNEL_ID` AS `所属栏目`, `lcc2`.`DESCRIPTION` AS `描述`, `lcc2`.`PROJECT_CODE` AS `项目编号`, `lcc2`.`PROJECT_TYPE` AS `项目类型`, `lcc2`.`AUTHOR` AS `作者`, `lcc2`.`ORIGIN` AS `来源`, `lcc2`.`AREA_NO` AS `所属地区`, `lcc2`.`LINK` AS `外部链接`, `lcc2`.`RELEASE_TIME` AS `发布时间`, `lcc2`.`ORDER_NUM` AS `排序`, `lcc2`.`SITE_ID` AS `所属站点`, `lcc2`.`MODEL_ID` AS `模型Id`, `lcc2`.`CONTENT_TYPE` AS `内容类型`, `lcc2`.`CONTENT_IMG` AS `单图上传`, `lcc2`.`DEL_FLAG` AS `删除标识`, `lcc2`.`CREATE_BY` AS `创建人`, `lcc2`.`CREATE_TIME` AS `创建时间`, `lcc2`.`UPDATE_BY` AS `更新人`, `lcc2`.`UPDATE_TIME` AS `更新时间`, `lcc2`.`LIKE_COUNT` AS `LIKE_COUNT`, `lcct`.`id` AS `id`, `lcct`.`txt` AS `txt`\nFROM `lemon_cms`.`lm_cms_channel` `lcc`\nLEFT JOIN `lemon_cms`.`lm_cms_content` `lcc2` ON `lcc2`.`CHANNEL_ID` = `lcc`.`ID`\nLEFT JOIN `lemon_cms`.`lm_cms_content_txt` `lcct` ON `lcc2`.`ID` = `lcct`.`id`\nWHERE `lcc`.`ID` = \'1\'\nGROUP BY `lcc`.`ID`\nLIMIT 1000','2026-09-06 19:24:07','ceeaf6d2064f5516b54b5dfa0f133efd72ec5551a74e2baad6fa7c06322b4fb8'),
(1468576265102464,'测试视图',1,'',0,0,'sql',0,0,'yan','2026-09-06 21:06:04','yan','2026-09-06 21:06:36',6,'SELECT\n  -- ========== 站点 lm_cms_site ==========\n  lcs.site_name                AS 站点名称,\n  lcs.id                       AS 站点主键,\n  lcs.site_key                 AS 站点标识,\n  lcs.site_path                AS 站点资源路径,\n  -- ========== 栏目 lm_cms_channel ==========\n  lcc.CHANNEL_NAME             AS 栏目名称,\n  lcc.CHANNEL_PATH             AS 栏目路径,\n  lcc.SITE_ID                  AS 栏目所属站点,\n  lcc.MODEL_ID                 AS 栏目模型,\n  -- ========== 模型 lm_cms_model ==========\n  lcm.MODEL_NAME               AS 模型名称,\n  lcm.MODEL_PATH               AS 模型路径,\n  lcm.SITE_ID                  AS 模型所属站点,\n  -- ========== 内容 lm_cms_content ==========\n  lcc2.CHANNEL_ID              AS 所属栏目,\n  lcc2.TITLE                   AS 标题,\n  lcc2.PROJECT_CODE            AS 项目编号,\n  lcc2.PROJECT_TYPE            AS 项目类型\nFROM lemon_cms.lm_cms_channel lcc\n  INNER JOIN lemon_cms.lm_cms_model lcm\n          ON lcm.ID = lcc.MODEL_ID\n         AND IFNULL(lcm.DEL_FLAG, 0) = 0          -- 模型软删除（库中存在 DEL_FLAG=2 的记录）\n  INNER JOIN lemon_cms.lm_cms_site lcs\n          ON lcs.id = lcc.SITE_ID\n         AND IFNULL(lcs.del_flag, 0) = 0          -- 站点软删除\n  LEFT JOIN lemon_cms.lm_cms_content lcc2\n          ON lcc2.CHANNEL_ID = lcc.ID\n         AND IFNULL(lcc2.DEL_FLAG, 0) = 0         -- 内容软删除\nWHERE IFNULL(lcc.DEL_FLAG, 0) = 0                 -- 栏目软删除\n  -- ========== 以下为按需勾选的筛选条件（取消注释并替换示例值） ==========\n  -- 【站点】\n  -- AND lcs.site_name LIKE CONCAT(\'%\', \'示例站点\', \'%\')\n  -- AND lcs.id = 1\n  -- AND lcs.site_key = \'main\'\n  -- AND lcs.site_path LIKE CONCAT(\'%\', \'/upload\', \'%\')\n  -- 【栏目】\n  -- AND lcc.CHANNEL_NAME LIKE CONCAT(\'%\', \'新闻\', \'%\')\n  -- AND lcc.CHANNEL_PATH LIKE \'/news%\'\n  -- AND lcc.SITE_ID IN (\'1\', \'2\')\n  -- AND lcc.MODEL_ID IN (1, 2)\n  -- 【模型】\n  -- AND lcm.MODEL_NAME LIKE CONCAT(\'%\', \'文章\', \'%\')\n  -- AND lcm.MODEL_PATH LIKE CONCAT(\'%\', \'article\', \'%\')\n  -- AND lcm.SITE_ID = lcc.SITE_ID                -- 只保留模型与栏目同站点的组合\n  -- 【内容】写在 WHERE 中 => 只返回“有匹配内容”的栏目行\n  -- AND lcc2.TITLE LIKE CONCAT(\'%\', \'公告\', \'%\')\n  -- AND lcc2.PROJECT_CODE LIKE CONCAT(\'%\', \'XM2024\', \'%\')\n  -- AND lcc2.PROJECT_TYPE IN (\'01\', \'02\')\n  -- AND lcc2.CHANNEL_ID = 10\n  -- 【内容】若希望保留无内容的栏目，把上面几条内容条件移到 LEFT JOIN 的 ON 里，\n  --        或用这一行替代： AND (lcc2.ID IS NULL OR lcc2.PROJECT_TYPE IN (\'01\',\'02\'))\nORDER BY lcs.id, lcc.ORDER_NUM, lcc2.RELEASE_TIME DESC\nLIMIT 1000',NULL,NULL);
