(3,1450948872324224,'cms公告内容查询','','{\"id\": 1450948872324224, \"items\": null, \"params\": {}, \"userId\": 1, \"delFlag\": 0, \"groupId\": 6, \"createBy\": \"yan\", \"isPublic\": 0, \"orderNum\": 0, \"updateBy\": \"yan\", \"configName\": \"cms公告内容查询\", \"createTime\": \"2026-08-12 23:23:02\", \"updateTime\": \"2026-08-26 10:02:27\", \"description\": \"\", \"canvasGroupIds\": null, \"selectDistinct\": 0, \"lastExecutedSql\": \"SELECT `lcc`.`CHANNEL_NAME` AS `栏目名称`, `lcc`.`CHANNEL_PATH` AS `栏目路径`, `lcc`.`SITE_ID` AS `所属站点`, `lcc`.`MODEL_ID` AS `模型`, `lcce`.`CHANNEL_TXT` AS `栏目内容`, `lcc2`.`CHANNEL_ID` AS `所属栏目`, `lcc2`.`TITLE` AS `标题`, `lcc2`.`PROJECT_CODE` AS `项目编号`, `lcc2`.`PROJECT_TYPE` AS `项目类型`, `lcm`.`MODEL_PATH` AS `模型路径`, `lcm`.`MODEL_NAME` AS `模型名称`, `lcm`.`SITE_ID` AS `所属站点`, `lcs`.`site_name` AS `站点名称`, `lcs`.`id` AS `主键`, `lcs`.`site_path` AS `站点资源路径`, `lcs`.`site_key` AS `站点标识`\\nFROM `lemon_cms`.`lm_cms_channel` `lcc`\\nLEFT JOIN `lemon_cms`.`lm_cms_channel_ext` `lcce` ON `lcc`.`ID` = `lcce`.`ID`\\nLEFT JOIN `lemon_cms`.`lm_cms_content` `lcc2` ON `lcc2`.`CHANNEL_ID` = `lcc`.`ID`\\nINNER JOIN `lemon_cms`.`lm_cms_model` `lcm` ON `lcc`.`MODEL_ID` = `lcm`.`ID`\\nINNER JOIN `lemon_cms`.`lm_cms_site` `lcs` ON `lcc`.`SITE_ID` = `lcs`.`id`\\nLIMIT 1000\", \"lastExecutedTime\": \"2026-08-26 09:53:20\", \"lastExecutedDigest\": \"50cae82ac789f9c49ef1fb451fcbb614d9c97f9830df05886876868f41238dff\"}','[{\"id\": 1, \"alias\": \"\", \"params\": {}, \"dbField\": null, \"delFlag\": 0, \"fieldId\": 1450935142204544, \"configId\": 1450948872324224, \"createBy\": \"yan\", \"orderNum\": 1, \"updateBy\": \"yan\", \"customSql\": \"\", \"queryType\": \"COLUMN\", \"createTime\": \"2026-08-12 23:23:02\", \"updateTime\": \"2026-08-12 23:23:02\", \"functionType\": null, \"sortDirection\": \"\", \"conditionValue\": \"\", \"conditionOperator\": null}, {\"id\": 2, \"alias\": \"\", \"params\": {}, \"dbField\": null, \"delFlag\": 0, \"fieldId\": 1450935142220928, \"configId\": 1450948872