(1452066609226880,'测试查询','select * from lm_cms_content  ;\r\n\r\nselect 1;\r\n\r\nSELECT\r\n  palace_name\r\nFROM\r\n  LM_ZI_WEI_AI_ANALYSIS_REPORT\r\nWHERE\r\n  (\r\n    member_id = 2\r\n    AND person_id = 1211562504160384\r\n    AND analysis_type = \'birth\'\r\n    AND api_type = \'SANHE\'\r\n    AND del_flag = 0\r\n    AND palace_name IS NOT NULL\r\n    AND palace_name <> \'\'\r\n    AND da_xian_order IS NULL\r\n    AND liu_nian IS NULL\r\n    AND liu_yue IS NULL\r\n    AND liu_ri IS NULL\r\n    AND liu_shi IS NULL\r\n  );\r\n\r\nSELECT\r\n  r.*,\r\n  p.NAME AS PERSON_NAME,\r\n  p.GENDER AS PERSON_GENDER,\r\n  p.BIRTH_DATE_TIME AS PERSON_BIRTH_DATE_TIME\r\nFROM\r\n  LM_ZI_WEI_AI_ANALYSIS_REPORT r\r\n  LEFT JOIN LM_ZI_WEI_PERSON p ON r.PERSON_ID = p.ID\r\nWHERE\r\n  r.MEMBER_ID = 2\r\n  AND r.PARAM_HASH = \'53d66bef280c2f9e06748732409c8ae52c80b488873791cae0758ce0f4f3d54b\'\r\n  AND r.DEL_FLAG = 0\r\nLIMIT\r\n  1;\r\n\r\n',1,'ctrs',NULL,NULL,1,NULL,0,0,'yan','2026-08-14 13:17:05','yan','2026-08-26 10:23:06'),
(1460501630788736,'保存查询测试','SELECT\r\n  palace_name\r\nFROM\r\n  LM_ZI_WEI_AI_ANALYSIS_REPORT\r\nWHERE (\r\n    member_id = 2\r\n    AND person_id = 1211562504160384\r\n    AND analysis_type = \'birth\'\r\n    AND api_type = \'SANHE\'\r\n    AND del_flag = 0\r\n    AND palace_name IS NOT NULL\r\n    AND palace_name <> \'\'\r\n    AND da_xian_order IS NULL\r\n    AND liu_nian IS NULL\r\n    AND liu_yue IS NULL\r\n    AND liu_ri IS NULL\r\n    AND liu_shi IS NULL\r\n  );\r\n\r\nSELECT\r\n  r.*,\r\n  p.NAME AS PERSON_NAME,\r\n  p.GENDER AS PERSON_GENDER,\r\n  p.BIRTH_DATE_TIME AS PERSON_BIRTH_DATE_TIME\r\nFROM\r\n  LM_ZI_WEI_AI_ANALYSIS_REPORT r\r\n  LEFT JOIN LM_ZI_WEI_PERSON p\r\n    ON r.PERSON_ID = p.ID\r\nWHERE r.MEMBER_ID = 2\r\n  AND r.PARAM_HASH = \'53d66bef280c2f9e06748732409c8ae52c80b488873791cae0758ce0f4f3d54b\'\r\n  AND r.DEL_FLAG = 0\r\nLIMIT 1;\r\n\r\n',1,'ctrs',NULL,NULL,1,NULL,0,0,'yan','2026-08-26 11:18:10','yan','2026-09-25 23:23:51'),
