(1467900969583744,1,1,'lemon_cms','SELECT (SELECT COUNT(*) FROM lm_cms_content) AS 总数, (SELECT COUNT(*) FROM lm_cms_content WHERE DEL_FLAG=0) AS 未删除, (SELECT COUNT(*) FROM lm_cms_content c LEFT JOIN lm_cms_content_txt t ON c.ID=t.id WHERE t.id IS NULL AND c.DEL_FLAG=0) AS 无正文;','b74ec9fd000c365233478e3d3cf24ddf','SELECT','agent_tool',1,NULL,1,8,'[\"lm_cms_content\",\"lm_cms_content_txt\"]',0,'2026-09-05 22:12:10'),
