(1467942807078016,1,1,'lemon_cms','SELECT YEAR(COALESCE(cc.RELEASE_TIME, cc.CREATE_TIME)) AS `年份`,\n       COUNT(*) AS `发布数量`\nFROM lm_cms_content cc\nJOIN lm_cms_channel ch ON cc.CHANNEL_ID = ch.ID\nWHERE cc.DEL_FLAG = 0\n  AND COALESCE(ch.DEL_FLAG, 0) = 0\n  AND ch.CHANNEL_NAME LIKE \'%公告%\'\nGROUP BY YEAR(COALESCE(cc.RELEASE_TIME, cc.CREATE_TIME))\nORDER BY `年份`','14be1af04b60651fde780f9f17998c81','SELECT','agent_tool',1,NULL,0,10,'[\"lm_cms_content\",\"lm_cms_channel\"]',0,'2026-09-05 23:37:17'),
(1467942833046656,1,1,'lemon_cms','SELECT\n  (SELECT COUNT(*) FROM lm_cms_channel WHERE CHANNEL_NAME LIKE \'%公告%\') AS 公告栏目数,\n  (SELECT COUNT(*) FROM lm_cms_channel WHERE CHANNEL_PATH LIKE \'%notice%\' OR CHANNEL_PATH LIKE \'%gonggao%\' OR CHANNEL_PATH LIKE \'%announce%\') AS 公告路径栏目数,\n  (SELECT COUNT(*) FROM lm_cms_model WHERE MODEL_NAME LIKE \'%公告%\' OR MODEL_PATH LIKE \'%notice%\') AS 公告模型数,\n  (SELECT COUNT(*) FROM lm_cms_content WHERE DEL_FLAG = 0) AS 有效内容数,\n  (SELECT COUNT(*) FROM lm_cms_content WHERE DEL_FLAG = 1) AS 已删内容数,\n  (SELECT COUNT(*) FROM lm_cms_content WHERE DEL_FLAG IS NULL) AS DEL_FLAG为空数','ec997c133b811c5fcd44dc288a01081b','SELECT','agent_tool',1,NULL,1,8,'[\"lm_cms_channel\",\"lm_cms_model\",\"lm_cms_content\"]',0,'2026-09-05 23:37:20'),
(1467942893077632,1,1,'lemon_cms','SELECT ID, CHANNEL_NAME, CHANNEL_PATH, PARENT_ID, DEL_FLAG FROM lm_cms_channel WHERE CHANNEL_NAME LIKE \'%告%\' OR CHANNEL_NAME LIKE \'%通知%\' OR CHANNEL_NAME LIKE \'%新闻%\' OR CHANNEL_PATH LIKE \'%notice%\' OR CHANNEL_PATH LIKE \'%news%\' OR CHANNEL_PATH LIKE \'%gg%\'','740a00a2757e449ac25444f21b10cd85','SELECT','agent_tool',1,NULL,2,8,'[\"lm_cms_channel\"]',0,'2026-09-05 23:37:28'),
(1467942983140480,1,1,'lemon_cms','SELECT\n  SUM(CASE WHEN ch.CHANNEL_NAME LIKE \'%公告%\' THEN 1 ELSE 0 END) AS 含公告,\n  SUM(CASE WHEN ch.CHANNEL_NAME LIKE \'%通知%\' THEN 1 ELSE 0 END) AS 含通知,\n  SUM(CASE WHEN ch.CHANNEL_NAME LIKE \'%新闻%\' THEN 1 ELSE 0 END) AS 含新闻,\n  SUM(CASE WHEN ch.CHANNEL_NAME LIKE \'%公告%\' OR ch.CHANNEL_NAME LIKE \'%通知%\' THEN 1 ELSE 0 END) AS 含公告或通知,\n  SUM(CASE WHEN ch.CHANNEL_PATH LIKE \'%notice%\' THEN 1 ELSE 0 END) AS 路径notice,\n  SUM(CASE WHEN ch.CHANNEL_PATH LIKE \'%news%\' THEN 1 ELSE 0 END) AS 路径news,\n  SUM(CASE WHEN ch.CHANNEL_PATH LIKE \'%gg%\' THEN 1 ELSE 0 END) AS 路径gg,\n  SUM(CASE WHEN ch.CHANNEL_PATH LIKE \'%tz%\' THEN 1 ELSE 0 END) AS 路径tz\nFROM lm_cms_content cc\nLEFT JOIN lm_cms_channel ch ON cc.CHANNEL_ID = ch.ID\nWHERE cc.DEL_FLAG = 0','aeed301337540e6bdf3023abb60bd270','SELECT','agent_tool',1,NULL,1,6,'[\"lm_cms_content\",\"lm_cms_channel\"]',0,'2026-09-05 23:37:39'),
