(1468573894132864,1,1,'lemon_data','SELECT\n  lcc.CHANNEL_NAME AS 栏目名称,\n  lcc.CHANNEL_PATH AS 栏目路径,\n  lcc.SITE_ID AS 所属站点,\n  lcc.MODEL_ID AS 模型,\n  lcc2.CHANNEL_ID AS 所属栏目,\n  lcc2.TITLE AS 标题,\n  lcc2.PROJECT_CODE AS 项目编号,\n  lcc2.PROJECT_TYPE AS 项目类型,\n  lcm.MODEL_PATH AS 模型路径,\n  lcm.MODEL_NAME AS 模型名称,\n  lcm.SITE_ID AS 模型所属站点,\n  lcs.site_name AS 站点名称,\n  lcs.id AS 站点主键,\n  lcs.site_path AS 站点资源路径,\n  lcs.site_key AS 站点标识\nFROM lemon_cms.lm_cms_channel lcc\n  INNER JOIN lemon_cms.lm_cms_model lcm ON lcm.ID = lcc.MODEL_ID AND IFNULL(lcm.DEL_FLAG,0) = 0\n  INNER JOIN lemon_cms.lm_cms_site lcs ON lcs.id = lcc.SITE_ID AND IFNULL(lcs.del_flag,0) = 0\n  LEFT JOIN lemon_cms.lm_cms_content lcc2 ON lcc2.CHANNEL_ID = lcc.ID AND IFNULL(lcc2.DEL_FLAG,0) = 0\nWHERE IFNULL(lcc.DEL_FLAG,0) = 0\n  AND lcc2.ID IS NOT NULL\n  AND lcs.site_key = \'main\'\n  AND lcc.CHANNEL_NAME LIKE CONCAT(\'%\', \'测试\', \'%\')\n  AND lcc.CHANNEL_PATH LIKE CONCAT(\'%\', \'/a\', \'%\')\n  AND lcm.MODEL_NAME LIKE CONCAT(\'%\', \'文章\', \'%\')\n  AND lcc2.TITLE LIKE CONCAT(\'%\', \'公告\', \'%\')\n  AND lcc2.PROJECT_CODE LIKE CONCAT(\'%\', \'XM\', \'%\')\n  AND lcc2.PROJECT_TYPE = \'01\'\nORDER BY lcs.id, lcc.ORDER_NUM, lcc2.RELEASE_TIME DESC\nLIMIT 1000','2d9741d526b87510ea8a4981bac13819','SELECT','agent_tool',1,NULL,0,25,'[\"lm_cms_channel\",\"lm_cms_model\",\"lm_cms_site\",\"lm_cms_content\"]',0,'2026-09-06 21:01:14'),
(1468573914154112,1,1,'lemon_data','SELECT COUNT(*) AS 行数\nFROM lemon_cms.lm_cms_channel lcc\n  INNER JOIN lemon_cms.lm_cms_model lcm ON lcm.ID = lcc.MODEL_ID AND IFNULL(lcm.DEL_FLAG,0) = 0\n  INNER JOIN lemon_cms.lm_cms_site lcs ON lcs.id = lcc.SITE_ID AND IFNULL(lcs.del_flag,0) = 0\n  LEFT JOIN lemon_cms.lm_cms_content lcc2 ON lcc2.CHANNEL_ID = lcc.ID AND IFNULL(lcc2.DEL_FLAG,0) = 0\nWHERE IFNULL(lcc.DEL_FLAG,0) = 0','481c314385a9aeec731bd97c519c3192','SELECT','agent_tool',1,NULL,1,7,'[\"lm_cms_channel\",\"lm_cms_model\",\"lm_cms_site\",\"lm_cms_content\"]',0,'2026-09-06 21:01:17'),
(1468573995353216,1,1,'lemon_data','SELECT\n  lcs.site_name AS 站点名称,\n  lcs.id AS 站点主键,\n  lcs.site_key AS 站点标识,\n  lcs.site_path AS 站点资源路径,\n  lcc.CHANNEL_NAME AS 栏目名称,\n  lcc.CHANNEL_PATH AS 栏目路径,\n  lcc.SITE_ID AS 栏目所属站点,\n  lcc.MODEL_ID AS 栏目模型,\n  lcm.MODEL_NAME AS 模型名称,\n  lcm.MODEL_PATH AS 模型路径,\n  lcm.SITE_ID AS 模型所属站点,\n  lcc2.CHANNEL_ID AS 所属栏目,\n  lcc2.TITLE AS 标题,\n  lcc2.PROJECT_CODE AS 项目编号,\n  lcc2.PROJECT_TYPE AS 项目类型\nFROM lemon_cms.lm_cms_channel lcc\n  INNER JOIN lemon_cms.lm_cms_model lcm\n          ON lcm.ID = lcc.MODEL_ID AND IFNULL(lcm.DEL_FLAG, 0) = 0\n  INNER JOIN lemon_cms.lm_cms_site lcs\n          ON lcs.id = lcc.SITE_ID AND IFNULL(lcs.del_flag, 0) = 0\n  LEFT JOIN lemon_cms.lm_cms_content lcc2\n          ON lcc2.CHANNEL_ID = lcc.ID AND IFNULL(lcc2.DEL_FLAG, 0) = 0\nWHERE IFNULL(lcc.DEL_FLAG, 0) = 0\n  -- ========== 站点 lm_cms_site ==========\n  -- AND lcs.site_name LIKE CONCAT(\'%\', \'示例站点\', \'%\')\n  -- AND lcs.id = 1\n  -- AND lcs.site_key = \'main\'\n  -- AND lcs.site_path LIKE CONCAT(\'%\', \'/upload\', \'%\')\n  -- ========== 栏目 lm_cms_channel ==========\n  -- AND lcc.CHANNEL_NAME LIKE CONCAT(\'%\', \'新闻\', \'%\')\n  -- AND lcc.CHANNEL_PATH LIKE \'/news%\'\n  -- AND lcc.SITE_ID IN (\'1\', \'2\')\n  -- AND lcc.MODEL_ID IN (1, 2)\n  -- ========== 模型 lm_cms_model ==========\n  -- AND lcm.MODEL_NAME LIKE CONCAT(\'%\', \'文章\', \'%\')\n  -- AND lcm.MODEL_PATH LIKE CONCAT(\'%\', \'article\', \'%\')\n  -- AND lcm.SITE_ID = lcs.id\n  -- ========== 内容 lm_cms_content（写在 ON 里则保留空栏目；写在 WHERE 里等价于只看有内容栏目） ==========\n  -- AND lcc2.TITLE LIKE CONCAT(\'%\', \'公告\', \'%\')\n  -- AND lcc2.PROJECT_CODE LIKE CONCAT(\'%\', \'XM2024\', \'%\')\n  -- AND lcc2.PROJECT_TYPE IN (\'01\', \'02\')\n  -- AND lcc2.CHANNEL_ID = 10\nORDER BY lcs.id, lcc.ORDER_NUM, lcc2.RELEASE_TIME DESC\nLIMIT 1000','b80485801cc4b43a30d9e9e235a16860','SELECT','agent_tool',1,NULL,45,7,'[\"lm_cms_channel\",\"lm_cms_model\",\"lm_cms_site\",\"lm_cms_content\"]',0,'2026-09-06 21:01:27'),
(1468575325553792,1,1,'lemon_data','SELECT\n  -- ========== 站点 lm_cms_site ==========\n  lcs.site_name                AS 站点名称,\n  lcs.id                       AS 站点主键,\n  lcs.site_key                 AS 站点标识,\n  lcs.site_path                AS 站点资源路径,\n  -- ========== 栏目 lm_cms_channel ==========\n  lcc.CHANNEL_NAME             AS 栏目名称,\n  lcc.CHANNEL_PATH             AS 栏目路径,\n  lcc.SITE_ID                  AS 栏目所属站点,\n  lcc.MODEL_ID                 AS 栏目模型,\n  -- ========== 模型 lm_cms_model ==========\n  lcm.MODEL_NAME               AS 模型名称,\n  lcm.MODEL_PATH               AS 模型路径,\n  lcm.SITE_ID                  AS 模型所属站点,\n  -- ========== 内容 lm_cms_content ==========\n  lcc2.CHANNEL_ID              AS 所属栏目,\n  lcc2.TITLE                   AS 标题,\n  lcc2.PROJECT_CODE            AS 项目编号,\n  lcc2.PROJECT_TYPE            AS 项目类型\nFROM lemon_cms.lm_cms_channel lcc\n  INNER JOIN lemon_cms.lm_cms_model lcm\n          ON lcm.ID = lcc.MODEL_ID\n         AND IFNULL(lcm.DEL_FLAG, 0) = 0          -- 模型软删除（库中存在 DEL_FLAG=2 的记录）\n  INNER JOIN lemon_cms.lm_cms_site lcs\n          ON lcs.id = lcc.SITE_ID\n         AND IFNULL(lcs.del_flag, 0) = 0          -- 站点软删除\n  LEFT JOIN lemon_cms.lm_cms_content lcc2\n          ON lcc2.CHANNEL_ID = lcc.ID\n         AND IFNULL(lcc2.DEL_FLAG, 0) = 0         -- 内容软删除\nWHERE IFNULL(lcc.DEL_FLAG, 0) = 0                 -- 栏目软删除\n  -- ========== 以下为按需勾选的筛选条件（取消注释并替换示例值） ==========\n  -- 【站点】\n  -- AND lcs.site_name LIKE CONCAT(\'%\', \'示例站点\', \'%\')\n  -- AND lcs.id = 1\n  -- AND lcs.site_key = \'main\'\n  -- AND lcs.site_path LIKE CONCAT(\'%\', \'/upload\', \'%\')\n  -- 【栏目】\n  -- AND lcc.CHANNEL_NAME LIKE CONCAT(\'%\', \'新闻\', \'%\')\n  -- AND lcc.CHANNEL_PATH LIKE \'/news%\'\n  -- AND lcc.SITE_ID IN (\'1\', \'2\')\n  -- AND lcc.MODEL_ID IN (1, 2)\n  -- 【模型】\n  -- AND lcm.MODEL_NAME LIKE CONCAT(\'%\', \'文章\', \'%\')\n  -- AND lcm.MODEL_PATH LIKE CONCAT(\'%\', \'article\', \'%\')\n  -- AND lcm.SITE_ID = lcc.SITE_ID                -- 只保留模型与栏目同站点的组合\n  -- 【内容】写在 WHERE 中 => 只返回“有匹配内容”的栏目行\n  -- AND lcc2.TITLE LIKE CONCAT(\'%\', \'公告\', \'%\')\n  -- AND lcc2.PROJECT_CODE LIKE CONCAT(\'%\', \'XM2024\', \'%\')\n  -- AND lcc2.PROJECT_TYPE IN (\'01\', \'02\')\n  -- AND lcc2.CHANNEL_ID = 10\n  -- 【内容】若希望保留无内容的栏目，把上面几条内容条件移到 LEFT JOIN 的 ON 里，\n  --        或用这一行替代： AND (lcc2.ID IS NULL OR lcc2.PROJECT_TYPE IN (\'01\',\'02\'))\nORDER BY lcs.id, lcc.ORDER_NUM, lcc2.RELEASE_TIME DESC\nLIMIT 1000','b80485801cc4b43a30d9e9e235a16860','SELECT','manual',1,NULL,45,13,'[\"lm_cms_channel\",\"lm_cms_model\",\"lm_cms_site\",\"lm_cms_content\"]',0,'2026-09-06 21:04:09'),
(1468576526779520,1,1,'lemon_data','SELECT\n  -- ========== 站点 lm_cms_site ==========\n  lcs.site_name                AS 站点名称,\n  lcs.id                       AS 站点主键,\n  lcs.site_key                 AS 站点标识,\n  lcs.site_path                AS 站点资源路径,\n  -- ========== 栏目 lm_cms_channel ==========\n  lcc.CHANNEL_NAME             AS 栏目名称,\n  lcc.CHANNEL_PATH             AS 栏目路径,\n  lcc.SITE_ID                  AS 栏目所属站点,\n  lcc.MODEL_ID                 AS 栏目模型,\n  -- ========== 模型 lm_cms_model ==========\n  lcm.MODEL_NAME               AS 模型名称,\n  lcm.MODEL_PATH               AS 模型路径,\n  lcm.SITE_ID                  AS 模型所属站点,\n  -- ========== 内容 lm_cms_content ==========\n  lcc2.CHANNEL_ID              AS 所属栏目,\n  lcc2.TITLE                   AS 标题,\n  lcc2.PROJECT_CODE            AS 项目编号,\n  lcc2.PROJECT_TYPE            AS 项目类型\nFROM lemon_cms.lm_cms_channel lcc\n  INNER JOIN lemon_cms.lm_cms_model lcm\n          ON lcm.ID = lcc.MODEL_ID\n         AND IFNULL(lcm.DEL_FLAG, 0) = 0          -- 模型软删除（库中存在 DEL_FLAG=2 的记录）\n  INNER JOIN lemon_cms.lm_cms_site lcs\n          ON lcs.id = lcc.SITE_ID\n         AND IFNULL(lcs.del_flag, 0) = 0          -- 站点软删除\n  LEFT JOIN lemon_cms.lm_cms_content lcc2\n          ON lcc2.CHANNEL_ID = lcc.ID\n         AND IFNULL(lcc2.DEL_FLAG, 0) = 0         -- 内容软删除\nWHERE IFNULL(lcc.DEL_FLAG, 0) = 0                 -- 栏目软删除\n  -- ========== 以下为按需勾选的筛选条件（取消注释并替换示例值） ==========\n  -- 【站点】\n  -- AND lcs.site_name LIKE CONCAT(\'%\', \'示例站点\', \'%\')\n  -- AND lcs.id = 1\n  -- AND lcs.site_key = \'main\'\n  -- AND lcs.site_path LIKE CONCAT(\'%\', \'/upload\', \'%\')\n  -- 【栏目】\n  -- AND lcc.CHANNEL_NAME LIKE CONCAT(\'%\', \'新闻\', \'%\')\n  -- AND lcc.CHANNEL_PATH LIKE \'/news%\'\n  -- AND lcc.SITE_ID IN (\'1\', \'2\')\n  -- AND lcc.MODEL_ID IN (1, 2)\n  -- 【模型】\n  -- AND lcm.MODEL_NAME LIKE CONCAT(\'%\', \'文章\', \'%\')\n  -- AND lcm.MODEL_PATH LIKE CONCAT(\'%\', \'article\', \'%\')\n  -- AND lcm.SITE_ID = lcc.SITE_ID                -- 只保留模型与栏目同站点的组合\n  -- 【内容】写在 WHERE 中 => 只返回“有匹配内容”的栏目行\n  -- AND lcc2.TITLE LIKE CONCAT(\'%\', \'公告\', \'%\')\n  -- AND lcc2.PROJECT_CODE LIKE CONCAT(\'%\', \'XM2024\', \'%\')\n  -- AND lcc2.PROJECT_TYPE IN (\'01\', \'02\')\n  -- AND lcc2.CHANNEL_ID = 10\n  -- 【内容】若希望保留无内容的栏目，把上面几条内容条件移到 LEFT JOIN 的 ON 里，\n  --        或用这一行替代： AND (lcc2.ID IS NULL OR lcc2.PROJECT_TYPE IN (\'01\',\'02\'))\nORDER BY lcs.id, lcc.ORDER_NUM, lcc2.RELEASE_TIME DESC\nLIMIT 1000','b80485801cc4b43a30d9e9e235a16860','SELECT','manual',1,NULL,45,9,'[\"lm_cms_channel\",\"lm_cms_model\",\"lm_cms_site\",\"lm_cms_content\"]',0,'2026-09-06 21:06:36'),
