(1473510127666304,1,1,'lemon_cms','SELECT c.CHANNEL_NAME AS `栏目名称`, cp.CHANNEL_NAME AS `上级栏目`, COUNT(ct.ID) AS `已发布公告数`\nFROM lm_cms_channel c\nLEFT JOIN lm_cms_channel cp ON cp.ID = c.PARENT_ID\nLEFT JOIN lm_cms_content ct ON ct.CHANNEL_ID = c.ID AND IFNULL(ct.DEL_FLAG,0) = 0 AND ct.RELEASE_TIME IS NOT NULL\nWHERE IFNULL(c.DEL_FLAG,0) = 0\nGROUP BY c.ID, c.CHANNEL_NAME, cp.CHANNEL_NAME\nORDER BY `已发布公告数` DESC, c.CHANNEL_NAME ASC\nLIMIT 50','0eb9013e2ec3e305a243b78dc4bdfa3d','SELECT','agent_tool',1,NULL,36,10,'[\"lm_cms_channel\",\"lm_cms_content\"]',0,'2026-09-13 20:24:02'),
(1473524942046336,1,1,'lemon_cms','SELECT CONCAT(IFNULL(cp.CHANNEL_NAME,\'\'), IF(cp.CHANNEL_NAME IS NULL,\'\', \' / \'), c.CHANNEL_NAME) AS `栏目名称`,\n       IFNULL(cp.CHANNEL_NAME, \'顶级栏目\') AS `所属上级`,\n       COUNT(ct.ID) AS `已发布公告数`\nFROM lm_cms_channel c\nLEFT JOIN lm_cms_channel cp ON cp.ID = c.PARENT_ID\nLEFT JOIN lm_cms_content ct\n       ON ct.CHANNEL_ID = c.ID\n      AND IFNULL(ct.DEL_FLAG,0) = 0\n      AND ct.RELEASE_TIME IS NOT NULL\nWHERE IFNULL(c.DEL_FLAG,0) = 0\nGROUP BY c.ID, c.CHANNEL_NAME, cp.CHANNEL_NAME\nHAVING `已发布公告数` > 0\nORDER BY `已发布公告数` DESC, `栏目名称` ASC\nLIMIT 100','4ecfd49b713dc2e9e180f2323836af5a','SELECT','agent_tool',1,NULL,9,9,'[\"lm_cms_channel\",\"lm_cms_content\"]',0,'2026-09-13 20:54:10'),
