(1490246674457728,1,1,'lemon_db_client','-- ---------------------------------------------------------------------\r\n-- 1) 分享链接表\r\n-- ---------------------------------------------------------------------\r\nCREATE TABLE IF NOT EXISTS `LM_BI_SCREEN_SHARE` (\r\n  `ID` bigint(20) NOT NULL COMMENT \'主键（雪花）\',\r\n  `SCREEN_ID` bigint(20) NOT NULL COMMENT \'大屏ID\',\r\n  `CREATOR_USER_ID` bigint(20) NOT NULL COMMENT \'创建者（=大屏所有者）；匿名访问的数据身份\',\r\n  `TOKEN` varchar(64) NOT NULL COMMENT \'随机令牌（32字节 base64url，43位）\',\r\n  `NAME` varchar(64) DEFAULT NULL COMMENT \'链接名称（备注用途）\',\r\n  `DATA_MODE` varchar(16) NOT NULL DEFAULT \'SNAPSHOT\' COMMENT \'SNAPSHOT=快照（默认） LIVE=以创建者身份实时查询\',\r\n  `SNAPSHOT_ID` bigint(20) DEFAULT NULL COMMENT \'实时大屏的分享专用快照ID（定时快照大屏跟随大屏快照，为空）\',\r\n  `SNAPSHOT_VERSION_ID` bigint(20) DEFAULT NULL COMMENT \'分享快照对应的发布版本ID\',\r\n  `SNAPSHOT_TIME` datetime DEFAULT NULL COMMENT \'分享快照生成时间\',\r\n  `PASSWORD_HASH` varchar(100) DEFAULT NULL COMMENT \'访问密码 BCrypt 哈希，空=无密码\',\r\n  `EXPIRE_TIME` datetime DEFAULT NULL COMMENT \'过期时间，空=永久\',\r\n  `ALLOWED_HOSTS` varchar(1000) DEFAULT NULL COMMENT \'允许嵌入(iframe)的站点，逗号分隔；空=不允许外站嵌入\',\r\n  `STATUS` varchar(16) NOT NULL DEFAULT \'ACTIVE\' COMMENT \'ACTIVE/DISABLED/REVOKED（撤销为终态）\',\r\n  `VIEW_COUNT` bigint(20) NOT NULL DEFAULT 0 COMMENT \'浏览次数（首屏加载计数，自动刷新不计）\',\r\n  `DENIED_COUNT` bigint(20) NOT NULL DEFAULT 0 COMMENT \'被拒绝次数（密码错误/限流/过期/撤销等）\',\r\n  `LAST_ACCESS_TIME` datetime DEFAULT NULL COMMENT \'最后访问时间\',\r\n  `REVOKE_TIME` datetime DEFAULT NULL COMMENT \'撤销时间\',\r\n  `CREATE_BY` varchar(64) DEFAULT NULL,\r\n  `CREATE_TIME` datetime DEFAULT NULL,\r\n  `UPDATE_BY` varchar(64) DEFAULT NULL,\r\n  `UPDATE_TIME` datetime DEFAULT NULL,\r\n  PRIMARY KEY (`ID`),\r\n  UNIQUE KEY `UK_BI_SCREEN_SHARE_TOKEN` (`TOKEN`),\r\n  KEY `IDX_BI_SCREEN_SHARE_SCREEN` (`SCREEN_ID`, `STATUS`)\r\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT=\'数据大屏分享链接\'','fa9dcbbd62a6c1cbe76e519132e08069','DDL','manual',1,NULL,0,284,'[\"LM_BI_SCREEN_SHARE\"]',0,'2026-10-07 11:54:37'),
(1490246722577536,1,1,'lemon_db_client','-- ---------------------------------------------------------------------\r\n-- 2) 操作权限 BiScreen:share\r\n--    菜单：优先取已挂载 BiScreen 模块的菜单，其次按名称/路径兜底\r\n-- ---------------------------------------------------------------------\r\nSET @bi_menu := (\r\n  SELECT menu_id FROM (\r\n    SELECT mm.menu_id, 0 AS prio FROM sys_menu_module mm WHERE mm.module_code = \'BiScreen\'\r\n    UNION ALL\r\n    SELECT m.menu_id, 1 AS prio FROM sys_menu m\r\n    WHERE m.path IN (\'/visual/dashboard\', \'dashboard\') OR m.component LIKE \'%visual/dashboard/index%\'\r\n  ) t ORDER BY prio, menu_id LIMIT 1\r\n)','8c4ec902f416420df720af1305bf44e3','SELECT','manual',0,'仅允许执行 SELECT / SHOW / DESCRIBE / EXPLAIN / PRAGMA 类只读语句',NULL,8,'[\"sys_menu_module\",\"sys_menu\"]',0,'2026-10-07 11:54:43'),
(1490264400807040,1,1,'lemon_db_client','INSERT INTO sys_operation (id, menu_id, module_code, operation_name, operation_code, method, res_url, del_flag)\r\nSELECT @op_id, @bi_menu, \'BiScreen\', \'分享大屏\', \'share\', \'shareSave\', \'/admin/biScreen/share/save\', 0 FROM DUAL\r\nWHERE @bi_menu IS NOT NULL\r\n  AND NOT EXISTS (SELECT 1 FROM sys_operation WHERE module_code = \'BiScreen\' AND operation_code = \'share\' AND del_flag = 0)','8a1ac4858cca0293adfaa32a85eda5fc','DML','manual',1,NULL,0,5,'[\"sys_operation\",\"DUAL\"]',0,'2026-10-07 12:30:41'),
(1490264471102592,1,1,'lemon_db_client','SET @op_id := (SELECT IFNULL(MAX(id), 0) + 1 FROM sys_operation)','0b42add1809f293463d92fcf36de819e','SELECT','manual',0,'仅允许执行 SELECT / SHOW / DESCRIBE / EXPLAIN / PRAGMA 类只读语句',NULL,4,'[\"sys_operation\"]',0,'2026-10-07 12:30:50'),
(1490293337908352,1,1,'lemon_db_client','-- 若 @bi_menu 为空（未找到大屏菜单）以上不会插入：请先 SET @bi_menu := <大屏菜单ID>; 再执行本段。\r\n-- 管理员拥有 * 权限无需授权；普通用户需要在「角色管理」里给角色勾选「分享大屏」，重新登录后生效。\r\n-- 可选（默认不执行）：给已拥有「发布大屏」(BiScreen:publish) 的角色同时授予分享权限\r\n-- （若 sys_role_operation 需要显式 id 列，请参照其他脚本补上）：\r\n-- INSERT INTO sys_role_operation (role_id, opera_id)\r\n-- SELECT DISTINCT ro.role_id, s.id\r\n--   FROM sys_role_operation ro\r\n--   JOIN sys_operation p ON p.id = ro.opera_id AND p.module_code = \'BiScreen\' AND p.operation_code = \'publish\' AND p.del_flag = 0\r\n--   JOIN sys_operation s ON s.module_code = \'BiScreen\' AND s.operation_code = \'share\' AND s.del_flag = 0\r\n--  WHERE NOT EXISTS (SELECT 1 FROM sys_role_operation x WHERE x.role_id = ro.role_id AND x.opera_id = s.id);\r\n\r\n-- ---------------------------------------------------------------------\r\n-- 校验\r\n-- ---------------------------------------------------------------------\r\nSELECT COUNT(1) AS share_table_exists FROM information_schema.TABLES\r\nWHERE TABLE_SCHEMA = DATABASE() AND UPPER(TABLE_NAME) = \'LM_BI_SCREEN_SHARE\'','e88844d50e6c3e023ebcedde6117ccfc','SELECT','manual',1,NULL,1,7,'[\"sys_role_operation\",\"sys_operation\",\"TABLES\"]',0,'2026-10-07 13:29:35'),
