(5476,'数据大屏',2,'com.lemon.agent.dashboard.controller.BiScreenController.saveDraft()','POST',1,'system','','/lmdb/admin/biScreen/saveDraft','0:0:0:0:0:0:0:1','未知','{\"id\":1474306468758656,\"name\":\"未命名大屏\",\"description\":\"\",\"config\":{\"schemaVersion\":1,\"width\":1200,\"height\":675,\"background\":\"#0b1220\",\"widgets\":[{\"id\":\"w_1789438743036_w5i98\",\"chartId\":1473510231262336,\"title\":\"各栏目已发布公告数量\",\"chartSpec\":{\"chartType\":\"bar\",\"xField\":\"栏目名称\",\"yFields\":[\"已发布公告数\"],\"seriesField\":null,\"stack\":false,\"xAxisLabel\":\"栏目\",\"yAxisLabel\":\"公告数量\",\"valueFormat\":\"number\",\"sortBy\":\"已发布公告数\",\"sortOrder\":\"desc\",\"description\":\"统计口径：以 lm_cms_channel（未删除栏目）为主表，左联 lm_cms_content 统计各栏目下 DEL_FLAG=0 且 RELEASE_TIME 非空（即已发布）的内容条数；上级栏目仅作辅助识别同名子栏目。\"},\"data\":{\"dbConfigId\":1,\"instanceName\":\"lemon_cms\",\"sqlText\":\"SELECT c.CHANNEL_NAME AS `栏目名称`,\\n       IFNULL(cp.CHANNEL_NAME, \'-\') AS `上级栏目`,\\n       COUNT(ct.ID) AS `已发布公告数`\\nFROM lm_cms_channel c\\nLEFT JOIN lm_cms_channel cp ON cp.ID = c.PARENT_ID\\nLEFT JOIN lm_cms_content ct\\n       ON ct.CHANNEL_ID = c.ID\\n      AND IFNULL(ct.DEL_FLAG, 0) = 0\\n      AND ct.RELEASE_TIME IS NOT NULL\\nWHERE IFNULL(c.DEL_FLAG, 0) = 0\\nGROUP BY c.ID, c.CHANNEL_NAME, cp.CHANNEL_NAME\\nORDER BY `已发布公告数` DESC, `栏目名称` ASC\\nLIMIT 100\",\"maxRows\":2000,\"timeoutSeconds\":30},\"x\":30,\"y\":30,\"w\":420,\"h\":260},{\"id\":\"w_1789438746931_nstf0\",\"chartId\":1467948409119872,\"title\":\"每年公告发布数量统计\",\"chartSpec\":{\"chartType\":\"bar\",\"xField\":\"年份\",\"yFields\":[\"发布数量\"],\"seriesField\":null,\"stack\":false,\"xAxisLabel\":\"年份\",\"yAxisLabel\":\"发布数量\",\"valueFormat\":\"number\",\"sortBy\":\"asc\",\"sortOrder\":\"asc\",\"description\":\"按发布年份统计 CMS 公告（内容）发布数量，已排除软删除数据（DEL_FLAG=0），不区分栏目/子栏目。\"},\"data\":{\"dbConfigId\":1,\"instanceName\":\"lemon_demo\",\"sqlText\":\"SELECT YEAR(COALESCE(RELEASE_TIME, CREATE_TIME)) AS `年份`,\\n       COUNT(*) AS `发布数量`\\nFROM lm_cms_content\\nWHERE DEL_FLAG = 0\\n  AND COALESCE(RELEASE_TIME, CREATE_TIME) IS NOT NULL\\nGROUP BY YEAR(COALESCE(RELEASE_TIME, CREATE_TIME))\\nORDER BY `年份`\",\"maxRows\":2000,\"timeoutSeconds\":30},\"x\":490,\"y\":32,\"w\":224,\"h\":184}]},\"draftRevision\":1,\"refreshMode\":\"LIVE\",\"refreshIntervalSeconds\":300}','{\"code\":200,\"msg\":\"common.success\",\"data\":{\"createBy\":\"yan\",\"createTime\":\"2026-09-14 23:24:11\",\"updateBy\":\"yan\",\"updateTime\":\"2026-09-14 23:24:11\",\"params\":{},\"id\":1474306468758656,\"ownerUserId\":1,\"name\":\"未命名大屏\",\"description\":\"\",\"status\":\"DRAFT\",\"draftRevision\":2,\"publishedVersionId\":null,\"currentSnapshotId\":null,\"refreshMode\":\"LIVE\",\"refreshIntervalSeconds\":300,\"nextRefreshTime\":null,\"lastRefreshTime\":null,\"lastRefreshStatus\":null,\"lastRefreshError\":null,\"leaseUntil\":null,\"delFlag\":0,\"config\":{\"schemaVersion\":1,\"width\":1200,\"height\":675,\"background\":\"#0b1220\",\"widgets\":[{\"id\":\"w_1789438743036_w5i98\",\"chartId\":1473510231262336,\"title\":\"各栏目已发布公告数量\",\"chartSpec\":{\"chartType\":\"bar\",\"xField\":\"栏目名称\",\"yFields\":[\"已发布公告数\"],\"seriesField\":null,\"stack\":false,\"xAxisLabel\":\"栏目\",\"yAxisLabel\":\"公告数量\",\"valueFormat\":\"number\",\"sortBy\":\"已发布公告数\",\"sortOrder\":\"desc\",\"description\":\"统计口径：以 lm_cms_channel（未删除栏目）为主表，左联 lm_cms_content 统计各栏目下 DEL_FLAG=0 且 RELEASE_TIME 非空（即已发布）的内容条数；上级栏目仅作辅助识别同名子栏目。\"},\"data\":{\"dbConfigId\":1,\"instanceName\":\"lemon_cms\",\"sqlText\":\"SELECT c.CHANNEL_NAME AS `栏目名称`,\\n       IFNULL(cp.CHANNEL_NAME, \'-\') AS `上级栏目`,\\n       COUNT(ct.ID) AS `已发布公告数`\\nFROM lm_cms_channel c\\nLEFT JOIN lm_cms_channel cp ON cp.ID = c.PARENT_ID\\nLEFT JOIN lm_cms_content ct\\n       ON ct.CHANNEL_ID = c.ID\\n      AND IFNULL(ct.DEL_FLAG, 0) = 0\\n      AND ct.RELEASE_TIME IS NOT NULL\\nWHERE IFNULL(c.DEL_FLAG, 0) = 0\\nGROUP BY c.ID, c.CHANNEL_NAME, cp.CHANNEL_NAME\\nORDER BY `已发布公告数` DESC, `栏目名称` ASC\\nLIMIT 100\",\"maxRows\":2000,\"timeoutSeconds\":30},\"x\