(5933,'执行自由SQL',0,'com.lemon.vq.controller.DataBaseOperateController.executeSql()','POST',1,'system','','/lmdb/admin/dataBaseOperate/executeSql','0:0:0:0:0:0:0:1','未知','{\"dbConfigId\":5,\"instanceName\":\"lemon_db_client\",\"sql\":\"SELECT * FROM \\\"public\\\".\\\"lm_ai_chart\\\" LIMIT 200\",\"maxRows\":200,\"requestId\":\"sql-1790085052483-zaa72cmx\",\"source\":\"manual\"}','{\"code\":200,\"msg\":\"common.success\",\"data\":{\"columns\":[\"ID\",\"USER_ID\",\"DB_CONFIG_ID\",\"INSTANCE_NAME\",\"TITLE\",\"SQL_TEXT\",\"CHART_SPEC\",\"CONVERSATION_ID\",\"DEL_FLAG\",\"CREATE_BY\",\"CREATE_TIME\",\"UPDATE_BY\",\"UPDATE_TIME\",\"DATASET_ID\",\"SOURCE_TYPE\",\"SPEC_VERSION\",\"REVISION\",\"DESCRIPTION\"],\"columnTables\":[\"lm_ai_chart\",\"lm_ai_chart\",\"lm_ai_chart\",\"lm_ai_chart\",\"lm_ai_chart\",\"lm_ai_chart\",\"lm_ai_chart\",\"lm_ai_chart\",\"lm_ai_chart\",\"lm_ai_chart\",\"lm_ai_chart\",\"lm_ai_chart\",\"lm_ai_chart\",\"lm_ai_chart\",\"lm_ai_chart\",\"lm_ai_chart\",\"lm_ai_chart\",\"lm_ai_chart\"],\"rows\":[{\"ID\":1467948409119872,\"USER_ID\":1,\"DB_CONFIG_ID\":1,\"INSTANCE_NAME\":\"lemon_demo\",\"TITLE\":\"每年公告发布数量统计\",\"SQL_TEXT\":\"SELECT YEAR(COALESCE(RELEASE_TIME, CREATE_TIME)) AS `年份`,\\n       COUNT(*) AS `发布数量`\\nFROM lm_cms_content\\nWHERE DEL_FLAG = 0\\n  AND COALESCE(RELEASE_TIME, CREATE_TIME) IS NOT NULL\\nGROUP BY YEAR(COALESCE(RELEASE_TIME, CREATE_TIME))\\nORDER BY `年份`\",\"CHART_SPEC\":\"{\\\"chartType\\\":\\\"bar\\\",\\\"xField\\\":\\\"年份\\\",\\\"yFields\\\":[\\\"发布数量\\\"],\\\"seriesField\\\":null,\\\"stack\\\":null,\\\"xAxisLabel\\\":\\\"年份\\\",\\\"yAxisLabel\\\":\\\"发布数量\\\",\\\"valueFormat\\\":\\\"number\\\",\\\"sortBy\\\":\\\"asc\\\",\\\"sortOrder\\\":\\\"asc\\\",\\\"description\\\":\\\"按发布年份统计 CMS 公告（内容）发布数量，已排除软删除数据（DEL_FLAG=0），不区分栏目/子栏目。\\\"}\",\"CONVERSATION_ID\":null,\"DEL_FLAG\":0,\"CREATE_BY\":\"yan\",\"CREATE_TIME\":\"2026-09-05 23:48:41\",\"UPDATE_BY\":\"yan\",\"UPDATE_TIME\":\"2026-09-05 23:48:41\",\"DATASET_ID\":null,\"SOURCE_TYPE\":\"AI\",\"SPEC_VERSION\":1,\"REVISION\":1,\"DESCRIPTION\":null},{\"ID\":1473510231262336,\"USER_ID\":1,\"DB_CONFIG_ID\":1,\"INSTANCE_NAME\":\"lemon_cms\",\"TITLE\":\"各栏目已发布公告数量\",\"SQL_TEXT\":\"SELECT c.CHANNEL_NAME AS `栏目名称`,\\n       IFNULL(cp.CHANNEL_NAME, \'-\') AS `上级栏目`,\\n       COUNT(ct.ID) AS `已发布公告数`\\nFROM lm_cms_channel c\\nLEFT JOIN lm_cms_channel cp ON cp.ID = c.PARENT_ID\\nLEFT JOIN lm_cms_content ct\\n       ON ct.CHANNEL_ID = c.ID\\n      AND IFNULL(ct.DEL_FLAG, 0) = 0\\n      AND ct.RELEASE_TIME IS NOT NULL\\nWHERE IFNULL(c.DEL_FLAG, 0) = 0\\nGROUP BY c.ID, c.CHANNEL_NAME, cp.CHANNEL_NAME\\nORDER BY `已发布公告数` DES',0,'','2026-09-22 21:50:53'),
