(6037,'分步执行SQL',0,'com.lemon.vq.controller.DataBaseOperateController.executeSqlBatch()','POST',1,'system','','/lmdb/admin/dataBaseOperate/executeSqlBatch','10.10.10.200','未知','{\"dbConfigId\":1,\"instanceName\":\"yongfeng_system_v2\",\"sql\":\"-- yanch：文件默认私有，企业归属由可信业务绑定；不猜测历史文件归属。\\r\\nALTER TABLE lm_attachment ADD COLUMN enterprise_id BIGINT NULL;\\r\\nCREATE INDEX idx_attachment_enterprise ON lm_attachment (enterprise_id, del_flag);\\r\\n-- 仅用现有企业资料的唯一引用作为证据；跨企业共用或未引用的旧文件仍留空，人工核对。\\r\\nUPDATE lm_attachment a SET enterprise_id = (\\r\\n    SELECT MIN(e.id) FROM yf_enterprise e WHERE e.logo_file_id = a.id OR e.license_file_id = a.id\\r\\n) WHERE enterprise_id IS NULL AND (\\r\\n    SELECT COUNT(DISTINCT e.id) FROM yf_enterprise e WHERE e.logo_file_id = a.id OR e.license_file_id = a.id\\r\\n) = 1;\",\"maxRows\":200,\"requestId\":\"sql-1791259869170-f4h6uu65\",\"source\":\"manual\"}','{\"code\":200,\"msg\":\"common.success\",\"data\":{\"items\":[{\"index\":1,\"sql\":\"ALTER TABLE lm_attachment ADD COLUMN enterprise_id BIGINT NULL\",\"kind\":\"ddl\",\"success\":true,\"error\":null,\"columns\":[],\"columnTables\":[],\"rows\":[],\"rowCount\":0,\"affectedRows\":0,\"elapsedMs\":357,\"message\":\"DDL/CALL OK, 0 row(s) affected\"},{\"index\":2,\"sql\":\"CREATE INDEX idx_attachment_enterprise ON lm_attachment (enterprise_id, del_flag)\",\"kind\":\"ddl\",\"success\":true,\"error\":null,\"columns\":[],\"columnTables\":[],\"rows\":[],\"rowCount\":0,\"affectedRows\":0,\"elapsedMs\":214,\"message\":\"DDL/CALL OK, 0 row(s) affected\"},{\"index\":3,\"sql\":\"UPDATE lm_attachment a SET enterprise_id = (\\r\\n    SELECT MIN(e.id) FROM yf_enterprise e WHERE e.logo_file_id = a.id OR e.license_file_id = a.id\\r\\n) WHERE enterprise_id IS NULL AND (\\r\\n    SELECT COUNT(DISTINCT e.id) FROM yf_enterprise e WHERE e.logo_file_id = a.id OR e.license_file_id = a.id\\r\\n) = 1\",\"kind\":\"dml\",\"success\":true,\"error\":null,\"columns\":[],\"columnTables\":[],\"rows\":[],\"rowCount\":2,\"af