_issue_history (tenant_id, rule_id, create_time, id)\\r\\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;\",\"maxRows\":200,\"requestId\":\"sql-1791259896644-rr4kkha2\",\"source\":\"manual\"}','{\"code\":200,\"msg\":\"common.success\",\"data\":{\"items\":[{\"index\":1,\"sql\":\"CREATE TABLE yf_code_rule (\\r\\n id BIGINT NOT NULL PRIMARY KEY, tenant_id BIGINT NOT NULL, app_code VARCHAR(50) NOT NULL, rule_code VARCHAR(50) NOT NULL,\\r\\n name VARCHAR(100) NOT NULL, business_type VARCHAR(100) NOT NULL DEFAULT \'\', prefix VARCHAR(40) NOT NULL DEFAULT \'\',\\r\\n date_pattern VARCHAR(20) NOT NULL DEFAULT \'\', separator VARCHAR(1) NOT NULL DEFAULT \'-\',\\r\\n sequence_width INT NOT NULL, start_value BIGINT NOT NULL, step INT NOT NULL, reset_period VARCHAR(10) NOT NULL,\\r\\n enabled INT NOT NULL DEFAULT 1, del_flag INT NOT NULL DEFAULT 0,\\r\\n create_by VARCHAR(64), create_time DATETIME, update_by VARCHAR(64), update_time DATETIME,\\r\\n UNIQUE KEY uk_code_rule_scope (tenant_id, app_code, rule_code)\\r\\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4\",\"kind\":\"ddl\",\"success\":false,\"error\":\"执行 SQL 失败: You have an error in your SQL syntax; check the manual that corresponds to your MySQL server version for the right syntax to use near \'separator VARCHAR(1) NOT NULL DEFAULT \'-\',\\r\\n sequence_width INT NOT NULL, start_\' at line 4\",\"columns\":[],\"columnTables\":[],\"rows\":[],\"rowCount\":0,\"affectedRows\":null,\"elapsedMs\":null,\"message\":null}],\"stopped\":true,\"elapsedMs\":46,\"message\":\"已分步执行 1/3 条，成功 0 条，第 1 条停止：执行 SQL 失败: You have an error in your SQL syntax; check the manual that corresponds to your MySQL server version for the right syntax to use near \'separator VARCHAR(1) NOT NULL DEFAULT \'-\',\\r\\n sequence_width INT NOT NULL, start_\' at line 4\"}}',0,'','2026-10-06 12:11:38'),
