(6042,'分步执行SQL',0,'com.lemon.vq.controller.DataBaseOperateController.executeSqlBatch()','POST',1,'system','','/lmdb/admin/dataBaseOperate/executeSqlBatch','10.10.10.200','未知','{\"dbConfigId\":1,\"instanceName\":\"yongfeng_system_v2\",\"sql\":\"-- yanch：当前企业ID不变；历史行新ID，通过base_id关联固定主行。\\r\\nALTER TABLE yf_enterprise ADD COLUMN base_id BIGINT NOT NULL DEFAULT 0;\\r\\nALTER TABLE yf_enterprise ADD COLUMN version_no INT NOT NULL DEFAULT 0;\\r\\nALTER TABLE yf_enterprise ADD COLUMN effective_time DATETIME NULL;\\r\\nALTER TABLE yf_enterprise ADD COLUMN archived_time DATETIME NULL;\\r\\nUPDATE yf_enterprise SET base_id=id;\\r\\n-- 历史副本复用信用代码；唯一性只约束当前主行，不影响防重复入驻。\\r\\nALTER TABLE yf_enterprise ADD COLUMN current_credit_code VARCHAR(32)\\r\\n  GENERATED ALWAYS AS (CASE WHEN id=base_id THEN unified_social_credit_code ELSE NULL END) STORED;\\r\\nCREATE UNIQUE INDEX uk_enterprise_current_uscc ON yf_enterprise(current_credit_code);\\r\\nDROP INDEX uk_enterprise_uscc ON yf_enterprise;\\r\\nALTER TABLE yf_enterprise ADD COLUMN history_version INT\\r\\n  GENERATED ALWAYS AS (CASE WHEN id<>base_id THEN version_no ELSE NULL END) STORED;\\r\\nCREATE UNIQUE INDEX uk_enterprise_history_version ON yf_enterprise(base_id,history_version);\\r\\nCREATE INDEX idx_enterprise_base_version ON yf_enterprise(base_id,version_no);\\r\\n\\r\\n-- 企业业务自己管理文件引用，公共附件表不承载企业字段。\\r\\nCREATE TABLE yf_enterprise_attachment (\\r\\n  file_id VARCHAR(64) NOT NULL PRIMARY KEY,\\r\\n  base_id BIGINT NOT NULL,\\r\\n  tenant_id BIGINT NOT NULL,\\r\\n  bind_by BIGINT NULL,\\r\\n  bind_time DATETIME NULL,\\r\\n  KEY idx_enterprise_attachment_base(base_id)\\r\\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT=\'企业材料引用（固定企业主ID，保留历史引用）\';\\r\\n-- 先完整迁出上批确立的归属，之后再删除旧列；不改写V20261011校验和。\\r\\nINSERT INTO yf_enterprise_attachment(file_id,base_id,tenant_id,bind_time)\\r\\nSELECT a.id,a.enterprise_id,a.enterprise_id,NOW() FROM lm_attachment a\\r\\nWHERE a.enterprise_id IS NOT NULL;\",\"maxRows\":200,\"requestId\":\"sql-17912635