, body VARCHAR(256) NOT NULL,\\r\\n way_code VARCHAR(32) NOT NULL, state VARCHAR(20) NOT NULL, pay_order_id VARCHAR(64),\\r\\n pay_data_type VARCHAR(32), pay_data TEXT, attempts INT NOT NULL DEFAULT 0, next_try DATETIME(3), lease_until D','{\"code\":200,\"msg\":\"common.success\",\"data\":{\"items\":[{\"index\":1,\"sql\":\"CREATE TABLE yf_payment_merchant (\\r\\n id BIGINT PRIMARY KEY, enterprise_id BIGINT NULL, code VARCHAR(64) NOT NULL UNIQUE,\\r\\n name VARCHAR(100) NOT NULL, mch_no VARCHAR(64) NOT NULL, app_id VARCHAR(64) NOT NULL,\\r\\n enabled INT NOT NULL DEFAULT 1, create_by VARCHAR(64), create_time DATETIME(3), update_by VARCHAR(64), update_time DATETIME(3),\\r\\n UNIQUE KEY uk_payment_remote_app(mch_no,app_id)\\r\\n)\",\"kind\":\"ddl\",\"success\":true,\"error\":null,\"columns\":[],\"columnTables\":[],\"rows\":[],\"rowCount\":0,\"affectedRows\":0,\"elapsedMs\":297,\"message\":\"DDL/CALL OK, 0 row(s) affected\"},{\"index\":2,\"sql\":\"CREATE TABLE yf_payment_credential (\\r\\n id BIGINT PRIMARY KEY, merchant_id BIGINT NOT NULL, secret_cipher TEXT NOT NULL,\\r\\n status VARCHAR(20) NOT NULL, expires_at DATETIME(3) NULL,\\r\\n create_by VARCHAR(64), create_time DATETIME(3), update_by VARCHAR(64), update_time DATETIME(3),\\r\\n INDEX idx_payment_credential(merchant_id,status,expires_at)\\r\\n)\",\"kind\":\"ddl\",\"success\":true,\"error\":null,\"columns\":[],\"columnTables\":[],\"rows\":[],\"rowCount\":0,\"affectedRows\":0,\"elapsedMs\":283,\"message\":\"DDL/CALL OK, 0 row(s) affected\"},{\"index\":3,\"sql\":\"CREATE TABLE yf_payment_route (\\r\\n id BIGINT PRIMARY KEY, enterprise_id BIGINT NOT NULL DEFAULT 0, scope VARCHAR(20) NOT NULL,\\r\\n scope_value VARCHAR(64) NOT NULL, route_key VARCHAR(64) NOT NULL UNIQUE,\\r\\n merchant_id BIGINT NOT NULL, enabled INT NOT NULL DEFAULT 1,\\r\\n create_by VARCHAR(64), create_time DATETIME(3), update_by VARCHAR(64), update_time DATETIME(3)\\r\\n)\",\"kind\":\"ddl\",\"success\":true,\"error\":null,\"columns\":[],\"column