(6053,'分步执行SQL',0,'com.lemon.vq.controller.DataBaseOperateController.executeSqlBatch()','POST',1,'system','','/lmdb/admin/dataBaseOperate/executeSqlBatch','10.10.10.200','未知','{\"dbConfigId\":1,\"instanceName\":\"lemon_db_client\",\"sql\":\"-- =====================================================================\\r\\n-- 数据大屏分享 / 嵌入链接（MySQL，可重复执行）\\r\\n--   1) 新建 LM_BI_SCREEN_SHARE 分享链接表\\r\\n--   2) 操作权限 BiScreen:share（分享大屏：管理分享链接），挂在已挂载 BiScreen 模块的菜单下\\r\\n-- 必须在重启后端之前执行（新版后端启动后访问分享接口会查询该表）。\\r\\n-- 只建表 / 插入不存在的数据，不删除、不修改已有数据。\\r\\n-- 匿名访问接口 /admin/biShare/public/** 由代码中的 @NoSession 显式放行，无需改 application.yml。\\r\\n-- @author yanch\\r\\n-- =====================================================================\\r\\nSET NAMES utf8mb4;\\r\\n\\r\\n-- ---------------------------------------------------------------------\\r\\n-- 1) 分享链接表\\r\\n-- ---------------------------------------------------------------------\\r\\nCREATE TABLE IF NOT EXISTS `LM_BI_SCREEN_SHARE` (\\r\\n  `ID` bigint(20) NOT NULL COMMENT \'主键（雪花）\',\\r\\n  `SCREEN_ID` bigint(20) NOT NULL COMMENT \'大屏ID\',\\r\\n  `CREATOR_USER_ID` bigint(20) NOT NULL COMMENT \'创建者（=大屏所有者）；匿名访问的数据身份\',\\r\\n  `TOKEN` varchar(64) NOT NULL COMMENT \'随机令牌（32字节 base64url，43位）\',\\r\\n  `NAME` varchar(64) DEFAULT NULL COMMENT \'链接名称（备注用途）\',\\r\\n  `DATA_MODE` varchar(16) NOT NULL DEFAULT \'SNAPSHOT\' COMMENT \'SNAPSHOT=快照（默认） LIVE=以创建者身份实时查询\',\\r\\n  `SNAPSHOT_ID` bigint(20) DEFAULT NULL COMMENT \'实时大屏的分享专用快照ID（定时快照大屏跟随大屏快照，为空）\',\\r\\n  `SNAPSHOT_VERSION_ID` bigint(20) DEFAULT NULL COMMENT \'分享快照对应的发布版本ID\',\\r\\n  `SNAPSHOT_TIME` datetime DEFAULT NULL COMMENT \'分享快照生成时间\',\\r\\n  `PASSWORD_HASH` varchar(100) DEFAULT NULL COMMENT \'访问密码 BCrypt 哈希，空=无密码\',\\r\\n  `EXPIRE_TIME` datetime DEFAULT NULL COMMENT \'过期时间，空=永久\',\\r\\n  `ALLOWED_HOSTS` varchar(1000) DEFAULT NULL COMMENT \'允许嵌入(iframe)的站点，逗号分隔；空=不允许外站嵌入\',\\r\\n  `STATUS` varchar(16) NOT NULL DEFAULT \'ACTIVE\' COMMENT \'ACTIVE/DISABLED/REVOKED（撤销为终态）\',\\r\\n  `VIEW_COUNT` bigint(20) NOT NULL DEFAULT 0 COMMENT \'浏览次数（首屏加载计数，自动刷新不计）\',\\r\\n  `DENIED_COUNT` bigint(20) NOT NULL DEFAULT 0 COMMENT \'被拒绝次数（密码错误/限流/过期/撤销等）\',\\r\\n  `LAST_ACCESS_TIME` datetime DEFAULT NULL COMMENT \'最后访问时间\',\\r\\n  `REVOKE_TIME` datetime DEFAULT NULL COMMENT \'撤销时间\',','{\"code\":200,\"msg\":\"common.success\",\"data\":{\"items\":[{\"index\":1,\"sql\":\"SET NAMES utf8mb4\",\"kind\":null,\"success\":false,\"error\":\"无法识别语句类型，仅支持查询、DML 或受控 DDL\",\"columns\":[],\"columnTables\":[],\"rows\":[],\"rowCount\":0,\"affectedRows\":null,\"elapsedMs\":null,\"message\":null}],\"stopped\":true,\"elapsedMs\":7,\"message\":\"已分步执行 1/7 条，成功 0 条，第 1 条停止：无法识别语句类型，仅支持查询、DML 或受控 DDL\"}}',0,'','2026-10-07 11:54:25'),
