_SHARE_TOKEN` (`TOKEN`),\\r\\n  KEY `IDX_BI_SCREEN_SHARE_SCREEN` (`SCREEN_ID`, `STATUS`)\\r\\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT=\'数据大屏分享链接\'\"}','{\"code\":200,\"msg\":\"common.success\",\"data\":{\"affectedRows\":0,\"elapsedMs\":284,\"message\":\"DDL/CALL OK, 0 row(s) affected\",\"sql\":\"-- ---------------------------------------------------------------------\\r\\n-- 1) 分享链接表\\r\\n-- ---------------------------------------------------------------------\\r\\nCREATE TABLE IF NOT EXISTS `LM_BI_SCREEN_SHARE` (\\r\\n  `ID` bigint(20) NOT NULL COMMENT \'主键（雪花）\',\\r\\n  `SCREEN_ID` bigint(20) NOT NULL COMMENT \'大屏ID\',\\r\\n  `CREATOR_USER_ID` bigint(20) NOT NULL COMMENT \'创建者（=大屏所有者）；匿名访问的数据身份\',\\r\\n  `TOKEN` varchar(64) NOT NULL COMMENT \'随机令牌（32字节 base64url，43位）\',\\r\\n  `NAME` varchar(64) DEFAULT NULL COMMENT \'链接名称（备注用途）\',\\r\\n  `DATA_MODE` varchar(16) NOT NULL DEFAULT \'SNAPSHOT\' COMMENT \'SNAPSHOT=快照（默认） LIVE=以创建者身份实时查询\',\\r\\n  `SNAPSHOT_ID` bigint(20) DEFAULT NULL COMMENT \'实时大屏的分享专用快照ID（定时快照大屏跟随大屏快照，为空）\',\\r\\n  `SNAPSHOT_VERSION_ID` bigint(20) DEFAULT NULL COMMENT \'分享快照对应的发布版本ID\',\\r\\n  `SNAPSHOT_TIME` datetime DEFAULT NULL COMMENT \'分享快照生成时间\',\\r\\n  `PASSWORD_HASH` varchar(100) DEFAULT NULL COMMENT \'访问密码 BCrypt 哈希，空=无密码\',\\r\\n  `EXPIRE_TIME` datetime DEFAULT NULL COMMENT \'过期时间，空=永久\',\\r\\n  `ALLOWED_HOSTS` varchar(1000) DEFAULT NULL COMMENT \'允许嵌入(iframe)的站点，逗号分隔；空=不允许外站嵌入\',\\r\\n  `STATUS` varchar(16) NOT NULL DEFAULT \'ACTIVE\' COMMENT \'ACTIVE/DISABLED/REVOKED（撤销为终态）\',\\r\\n  `VIEW_COUNT` bigint(20) NOT NULL DEFAULT 0 COMMENT \'浏览次数（首屏加载计数，自动刷新不计）\',\\r\\n  `DENIED_COUNT` bigint(20) NOT NULL DEFAULT 0 COMMENT \'被拒绝次数（密码错误/限流/过期/撤销等）\',\\r\\n  `LAST_ACCESS_TIME` datetime DEFAULT NULL COMMENT \'最后访问时间\',\\r\\n  `REVOKE_TIME` datetime DEFAULT NULL COMMENT \'撤销时间\',\\r\\n  `CREATE_BY` varchar(64) DEFAULT NULL,\\r\\n  `CREATE_TIME` datetime DEFAULT NULL,\\r\\n  `UPDATE_BY` varchar(64) DEFAULT NULL,\\r\\n  `UPDATE_TIME` datetime DEFAULT NULL,\\r\\n  PRIMARY KEY (`ID`),\\r\\n  UNIQUE KEY `UK_BI_SCREEN_SHARE_TOKEN` (`TOKEN`),\\r\\n  KEY `IDX_BI_SCREEN_SHARE_SCREEN` (`SCREEN_ID`, `STATUS`)\\r\\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT=\'数据大屏分享链接\'\"}}',0,'','2026-10-07 11:54:37'),
(6055,'执行自由SQL',0,'com.lemon.vq.controller.DataBaseOperateController.executeSql()','POST',1,'system','','/lmdb/admin/dataBaseOperate/executeSql','10.10.10.200','未知','{\"dbConfigId\":1,\"instanceName\":\"lemon_db_client\",\"sql\":\"-- ---------------------------------------------------------------------\\r\\n-- 2) 操作权限 BiScreen:share\\r\\n--    菜单：优先取已挂载 BiScreen 模块的菜单，其次按名称/路径兜底\\r\\n-- ---------------------------------------------------------------------\\r\\nSET @bi_menu := (\\r\\n  SELECT menu_id FROM (\\r\\n    SELECT mm.menu_id, 0 AS prio FROM sys_menu_module mm WHERE mm.module_code = \'BiScreen\'\\r\\n    UNION ALL\\r\\n    SELECT m.menu_id, 1 AS prio FROM sys_menu m\\r\\n    WHERE m.path IN (\'/visual/dashboard\', \'dashboard\') OR m.component LIKE \'%visual/dashboard/index%\'\\r\\n  ) t ORDER BY prio, menu_id LIMIT 1\\r\\n)\",\"maxRows\":200,\"requestId\":\"sql-1791345282086-wiesg9ns\",\"source\":\"manual\"}','{\"code\":-1,\"msg\":\"执行SQL失败: 仅允许执行 SELECT / SHOW / DESCRIBE / EXPLAIN / PRAGMA 类只读语句\",\"data\":null}',0,'','2026-10-07 11:54:43'),
(6056,'执行自由DML',2,'com.lemon.vq.controller.DataBaseOperateController.executeDml()','POST',1,'system','','/lmdb/admin/dataBaseOperate/executeDml','10.10.10.200','未知','{\"dbConfigId\":1,\"instanceName\":\"lemon_db_client\",\"sql\":\"INSERT INTO sys_operation (id, menu_id, module_code, operation_name, operation_code, method, res_url, del_flag)\\r\\nSELECT @op_id, @bi_menu, \'BiScreen\', \'分享大屏\', \'share\', \'shareSave\', \'/admin/biScreen/share/save\', 0 FROM DUAL\\r\\nWHERE @bi_menu IS NOT NULL\\r\\n  AND NOT EXISTS (SELECT 1 FROM sys_operation WHERE module_code = \'BiScreen\' AND operation_code = \'share\' AND del_flag = 0)\"}','{\"code\":200,\"msg\":\"common.success\",\"data\":{\"affectedRows\":0,\"elapsedMs\":5,\"message\":\"DML OK, 0 row(s) affected\",\"sql\":\"INSERT INTO sys_operation (id, menu_id, module_code, operation_name, operation_code, method, res_url, del_flag)\\r\\nSELECT @op_id, @bi_menu, \'BiScreen\', \'分享大屏\', \'share\', \'shareSave\', \'/admin/biScreen/share/save\', 0 FROM DUAL\\r\\nWHERE @bi_menu IS NOT NULL\\r\\n  AND NOT EXISTS (SELECT 1 FROM sys_operation WHERE module_code = \'BiScreen\' AND operation_code = \'share\' AND del_flag = 0)\"}}',0,'','2026-10-07 12:30:41'),
