(6121,'获取表DDL',0,'com.lemon.vq.controller.DataBaseOperateController.getTableDDL()','GET',1,'system','','/lmdb/admin/dataBaseOperate/getTableDDL/1/lemon_db_client/lm_vq_db_config','0:0:0:0:0:0:0:1','未知','{dbConfigId=1, instanceName=lemon_db_client, tableName=lm_vq_db_config}','{\"code\":200,\"msg\":\"common.success\",\"data\":{\"dbConfigId\":1,\"instanceName\":\"lemon_db_client\",\"createTime\":\"2026-10-09 17:13:30\",\"ddlLength\":2088,\"dbType\":\"MY_SQL\",\"ddl\":\"CREATE TABLE `lm_vq_db_config` ( `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT \'主键ID\',\\n  `DB_NAME` varchar(100) DEFAULT NULL COMMENT \'db name\',\\n  `DB_TYPE` varchar(20) NOT NULL COMMENT \'数据库类型\',\\n  `DB_HOST` varchar(50) NOT NULL DEFAULT \'-\' COMMENT \'host\',\\n  `DB_PORT` int(6) NOT NULL DEFAULT \'0\' COMMENT \'port\',\\n  `JDBC_URL` varchar(1024) NOT NULL DEFAULT \'\' COMMENT \'jdbc url\',\\n  `USERNAME` varchar(100) NOT NULL DEFAULT \'-\' COMMENT \'username\',\\n  `PASSWORD` varchar(100) NOT NULL DEFAULT \'\' COMMENT \'password\',\\n  `DESCRIPTION` varchar(500) DEFAULT NULL COMMENT \'描述\',\\n  `IS_PUBLIC` tinyint(1) DEFAULT \'0\' COMMENT \'是否公开库：1=登录用户可用(默认不可改画布)\',\\n  `OWNER_USER_ID` bigint(20) DEFAULT NULL COMMENT \'创建者/所有者用户ID\',\\n  `ORDER_NUM` int(4) NOT NULL DEFAULT \'0\' COMMENT \'order\',\\n  `DEL_FLAG` tinyint(1) DEFAULT \'0\' COMMENT \'删除标识\',\\n  `CREATE_BY` varchar(64) DEFAULT NULL COMMENT \'创建者\',\\n  `CREATE_TIME` datetime DEFAULT NULL COMMENT \'创建时间\',\\n  `UPDATE_BY` varchar(64) DEFAULT NULL COMMENT \'更新者\',\\n  `UPDATE_TIME` datetime DEFAULT NULL COMMENT \'更新时间\',\\n  `SCHEMA_NAME` varchar(512) DEFAULT NULL COMMENT \'schema or file path\',\\n  `CONNECTION_STATUS` int(11) DEFAULT \'0\' COMMENT \'连接状态（0-未连接 1-已连接）\',\\n  `LAST_CHECK_TIME` datetime DEFAULT NULL COMMENT \'最后连接检测时间\',\\n  `SSH_ENABLED` tinyint(1) DEFAULT \'0\' COMMENT \'是否启用 SSH 隧道(0否1是)\',\\n  `SSH_HOST` varchar(128) DEFAULT NULL COMMENT \'SSH 跳板机主机\',\\n  `SSH_PORT` int(6) DEFAULT \'22\' COMMENT \'SSH 端口\',\\n  `SSH_USERNAME` varchar(64) DEFAULT NULL COMMENT \'SSH 用户名\',\\n  `SSH_PASSWORD` varchar(256) DEFAULT NULL COMMENT \'SSH 密码(与私钥二选一)\',\\n  `SSH_PRIVATE_KEY` text COMMENT \'SSH 私钥 PEM 文本\',\\n  `SSH_PASSPHRASE` varchar(256) DEFAULT NULL COMMENT \'SSH 私钥口令\',\\n  `AI_ALLOW_SAMPLE_DATA` tinyint(1) NOT NULL DEFAULT \'0\' COMMENT \'AI 工具是否允许读取真实行数据（sample_rows/run_sql 返回行）\',\\n  `AI_ENABLED` tinyint(1) NOT N',0,'','2026-10-09 17:13:30'),
(6122,'执行受控DDL',3,'com.lemon.vq.controller.DataBaseOperateController.executeDdl()','POST',1,'system','','/lmdb/admin/dataBaseOperate/executeDdl','0:0:0:0:0:0:0:1','未知','{\"dbConfigId\":1,\"instanceName\":\"lemon_db_client\",\"sql\":\"CREATE TABLE  LM_VQ_DDL_TEMPLATE (\\r\\n  ID BIGINT NOT NULL AUTO_INCREMENT COMMENT \'主键\',\\r\\n  DB_TYPE VARCHAR(32) NOT NULL COMMENT \'产品码(H2/MY_SQL)或方言族(H2_LIKE)\',\\r\\n  OBJECT_KIND VARCHAR(32) NOT NULL COMMENT \'TABLE/VIEW/PROCEDURE/FUNCTION/TRIGGER/EVENT/ALTER_TABLE\',\\r\\n  SQL_TEXT MEDIUMTEXT NOT NULL COMMENT \'模板，占位符 ${qualified} ${name} ${schema} ${rawName} ${rawSchema} ${table} ${rawTable}\',\\r\\n  ENABLED TINYINT NOT NULL DEFAULT 1 COMMENT \'1启用 0停用\',\\r\\n  REMARK VARCHAR(200) DEFAULT NULL COMMENT \'备注\',\\r\\n  DEL_FLAG TINYINT DEFAULT 0 COMMENT \'删除标识\',\\r\\n  CREATE_BY VARCHAR(64) DEFAULT NULL,\\r\\n  CREATE_TIME DATETIME DEFAULT NULL,\\r\\n  UPDATE_BY VARCHAR(64) DEFAULT NULL,\\r\\n  UPDATE_TIME DATETIME DEFAULT NULL,\\r\\n  PRIMARY KEY (ID),\\r\\n  UNIQUE KEY UK_VQ_DDL_TPL (DB_TYPE, OBJECT_KIND, DEL_FLAG)\\r\\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT=\'SQL编辑器默认DDL模板\'\"}','{\"code\":-1,\"msg\":\"执行DDL失败: 执行 SQL 失败: Table \'lm_vq_ddl_template\' already exists\",\"data\":null}',0,'','2026-10-09 17:23:58'),
(6123,'分步执行SQL',0,'com.lemon.vq.controller.DataBaseOperateController.executeSqlBatch()','POST',1,'system','','/lmdb/admin/dataBaseOperate/executeSqlBatch','0:0:0:0:0:0:0:1','未知','{\"dbConfigId\":1,\"instanceName\":\"lemon_db_client\",\"sql\":\"-- Lemon ETL 第一版：任务区草稿、不可变发布版本和菜单权限。\\r\\n-- 配置 JSON 是唯一事实来源；连接密码不得写入 JSON。\\r\\n-- @author yanch\\r\\n\\r\\nCREATE TABLE IF NOT EXISTS `LM_ETL_WORKSPACE` (\\r\\n  `ID` bigint NOT NULL COMMENT \'任务区ID\',\\r\\n  `USER_ID` bigint NOT NULL COMMENT \'创建用户ID\',\\r\\n  `WORKSPACE_NAME` varchar(100) NOT NULL COMMENT \'任务区名称\',\\r\\n  `DESCRIPTION` varchar(500) DEFAULT NULL COMMENT \'任务区说明\',\\r\\n  `DRAFT_JSON` longtext NOT NULL COMMENT \'当前草稿JSON\',\\r\\n  `REVISION` int NOT NULL DEFAULT 1 COMMENT \'草稿乐观锁版本\',\\r\\n  `PUBLISHED_VERSION` int NOT NULL DEFAULT 0 COMMENT \'最近发布版本号\',\\r\\n  `STATUS` varchar(16) NOT NULL DEFAULT \'DRAFT\' COMMENT \'DRAFT/PUBLISHED\',\\r\\n  `DEL_FLAG` tinyint NOT NULL DEFAULT 0 COMMENT \'逻辑删除\',\\r\\n  `CREATE_BY` varchar(64) DEFAULT NULL,\\r\\n  `CREATE_TIME` datetime DEFAULT NULL,\\r\\n  `UPDATE_BY` varchar(64) DEFAULT NULL,\\r\\n  `UPDATE_TIME` datetime DEFAULT NULL,\\r\\n  PRIMARY KEY (`ID`),\\r\\n  KEY `IDX_ETL_WORKSPACE_USER` (`USER_ID`, `DEL_FLAG`, `UPDATE_TIME`)\\r\\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT=\'ETL任务区\';\\r\\n\\r\\nCREATE TABLE IF NOT EXISTS `LM_ETL_WORKSPACE_VERSION` (\\r\\n  `ID` bigint NOT NULL COMMENT \'版本ID\',\\r\\n  `WORKSPACE_ID` bigint NOT NULL COMMENT \'任务区ID\',\\r\\n  `USER_ID` bigint NOT NULL COMMENT \'发布用户ID\',\\r\\n  `VERSION_NO` int NOT NULL COMMENT \'版本号\',\\r\\n  `CONFIG_JSON` longtext NOT NULL COMMENT \'不可变配置JSON\',\\r\\n  `CONTENT_HASH` char(64) NOT NULL COMMENT \'配置SHA-256\',\\r\\n  `CREATE_BY` varchar(64) DEFAULT NULL,\\r\\n  `CREATE_TIME` datetime DEFAULT NULL,\\r\\n  `UPDATE_BY` varchar(64) DEFAULT NULL,\\r\\n  `UPDATE_TIME` datetime DEFAULT NULL,\\r\\n  PRIMARY KEY (`ID`),\\r\\n  UNIQUE KEY `UK_ETL_WORKSPACE_VERSION` (`WORKSPACE_ID`, `VERSION_NO`),\\r\\n  KEY `IDX_ETL_VERSION_USER` (`USER_ID`, `CREATE_TIME`)\\r\\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT=\'ETL任务区发布版本\';\\r\\n\\r\\n-- 将 ETL 挂到 LSql 目录。不存在 LSql 时只建表，不会错误挂到根菜单。\\r\\nSET @etl_parent_menu := (\\r\\n  SELECT menu_id FROM sys_menu\\r\\n  WHERE name = \'LSql\' OR path = \'/lSql\'\\r\\n  ORDER ','{\"code\":200,\"msg\":\"common.success\",\"data\":{\"items\":[{\"index\":1,\"sql\":\"CREATE TABLE IF NOT EXISTS `LM_ETL_WORKSPACE` (\\r\\n  `ID` bigint NOT NULL COMMENT \'任务区ID\',\\r\\n  `USER_ID` bigint NOT NULL COMMENT \'创建用户ID\',\\r\\n  `WORKSPACE_NAME` varchar(100) NOT NULL COMMENT \'任务区名称\',\\r\\n  `DESCRIPTION` varchar(500) DEFAULT NULL COMMENT \'任务区说明\',\\r\\n  `DRAFT_JSON` longtext NOT NULL COMMENT \'当前草稿JSON\',\\r\\n  `REVISION` int NOT NULL DEFAULT 1 COMMENT \'草稿乐观锁版本\',\\r\\n  `PUBLISHED_VERSION` int NOT NULL DEFAULT 0 COMMENT \'最近发布版本号\',\\r\\n  `STATUS` varchar(16) NOT NULL DEFAULT \'DRAFT\' COMMENT \'DRAFT/PUBLISHED\',\\r\\n  `DEL_FLAG` tinyint NOT NULL DEFAULT 0 COMMENT \'逻辑删除\',\\r\\n  `CREATE_BY` varchar(64) DEFAULT NULL,\\r\\n  `CREATE_TIME` datetime DEFAULT NULL,\\r\\n  `UPDATE_BY` varchar(64) DEFAULT NULL,\\r\\n  `UPDATE_TIME` datetime DEFAULT NULL,\\r\\n  PRIMARY KEY (`ID`),\\r\\n  KEY `IDX_ETL_WORKSPACE_USER` (`USER_ID`, `DEL_FLAG`, `UPDATE_TIME`)\\r\\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT=\'ETL任务区\'\",\"kind\":\"ddl\",\"success\":true,\"error\":null,\"columns\":[],\"columnTables\":[],\"rows\":[],\"rowCount\":0,\"affectedRows\":0,\"elapsedMs\":30,\"message\":\"DDL/CALL OK, 0 row(s) affected\",\"truncated\":false},{\"index\":2,\"sql\":\"CREATE TABLE IF NOT EXISTS `LM_ETL_WORKSPACE_VERSION` (\\r\\n  `ID` bigint NOT NULL COMMENT \'版本ID\',\\r\\n  `WORKSPACE_ID` bigint NOT NULL COMMENT \'任务区ID\',\\r\\n  `USER_ID` bigint NOT NULL COMMENT \'发布用户ID\',\\r\\n  `VERSION_NO` int NOT NULL COMMENT \'版本号\',\\r\\n  `CONFIG_JSON` longtext NOT NULL COMMENT \'不可变配置JSON\',\\r\\n  `CONTENT_HASH` char(64) NOT NULL COMMENT \'配置SHA-256\',\\r\\n  `CREATE_BY` varchar(64) DEFAULT NULL,\\r\\n  `CREATE_TIME` datetime DEFAULT NULL,\\r\\n  `UPDATE_BY` varchar(64) DEFAULT NULL,\\r\\n  `UPDATE_TIME` datetime DEFAULT NULL,\\r\\n  PRIMARY KEY (`ID`),\\r\\n  UNIQUE KEY `UK_ETL_WORKSPACE_VERSION` (`WORKSPACE_ID`, `VERSION_NO`),\\r\\n  KEY `IDX_ETL_VERSION_USER` (`USER_ID`, `CREATE_TIME`)\\r\\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT=\'ETL任务区发布版本\'\",\"kind\":\"ddl\",\"success\":true,\"error\":null,\"columns\":[],\"c',0,'','2026-10-09 17:24:09'),
(6124,'分步执行SQL',0,'com.lemon.vq.controller.DataBaseOperateController.executeSqlBatch()','POST',1,'system','','/lmdb/admin/dataBaseOperate/executeSqlBatch','0:0:0:0:0:0:0:1','未知','{\"dbConfigId\":1,\"instanceName\":\"lemon_db_client\",\"sql\":\"-- 工作区持久化定时计划与触发批次；执行前备份平台库，非业务同步目标库。@author yanch\\r\\nCREATE TABLE IF NOT EXISTS LM_ETL_SCHEDULE (\\r\\n  WORKSPACE_ID bigint NOT NULL,\\r\\n  USER_ID bigint NOT NULL,\\r\\n  OWNER_TYPE varchar(16) NOT NULL,\\r\\n  ROLE_ID bigint NOT NULL,\\r\\n  ENABLED tinyint NOT NULL DEFAULT 0,\\r\\n  REVISION int NOT NULL,\\r\\n  PUBLISHED_VERSION int NOT NULL,\\r\\n  PIPELINE_IDS_JSON longtext NOT NULL,\\r\\n  MODE varchar(16) NOT NULL,\\r\\n  TIME_ZONE varchar(80) NOT NULL,\\r\\n  CRON_EXPRESSION varchar(160) DEFAULT NULL,\\r\\n  TIME_OF_DAY varchar(5) DEFAULT NULL,\\r\\n  WEEK_DAYS_JSON varchar(64) NOT NULL,\\r\\n  INTERVAL_MINUTES int DEFAULT NULL,\\r\\n  RUN_AT bigint DEFAULT NULL,\\r\\n  NEXT_FIRE_AT bigint DEFAULT NULL,\\r\\n  UPDATED_AT bigint NOT NULL,\\r\\n  PRIMARY KEY (WORKSPACE_ID),\\r\\n  KEY IDX_ETL_SCHEDULE_DUE (ENABLED,NEXT_FIRE_AT),\\r\\n  KEY IDX_ETL_SCHEDULE_USER (USER_ID)\\r\\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT=\'ETL工作区定时计划\';\\r\\n\\r\\nCREATE TABLE IF NOT EXISTS LM_ETL_SCHEDULE_FIRE (\\r\\n  ID varchar(32) NOT NULL,\\r\\n  WORKSPACE_ID bigint NOT NULL,\\r\\n  USER_ID bigint NOT NULL,\\r\\n  OWNER_TYPE varchar(16) NOT NULL,\\r\\n  ROLE_ID bigint NOT NULL,\\r\\n  PUBLISHED_VERSION int NOT NULL,\\r\\n  PIPELINE_IDS_JSON longtext NOT NULL,\\r\\n  RUN_IDS_JSON longtext NOT NULL,\\r\\n  NEXT_INDEX int NOT NULL DEFAULT 0,\\r\\n  CURRENT_RUN_ID varchar(32) DEFAULT NULL,\\r\\n  STATUS varchar(16) NOT NULL,\\r\\n  MESSAGE varchar(500) DEFAULT NULL,\\r\\n  SCHEDULED_AT bigint NOT NULL,\\r\\n  CREATED_AT bigint NOT NULL,\\r\\n  FINISHED_AT bigint DEFAULT NULL,\\r\\n  ACTIVE_KEY varchar(64) DEFAULT NULL,\\r\\n  LEASE_TOKEN varchar(36) DEFAULT NULL,\\r\\n  LEASE_UNTIL bigint DEFAULT NULL,\\r\\n  PRIMARY KEY (ID),\\r\\n  UNIQUE KEY UK_ETL_SCHEDULE_ACTIVE (ACTIVE_KEY),\\r\\n  KEY IDX_ETL_SCHEDULE_FIRE_ACTIVE (STATUS,LEASE_UNTIL),\\r\\n  KEY IDX_ETL_SCHEDULE_FIRE_USER (USER_ID,WORKSPACE_ID,CREATED_AT)\\r\\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT=\'ETL定时触发审计及串行批次\';\\r\\n\\r\\n-- 只登记新权限，不自动为角色增权','{\"code\":200,\"msg\":\"common.success\",\"data\":{\"items\":[{\"index\":1,\"sql\":\"CREATE TABLE IF NOT EXISTS LM_ETL_SCHEDULE (\\r\\n  WORKSPACE_ID bigint NOT NULL,\\r\\n  USER_ID bigint NOT NULL,\\r\\n  OWNER_TYPE varchar(16) NOT NULL,\\r\\n  ROLE_ID bigint NOT NULL,\\r\\n  ENABLED tinyint NOT NULL DEFAULT 0,\\r\\n  REVISION int NOT NULL,\\r\\n  PUBLISHED_VERSION int NOT NULL,\\r\\n  PIPELINE_IDS_JSON longtext NOT NULL,\\r\\n  MODE varchar(16) NOT NULL,\\r\\n  TIME_ZONE varchar(80) NOT NULL,\\r\\n  CRON_EXPRESSION varchar(160) DEFAULT NULL,\\r\\n  TIME_OF_DAY varchar(5) DEFAULT NULL,\\r\\n  WEEK_DAYS_JSON varchar(64) NOT NULL,\\r\\n  INTERVAL_MINUTES int DEFAULT NULL,\\r\\n  RUN_AT bigint DEFAULT NULL,\\r\\n  NEXT_FIRE_AT bigint DEFAULT NULL,\\r\\n  UPDATED_AT bigint NOT NULL,\\r\\n  PRIMARY KEY (WORKSPACE_ID),\\r\\n  KEY IDX_ETL_SCHEDULE_DUE (ENABLED,NEXT_FIRE_AT),\\r\\n  KEY IDX_ETL_SCHEDULE_USER (USER_ID)\\r\\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT=\'ETL工作区定时计划\'\",\"kind\":\"ddl\",\"success\":true,\"error\":null,\"columns\":[],\"columnTables\":[],\"rows\":[],\"rowCount\":0,\"affectedRows\":0,\"elapsedMs\":33,\"message\":\"DDL/CALL OK, 0 row(s) affected\",\"truncated\":false},{\"index\":2,\"sql\":\"CREATE TABLE IF NOT EXISTS LM_ETL_SCHEDULE_FIRE (\\r\\n  ID varchar(32) NOT NULL,\\r\\n  WORKSPACE_ID bigint NOT NULL,\\r\\n  USER_ID bigint NOT NULL,\\r\\n  OWNER_TYPE varchar(16) NOT NULL,\\r\\n  ROLE_ID bigint NOT NULL,\\r\\n  PUBLISHED_VERSION int NOT NULL,\\r\\n  PIPELINE_IDS_JSON longtext NOT NULL,\\r\\n  RUN_IDS_JSON longtext NOT NULL,\\r\\n  NEXT_INDEX int NOT NULL DEFAULT 0,\\r\\n  CURRENT_RUN_ID varchar(32) DEFAULT NULL,\\r\\n  STATUS varchar(16) NOT NULL,\\r\\n  MESSAGE varchar(500) DEFAULT NULL,\\r\\n  SCHEDULED_AT bigint NOT NULL,\\r\\n  CREATED_AT bigint NOT NULL,\\r\\n  FINISHED_AT bigint DEFAULT NULL,\\r\\n  ACTIVE_KEY varchar(64) DEFAULT NULL,\\r\\n  LEASE_TOKEN varchar(36) DEFAULT NULL,\\r\\n  LEASE_UNTIL bigint DEFAULT NULL,\\r\\n  PRIMARY KEY (ID),\\r\\n  UNIQUE KEY UK_ETL_SCHEDULE_ACTIVE (ACTIVE_KEY),\\r\\n  KEY IDX_ETL_SCHEDULE_FIRE_ACTIVE (STATUS,LEASE_UNTIL),\\r\\n ',0,'','2026-10-09 17:24:19'),
(6125,'分步执行SQL',0,'com.lemon.vq.controller.DataBaseOperateController.executeSqlBatch()','POST',1,'system','','/lmdb/admin/dataBaseOperate/executeSqlBatch','0:0:0:0:0:0:0:1','未知','{\"dbConfigId\":1,\"instanceName\":\"lemon_db_client\",\"sql\":\"-- SQL ETL 执行历史及新操作权限。@author yanch\\r\\nCREATE TABLE IF NOT EXISTS LM_ETL_RUN (\\r\\n  ID varchar(32) NOT NULL,\\r\\n  WORKSPACE_ID bigint NOT NULL,\\r\\n  USER_ID bigint NOT NULL,\\r\\n  PIPELINE_ID varchar(128) NOT NULL,\\r\\n  PIPELINE_NAME varchar(200) DEFAULT NULL,\\r\\n  REVISION int NOT NULL,\\r\\n  STATUS varchar(16) NOT NULL,\\r\\n  ACTIVE_KEY varchar(255) DEFAULT NULL COMMENT \'同一工作区任务仅允许一个活动运行\',\\r\\n  CONFIG_JSON longtext NOT NULL,\\r\\n  STEPS_JSON longtext NOT NULL,\\r\\n  MESSAGE varchar(500) DEFAULT NULL,\\r\\n  STARTED_AT bigint NOT NULL,\\r\\n  FINISHED_AT bigint DEFAULT NULL,\\r\\n  CANCEL_REQUESTED tinyint NOT NULL DEFAULT 0,\\r\\n  PRIMARY KEY (ID),\\r\\n  UNIQUE KEY UK_ETL_ACTIVE (ACTIVE_KEY),\\r\\n  KEY IDX_ETL_RUN_USER (USER_ID, WORKSPACE_ID, STARTED_AT)\\r\\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT=\'SQL ETL执行记录\';\\r\\n\\r\\nCREATE TABLE IF NOT EXISTS LM_ETL_RUN_LOG (\\r\\n  ID varchar(32) NOT NULL,\\r\\n  RUN_ID varchar(32) NOT NULL,\\r\\n  NODE_ID varchar(128) DEFAULT NULL,\\r\\n  LEVEL varchar(8) NOT NULL,\\r\\n  STATUS varchar(20) NOT NULL,\\r\\n  ROW_COUNT bigint NOT NULL DEFAULT 0,\\r\\n  MESSAGE varchar(500) DEFAULT NULL,\\r\\n  CREATED_AT bigint NOT NULL,\\r\\n  PRIMARY KEY (ID),\\r\\n  KEY IDX_ETL_LOG_RUN (RUN_ID, CREATED_AT),\\r\\n  KEY IDX_ETL_LOG_NODE (RUN_ID, NODE_ID, CREATED_AT)\\r\\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT=\'ETL任务节点分页批次日志\';\\r\\n\\r\\nSET @etl_menu := (SELECT menu_id FROM sys_menu WHERE name=\'EtlWorkspace\' OR path=\'/lSql/etl\' LIMIT 1);\\r\\nSET @etl_op := (SELECT IFNULL(MAX(id),0)+1 FROM sys_operation);\\r\\nINSERT INTO sys_operation (id,menu_id,module_code,operation_name,operation_code,method,res_url,del_flag)\\r\\nSELECT @etl_op,@etl_menu,\'EtlWor