/*Table structure for table `lm_ai_agent_memory` */

DROP TABLE IF EXISTS `lm_ai_agent_memory`;

CREATE TABLE `lm_ai_agent_memory` (
  `ID` bigint(20) NOT NULL,
  `SCOPE` varchar(16) NOT NULL COMMENT 'INSTANCE=实例共享知识 / USER=该用户在该实例上的使用习惯',
  `USER_ID` bigint(20) NOT NULL DEFAULT '0' COMMENT 'INSTANCE 固定 0；USER 为真实用户',
  `DB_CONFIG_ID` bigint(20) NOT NULL,
  `INSTANCE_NAME` varchar(128) NOT NULL,
  `TITLE` varchar(200) DEFAULT NULL,
  `SUMMARY` varchar(800) DEFAULT NULL COMMENT '短摘要，优先注入 system prompt',
  `CONTENT_MD` mediumtext COMMENT '完整记忆 Markdown',
  `FOCUS_TABLES_JSON` text COMMENT '热表 [{table,hits,lastAt}]',
  `PENDING_TURNS` int(11) NOT NULL DEFAULT '0' COMMENT '自上次消化以来的未总结对话轮数',
  `LAST_DIGEST_AT` datetime DEFAULT NULL,
  `VERSION` int(11) NOT NULL DEFAULT '1',
  `LAST_MODEL_ID` bigint(20) DEFAULT NULL,
  `STATUS` varchar(16) NOT NULL DEFAULT 'ACTIVE',
  `DEL_FLAG` tinyint(1) DEFAULT '0',
  `CREATE_BY` varchar(64) DEFAULT NULL,
  `CREATE_TIME` datetime DEFAULT NULL,
  `UPDATE_BY` varchar(64) DEFAULT NULL,
  `UPDATE_TIME` datetime DEFAULT NULL,
  PRIMARY KEY (`ID`),
  UNIQUE KEY `UK_AGENT_MEMORY` (`SCOPE`,`USER_ID`,`DB_CONFIG_ID`,`INSTANCE_NAME`),
  KEY `IDX_AGENT_MEM_INST` (`DB_CONFIG_ID`,`INSTANCE_NAME`,`SCOPE`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='数据库智能体隐式记忆（实例/用户）';

/*Data for the table `lm_ai_agent_memory` */


/*Table structure for table `lm_ai_chart` */

DROP TABLE IF EXISTS `lm_ai_chart`;

CREATE TABLE `lm_ai_chart` (
  `ID` bigint(20) NOT NULL,
  `USER_ID` bigint(20) NOT NULL,
  `DB_CONFIG_ID` bigint(20) NOT NULL,
  `INSTANCE_NAME` varchar(128) DEFAULT NULL,
  `TITLE` varchar(200) NOT NULL,
  `SQL_TEXT` mediumtext NOT NULL,
  `CHART_SPEC` text NOT NULL COMMENT 'ChartSpec JSON（见设计文档附录 D）',
  `CONVERSATION_ID` bigint(20) DEFAULT NULL,
  `DEL_FLAG` tinyint(1) DEFAULT '0',
  `CREATE_BY` varchar(64) DEFAULT NULL,
  `CREATE_TIME` datetime DEFAULT NULL,
  `UPDATE_BY` varchar(64) DEFAULT NULL,
  `UPDATE_TIME` datetime DEFAULT NULL,
  `DATASET_ID` bigint(20) DEFAULT NULL COMMENT '通用数据集ID',
  `SOURCE_TYPE` varchar(16) NOT NULL DEFAULT 'AI' COMMENT 'AI/MANUAL',
  `SPEC_VERSION` int(11) NOT NULL DEFAULT '1' COMMENT 'ChartSpec协议版本',
  `REVISION` int(11) NOT NULL DEFAULT '1' COMMENT '图表修订号',
  `DESCRIPTION` varchar(500) DEFAULT NULL,
  PRIMARY KEY (`ID`),
  KEY `IDX_AI_CHART_USER` (`USER_ID`,`DB_CONFIG_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='AI 生成图表';

/*Data for the table `lm_ai_chart` */


/*Table structure for table `lm_ai_conversation` */

DROP TABLE IF EXISTS `lm_ai_conversation`;

CREATE TABLE `lm_ai_conversation` (
  `ID` bigint(20) NOT NULL,
  `USER_ID` bigint(20) NOT NULL,
  `TITLE` varchar(200) DEFAULT NULL COMMENT '首条用户消息截断',
  `SCENE` varchar(32) NOT NULL DEFAULT 'sql' COMMENT 'sql=编辑器助手 / chart=图表 / schema_doc=文档维护 / free',
  `DB_CONFIG_ID` bigint(20) DEFAULT NULL,
  `INSTANCE_NAME` varchar(128) DEFAULT NULL,
  `MODEL_ID` bigint(20) DEFAULT NULL COMMENT '最近使用模型',
  `TOTAL_PROMPT_TOKENS` bigint(20) DEFAULT '0',
  `TOTAL_COMPLETION_TOKENS` bigint(20) DEFAULT '0',
  `DEL_FLAG` tinyint(1) DEFAULT '0',
  `CREATE_BY` varchar(64) DEFAULT NULL,
  `CREATE_TIME` datetime DEFAULT NULL,
  `UPDATE_BY` varchar(64) DEFAULT NULL,
  `UPDATE_TIME` datetime DEFAULT NULL,
  PRIMARY KEY (`ID`),
  KEY `IDX_AI_CONV_USER` (`USER_ID`,`DB_CONFIG_ID`,`UPDATE_TIME`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='AI 会话';

/*Data for the table `lm_ai_conversation` */


/*Table structure for table `lm_ai_message` */

DROP TABLE IF EXISTS `lm_ai_message`;

CREATE TABLE `lm_ai_message` (
  `ID` bigint(20) NOT NULL,
  `CONVERSATION_ID` bigint(20) NOT NULL,
  `SEQ` int(11) NOT NULL COMMENT '会话内顺序',
  `ROLE` varchar(16) NOT NULL COMMENT 'system/user/assistant/tool',
  `CONTENT` longtext COMMENT '文本内容',
  `REASONING` longtext COMMENT '思考内容（仅展示，不回传模型）',
  `TOOL_CALLS` text COMMENT 'assistant 发起的 tool_calls（JSON 数组）',
  `TOOL_CALL_ID` varchar(64) DEFAULT NULL COMMENT 'role=tool 时对应的 call id',
  `TOOL_NAME` varchar(64) DEFAULT NULL,
  `ATTACHMENTS` text COMMENT '结构化产物 JSON：{proposedSql:{}, chart:{}} 供前端回放',
  `PROMPT_TOKENS` int(11) DEFAULT NULL,
  `COMPLETION_TOKENS` int(11) DEFAULT NULL,
  `MODEL_ID` bigint(20) DEFAULT NULL,
  `CREATE_TIME` datetime DEFAULT NULL,
  PRIMARY KEY (`ID`),
  KEY `IDX_AI_MSG_CONV` (`CONVERSATION_ID`,`SEQ`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='AI 消息';

/*Data for the table `lm_ai_message` */


/*Table structure for table `lm_ai_model` */

DROP TABLE IF EXISTS `lm_ai_model`;

CREATE TABLE `lm_ai_model` (
  `ID` bigint(20) NOT NULL,
  `PROVIDER_ID` bigint(20) NOT NULL COMMENT 'LM_AI_PROVIDER.ID',
  `MODEL_CODE` varchar(100) NOT NULL COMMENT '调用时的 model 参数，如 deepseek-chat',
  `DISPLAY_NAME` varchar(100) NOT NULL,
  `SUPPORTS_TOOLS` tinyint(1) NOT NULL DEFAULT '1' COMMENT '支持 function calling（Agent 必需）',
  `SUPPORTS_REASONING` tinyint(1) NOT NULL DEFAULT '0' COMMENT '返回 reasoning_content（deepseek-reasoner/qwen3 思考）',
  `CONTEXT_WINDOW` int(11) DEFAULT '128000' COMMENT '上下文窗口 tokens，用于预算',
  `MAX_OUTPUT_TOKENS` int(11) DEFAULT '8192',
  `DEFAULT_TEMPERATURE` decimal(3,2) DEFAULT '0.20',
  `IS_DEFAULT` tinyint(1) NOT NULL DEFAULT '0' COMMENT '全局默认模型（仅一个）',
  `ENABLED` tinyint(1) NOT NULL DEFAULT '1',
  `ORDER_NUM` int(4) NOT NULL DEFAULT '0',
  `DEL_FLAG` tinyint(1) DEFAULT '0',
  `CREATE_BY` varchar(64) DEFAULT NULL,
  `CREATE_TIME` datetime DEFAULT NULL,
  `UPDATE_BY` varchar(64) DEFAULT NULL,
  `UPDATE_TIME` datetime DEFAULT NULL,
  PRIMARY KEY (`ID`),
  UNIQUE KEY `UK_AI_MODEL` (`PROVIDER_ID`,`MODEL_CODE`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='AI 模型版本';

/*Data for the table `lm_ai_model` */


/*Table structure for table `lm_ai_provider` */

DROP TABLE IF EXISTS `lm_ai_provider`;

CREATE TABLE `lm_ai_provider` (
  `ID` bigint(20) NOT NULL COMMENT '主键(雪花)',
  `PROVIDER_CODE` varchar(32) NOT NULL COMMENT '厂商编码：qwen/kimi/deepseek/glm/openai/gemini/custom',
  `PROVIDER_NAME` varchar(64) NOT NULL COMMENT '显示名称',
  `PROTOCOL` varchar(32) NOT NULL DEFAULT 'openai_compatible' COMMENT '协议：openai_compatible（预留 anthropic 等）',
  `BASE_URL` varchar(255) NOT NULL COMMENT '接口根地址，如 https://api.deepseek.com/v1',
  `API_KEY_ENC` varchar(1024) DEFAULT NULL COMMENT 'API Key（AES 加密）',
  `EXTRA_HEADERS` varchar(1024) DEFAULT NULL COMMENT '额外请求头 JSON（部分厂商需要）',
  `TIMEOUT_SECONDS` int(4) NOT NULL DEFAULT '120' COMMENT '读超时秒',
  `SUPPORTS_STREAM_USAGE` tinyint(1) NOT NULL DEFAULT '0' COMMENT '流式是否支持 stream_options.include_usage',
  `ENABLED` tinyint(1) NOT NULL DEFAULT '1' COMMENT '启用',
  `IS_BUILTIN` tinyint(1) NOT NULL DEFAULT '0' COMMENT '内置种子（不可删，可改）',
  `SCOPE` varchar(16) NOT NULL DEFAULT 'GLOBAL' COMMENT 'GLOBAL=全局共享 / USER=仅本人',
  `OWNER_USER_ID` bigint(20) DEFAULT NULL COMMENT 'SCOPE=USER 时所属用户',
  `ORDER_NUM` int(4) NOT NULL DEFAULT '0',
  `DEL_FLAG` tinyint(1) DEFAULT '0',
  `CREATE_BY` varchar(64) DEFAULT NULL,
  `CREATE_TIME` datetime DEFAULT NULL,
  `UPDATE_BY` varchar(64) DEFAULT NULL,
  `UPDATE_TIME` datetime DEFAULT NULL,
  PRIMARY KEY (`ID`),
  KEY `IDX_AI_PROVIDER_OWNER` (`SCOPE`,`OWNER_USER_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='AI 大模型厂商配置';

/*Data for the table `lm_ai_provider` */


/*Table structure for table `lm_ai_schema_doc` */

DROP TABLE IF EXISTS `lm_ai_schema_doc`;

CREATE TABLE `lm_ai_schema_doc` (
  `ID` bigint(20) NOT NULL,
  `DB_CONFIG_ID` bigint(20) NOT NULL,
  `INSTANCE_NAME` varchar(128) NOT NULL,
  `DOC_TYPE` varchar(16) NOT NULL COMMENT 'OVERVIEW/DOMAIN/TABLE',
  `DOMAIN_CODE` varchar(64) NOT NULL DEFAULT '' COMMENT '业务域编码（DOMAIN/TABLE 有值；来源画布分组名或 AI 聚类）',
  `DOMAIN_NAME` varchar(100) DEFAULT NULL,
  `TABLE_NAME` varchar(128) NOT NULL DEFAULT '' COMMENT 'DOC_TYPE=TABLE 有值',
  `TITLE` varchar(200) DEFAULT NULL,
  `SUMMARY` varchar(500) DEFAULT NULL COMMENT '一句话说明（注入总览/索引用，控制 token）',
  `CONTENT_MD` mediumtext COMMENT '完整 Markdown',
  `KEY_FIELDS_JSON` text COMMENT 'TABLE：[{field,meaning,role:pk|fk|status|time|amount|other}]',
  `RELATIONS_JSON` text COMMENT 'TABLE：[{table,onSql:"a.uid=b.id",type:"1:N",source:"canvas|ai|history",confidence}]',
  `SCHEMA_HASH` char(32) DEFAULT NULL COMMENT '表结构指纹 MD5(列名+类型+注释)，用于增量判断',
  `SOURCE` varchar(16) NOT NULL DEFAULT 'ai' COMMENT 'canvas/ai/user/history',
  `STATUS` varchar(16) NOT NULL DEFAULT 'ACTIVE' COMMENT 'ACTIVE/STALE(结构已变)/DROPPED(表已删)',
  `VERSION` int(11) NOT NULL DEFAULT '1',
  `LAST_MODEL_ID` bigint(20) DEFAULT NULL,
  `USER_LOCKED` tinyint(1) NOT NULL DEFAULT '0' COMMENT '用户手工编辑后锁定，AI 不覆盖只追加备注',
  `DEL_FLAG` tinyint(1) DEFAULT '0',
  `CREATE_BY` varchar(64) DEFAULT NULL,
  `CREATE_TIME` datetime DEFAULT NULL,
  `UPDATE_BY` varchar(64) DEFAULT NULL,
  `UPDATE_TIME` datetime DEFAULT NULL,
  PRIMARY KEY (`ID`),
  UNIQUE KEY `UK_SCHEMA_DOC` (`DB_CONFIG_ID`,`INSTANCE_NAME`,`DOC_TYPE`,`DOMAIN_CODE`,`TABLE_NAME`),
  KEY `IDX_SCHEMA_DOC_TABLE` (`DB_CONFIG_ID`,`INSTANCE_NAME`,`TABLE_NAME`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='AI 维护的数据库结构说明文档';

/*Data for the table `lm_ai_schema_doc` */


/*Table structure for table `lm_ai_schema_doc_history` */

DROP TABLE IF EXISTS `lm_ai_schema_doc_history`;

CREATE TABLE `lm_ai_schema_doc_history` (
  `ID` bigint(20) NOT NULL,
  `DOC_ID` bigint(20) NOT NULL,
  `VERSION` int(11) NOT NULL,
  `CONTENT_MD` mediumtext,
  `KEY_FIELDS_JSON` text,
  `RELATIONS_JSON` text,
  `SOURCE` varchar(16) DEFAULT NULL,
  `CHANGE_NOTE` varchar(500) DEFAULT NULL,
  `CREATE_BY` varchar(64) DEFAULT NULL,
  `CREATE_TIME` datetime DEFAULT NULL,
  PRIMARY KEY (`ID`),
  KEY `IDX_SDH_DOC` (`DOC_ID`,`VERSION`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Schema 文档版本';

/*Data for the table `lm_ai_schema_doc_history` */


/*Table structure for table `lm_attachment` */

DROP TABLE IF EXISTS `lm_attachment`;

CREATE TABLE `lm_attachment` (
  `ID` varchar(50) NOT NULL COMMENT '主键',
  `CONFIG_ID` varchar(50) DEFAULT NULL COMMENT '附件配置Id',
  `MODULE_CODE` varchar(50) DEFAULT NULL COMMENT '业务模块编码',
  `BELONG_ID` varchar(50) DEFAULT NULL COMMENT '业务id',
  `ATTACH_NAME` varchar(100) DEFAULT NULL COMMENT '附件名称',
  `ATTACH_TYPE` varchar(50) DEFAULT NULL COMMENT '附件类型',
  `ORIGINAL_NAME` varchar(150) DEFAULT NULL COMMENT '原始文件名',
  `SAVE_PATH` varchar(200) DEFAULT NULL COMMENT '保存路径',
  `FULL_SAVE_PATH` varchar(200) DEFAULT NULL COMMENT '磁盘路径',
  `DOWNLOAD_URL` varchar(300) DEFAULT NULL COMMENT '下载路径',
  `USER_ID` varchar(50) DEFAULT NULL COMMENT '上传用户id',
  `VALIDATE_CODE` varchar(50) DEFAULT NULL COMMENT '验证码（md5）',
  `FILE_SIZE` int(15) DEFAULT NULL COMMENT '文件长度',
  `DEL_FLAG` int(1) DEFAULT NULL COMMENT '删除标识',
  `CREATE_BY` varchar(50) DEFAULT NULL COMMENT '创建人',
  `CREATE_TIME` datetime DEFAULT NULL COMMENT '创建时间',
  `UPDATE_BY` varchar(50) DEFAULT NULL COMMENT '更新人',
  `UPDATE_TIME` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

/*Data for the table `lm_attachment` */


/*Table structure for table `lm_bi_dataset` */

DROP TABLE IF EXISTS `lm_bi_dataset`;

CREATE TABLE `lm_bi_dataset` (
  `ID` bigint(20) NOT NULL,
  `USER_ID` bigint(20) NOT NULL,
  `NAME` varchar(200) NOT NULL,
  `DB_CONFIG_ID` bigint(20) NOT NULL,
  `INSTANCE_NAME` varchar(128) DEFAULT NULL,
  `SQL_TEXT` mediumtext NOT NULL,
  `PARAM_SCHEMA_JSON` text,
  `DEFAULT_PARAMS_JSON` text,
  `MAX_ROWS` int(11) NOT NULL DEFAULT '2000',
  `TIMEOUT_SECONDS` int(11) NOT NULL DEFAULT '30',
  `REVISION` int(11) NOT NULL DEFAULT '1',
  `DEL_FLAG` tinyint(1) NOT NULL DEFAULT '0',
  `CREATE_BY` varchar(64) DEFAULT NULL,
  `CREATE_TIME` datetime DEFAULT NULL,
  `UPDATE_BY` varchar(64) DEFAULT NULL,
  `UPDATE_TIME` datetime DEFAULT NULL,
  PRIMARY KEY (`ID`),
  KEY `IDX_BI_DATASET_OWNER` (`USER_ID`,`DB_CONFIG_ID`,`DEL_FLAG`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='大屏参数化数据集';

/*Data for the table `lm_bi_dataset` */


/*Table structure for table `lm_bi_refresh_log` */

DROP TABLE IF EXISTS `lm_bi_refresh_log`;

CREATE TABLE `lm_bi_refresh_log` (
  `ID` bigint(20) NOT NULL,
  `SCREEN_ID` bigint(20) NOT NULL,
  `SCREEN_VERSION_ID` bigint(20) DEFAULT NULL,
  `SNAPSHOT_ID` bigint(20) DEFAULT NULL,
  `TRIGGER_TYPE` varchar(16) NOT NULL,
  `STATUS` varchar(16) NOT NULL,
  `START_TIME` datetime NOT NULL,
  `END_TIME` datetime DEFAULT NULL,
  `DURATION_MS` bigint(20) DEFAULT '0',
  `ERROR_MSG` varchar(2000) DEFAULT NULL,
  `CREATE_BY` varchar(64) DEFAULT NULL,
  `CREATE_TIME` datetime DEFAULT NULL,
  PRIMARY KEY (`ID`),
  KEY `IDX_BI_REFRESH_LOG` (`SCREEN_ID`,`START_TIME`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='大屏刷新日志';

/*Data for the table `lm_bi_refresh_log` */

/*Table structure for table `lm_bi_screen` */

DROP TABLE IF EXISTS `lm_bi_screen`;

CREATE TABLE `lm_bi_screen` (
  `ID` bigint(20) NOT NULL,
  `OWNER_USER_ID` bigint(20) NOT NULL,
  `NAME` varchar(200) NOT NULL,
  `DESCRIPTION` varchar(500) DEFAULT NULL,
  `STATUS` varchar(16) NOT NULL DEFAULT 'DRAFT' COMMENT 'DRAFT/PUBLISHED/DISABLED',
  `DRAFT_CONFIG_JSON` mediumtext NOT NULL,
  `DRAFT_REVISION` int(11) NOT NULL DEFAULT '1',
  `PUBLISHED_VERSION_ID` bigint(20) DEFAULT NULL,
  `CURRENT_SNAPSHOT_ID` bigint(20) DEFAULT NULL,
  `REFRESH_MODE` varchar(24) NOT NULL DEFAULT 'LIVE' COMMENT 'LIVE/INTERVAL_SNAPSHOT',
  `REFRESH_INTERVAL_SECONDS` int(11) NOT NULL DEFAULT '300',
  `NEXT_REFRESH_TIME` datetime DEFAULT NULL,
  `LAST_REFRESH_TIME` datetime DEFAULT NULL,
  `LAST_REFRESH_STATUS` varchar(24) DEFAULT NULL,
  `LAST_REFRESH_ERROR` varchar(2000) DEFAULT NULL,
  `LEASE_UNTIL` datetime DEFAULT NULL,
  `DEL_FLAG` tinyint(1) NOT NULL DEFAULT '0',
  `CREATE_BY` varchar(64) DEFAULT NULL,
  `CREATE_TIME` datetime DEFAULT NULL,
  `UPDATE_BY` varchar(64) DEFAULT NULL,
  `UPDATE_TIME` datetime DEFAULT NULL,
  PRIMARY KEY (`ID`),
  KEY `IDX_BI_SCREEN_OWNER` (`OWNER_USER_ID`,`DEL_FLAG`,`UPDATE_TIME`),
  KEY `IDX_BI_SCREEN_DUE` (`STATUS`,`REFRESH_MODE`,`NEXT_REFRESH_TIME`,`DEL_FLAG`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='数据大屏';

/*Data for the table `lm_bi_screen` */


/*Table structure for table `lm_bi_screen_share` */

DROP TABLE IF EXISTS `lm_bi_screen_share`;

CREATE TABLE `lm_bi_screen_share` (
  `ID` bigint(20) NOT NULL COMMENT '主键（雪花）',
  `SCREEN_ID` bigint(20) NOT NULL COMMENT '大屏ID',
  `CREATOR_USER_ID` bigint(20) NOT NULL COMMENT '创建者（=大屏所有者）；匿名访问的数据身份',
  `TOKEN` varchar(64) NOT NULL COMMENT '随机令牌（32字节 base64url，43位）',
  `NAME` varchar(64) DEFAULT NULL COMMENT '链接名称（备注用途）',
  `DATA_MODE` varchar(16) NOT NULL DEFAULT 'SNAPSHOT' COMMENT 'SNAPSHOT=快照（默认） LIVE=以创建者身份实时查询',
  `SNAPSHOT_ID` bigint(20) DEFAULT NULL COMMENT '实时大屏的分享专用快照ID（定时快照大屏跟随大屏快照，为空）',
  `SNAPSHOT_VERSION_ID` bigint(20) DEFAULT NULL COMMENT '分享快照对应的发布版本ID',
  `SNAPSHOT_TIME` datetime DEFAULT NULL COMMENT '分享快照生成时间',
  `PASSWORD_HASH` varchar(100) DEFAULT NULL COMMENT '访问密码 BCrypt 哈希，空=无密码',
  `EXPIRE_TIME` datetime DEFAULT NULL COMMENT '过期时间，空=永久',
  `ALLOWED_HOSTS` varchar(1000) DEFAULT NULL COMMENT '允许嵌入(iframe)的站点，逗号分隔；空=不允许外站嵌入',
  `STATUS` varchar(16) NOT NULL DEFAULT 'ACTIVE' COMMENT 'ACTIVE/DISABLED/REVOKED（撤销为终态）',
  `VIEW_COUNT` bigint(20) NOT NULL DEFAULT '0' COMMENT '浏览次数（首屏加载计数，自动刷新不计）',
  `DENIED_COUNT` bigint(20) NOT NULL DEFAULT '0' COMMENT '被拒绝次数（密码错误/限流/过期/撤销等）',
  `LAST_ACCESS_TIME` datetime DEFAULT NULL COMMENT '最后访问时间',
  `REVOKE_TIME` datetime DEFAULT NULL COMMENT '撤销时间',
  `CREATE_BY` varchar(64) DEFAULT NULL,
  `CREATE_TIME` datetime DEFAULT NULL,
  `UPDATE_BY` varchar(64) DEFAULT NULL,
  `UPDATE_TIME` datetime DEFAULT NULL,
  PRIMARY KEY (`ID`),
  UNIQUE KEY `UK_BI_SCREEN_SHARE_TOKEN` (`TOKEN`),
  KEY `IDX_BI_SCREEN_SHARE_SCREEN` (`SCREEN_ID`,`STATUS`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='数据大屏分享链接';

/*Data for the table `lm_bi_screen_share` */

/*Table structure for table `lm_bi_screen_snapshot` */

DROP TABLE IF EXISTS `lm_bi_screen_snapshot`;

CREATE TABLE `lm_bi_screen_snapshot` (
  `ID` bigint(20) NOT NULL,
  `SCREEN_ID` bigint(20) NOT NULL,
  `SCREEN_VERSION_ID` bigint(20) NOT NULL,
  `STATUS` varchar(16) NOT NULL COMMENT 'SUCCESS/FAILED',
  `FILE_PATH` varchar(500) DEFAULT NULL,
  `CONTENT_HASH` char(64) DEFAULT NULL,
  `CONTENT_BYTES` bigint(20) DEFAULT '0',
  `ROW_COUNT` int(11) DEFAULT '0',
  `DURATION_MS` bigint(20) DEFAULT '0',
  `TRIGGER_TYPE` varchar(16) DEFAULT NULL COMMENT 'PUBLISH/MANUAL/SCHEDULE',
  `ERROR_MSG` varchar(2000) DEFAULT NULL,
  `GENERATED_AT` datetime DEFAULT NULL,
  `CREATE_BY` varchar(64) DEFAULT NULL,
  `CREATE_TIME` datetime DEFAULT NULL,
  PRIMARY KEY (`ID`),
  KEY `IDX_BI_SNAPSHOT_SCREEN` (`SCREEN_ID`,`GENERATED_AT`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='大屏数据快照';

/*Data for the table `lm_bi_screen_snapshot` */

/*Table structure for table `lm_bi_screen_version` */

DROP TABLE IF EXISTS `lm_bi_screen_version`;

CREATE TABLE `lm_bi_screen_version` (
  `ID` bigint(20) NOT NULL,
  `SCREEN_ID` bigint(20) NOT NULL,
  `VERSION_NO` int(11) NOT NULL,
  `STATUS` varchar(16) NOT NULL DEFAULT 'PREPARING' COMMENT 'PREPARING/ACTIVE/FAILED',
  `CONFIG_JSON` mediumtext NOT NULL COMMENT '冻结的内部配置，包含SQL执行清单',
  `CONFIG_HASH` char(64) NOT NULL,
  `PUBLISH_USER_ID` bigint(20) NOT NULL,
  `CREATE_BY` varchar(64) DEFAULT NULL,
  `CREATE_TIME` datetime DEFAULT NULL,
  `UPDATE_BY` varchar(64) DEFAULT NULL,
  `UPDATE_TIME` datetime DEFAULT NULL,
  PRIMARY KEY (`ID`),
  UNIQUE KEY `UK_BI_SCREEN_VERSION` (`SCREEN_ID`,`VERSION_NO`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='不可变大屏发布版本';

/*Data for the table `lm_bi_screen_version` */


/*Table structure for table `lm_etl_notify` */

DROP TABLE IF EXISTS `lm_etl_notify`;

CREATE TABLE `lm_etl_notify` (
  `WORKSPACE_ID` bigint(20) NOT NULL,
  `USER_ID` bigint(20) NOT NULL,
  `ENABLED` tinyint(4) NOT NULL DEFAULT '0',
  `ON_FAILURE` tinyint(4) NOT NULL DEFAULT '1',
  `CHANNEL_IDS_JSON` longtext NOT NULL,
  `REVISION` int(11) NOT NULL,
  `UPDATED_AT` bigint(20) NOT NULL,
  PRIMARY KEY (`WORKSPACE_ID`),
  KEY `IDX_ETL_NOTIFY_USER` (`USER_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='ETL工作区消息通知';

/*Data for the table `lm_etl_notify` */

/*Table structure for table `lm_etl_run` */

DROP TABLE IF EXISTS `lm_etl_run`;

CREATE TABLE `lm_etl_run` (
  `ID` varchar(32) NOT NULL,
  `WORKSPACE_ID` bigint(20) NOT NULL,
  `USER_ID` bigint(20) NOT NULL,
  `PIPELINE_ID` varchar(128) NOT NULL,
  `PIPELINE_NAME` varchar(200) DEFAULT NULL,
  `REVISION` int(11) NOT NULL,
  `STATUS` varchar(16) NOT NULL,
  `ACTIVE_KEY` varchar(255) DEFAULT NULL COMMENT '同一工作区任务仅允许一个活动运行',
  `CONFIG_JSON` longtext NOT NULL,
  `STEPS_JSON` longtext NOT NULL,
  `MESSAGE` varchar(500) DEFAULT NULL,
  `STARTED_AT` bigint(20) NOT NULL,
  `FINISHED_AT` bigint(20) DEFAULT NULL,
  `CANCEL_REQUESTED` tinyint(4) NOT NULL DEFAULT '0',
  `OWNER_TOKEN` varchar(36) DEFAULT NULL COMMENT '运行所有权令牌',
  `LEASE_UNTIL` bigint(20) DEFAULT NULL COMMENT '心跳租约截止时间',
  PRIMARY KEY (`ID`),
  UNIQUE KEY `UK_ETL_ACTIVE` (`ACTIVE_KEY`),
  KEY `IDX_ETL_RUN_USER` (`USER_ID`,`WORKSPACE_ID`,`STARTED_AT`),
  KEY `IDX_ETL_RUN_LEASE` (`STATUS`,`LEASE_UNTIL`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='SQL ETL执行记录';

/*Data for the table `lm_etl_run` */


/*Table structure for table `lm_etl_run_log` */

DROP TABLE IF EXISTS `lm_etl_run_log`;

CREATE TABLE `lm_etl_run_log` (
  `ID` varchar(32) NOT NULL,
  `RUN_ID` varchar(32) NOT NULL,
  `NODE_ID` varchar(128) DEFAULT NULL,
  `LEVEL` varchar(8) NOT NULL,
  `STATUS` varchar(20) NOT NULL,
  `ROW_COUNT` bigint(20) NOT NULL DEFAULT '0',
  `MESSAGE` varchar(500) DEFAULT NULL,
  `CREATED_AT` bigint(20) NOT NULL,
  PRIMARY KEY (`ID`),
  KEY `IDX_ETL_LOG_RUN` (`RUN_ID`,`CREATED_AT`),
  KEY `IDX_ETL_LOG_NODE` (`RUN_ID`,`NODE_ID`,`CREATED_AT`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='ETL任务节点分页批次日志';

/*Data for the table `lm_etl_run_log` */


/*Table structure for table `lm_etl_schedule` */

DROP TABLE IF EXISTS `lm_etl_schedule`;

CREATE TABLE `lm_etl_schedule` (
  `WORKSPACE_ID` bigint(20) NOT NULL,
  `USER_ID` bigint(20) NOT NULL,
  `OWNER_TYPE` varchar(16) NOT NULL,
  `ROLE_ID` bigint(20) NOT NULL,
  `ENABLED` tinyint(4) NOT NULL DEFAULT '0',
  `REVISION` int(11) NOT NULL,
  `PUBLISHED_VERSION` int(11) NOT NULL,
  `PIPELINE_IDS_JSON` longtext NOT NULL,
  `STEPS_JSON` longtext COMMENT '有序工作区步骤快照（含前置与本工作区）',
  `MODE` varchar(16) NOT NULL,
  `TIME_ZONE` varchar(80) NOT NULL,
  `CRON_EXPRESSION` varchar(160) DEFAULT NULL,
  `TIME_OF_DAY` varchar(5) DEFAULT NULL,
  `WEEK_DAYS_JSON` varchar(64) NOT NULL,
  `INTERVAL_MINUTES` int(11) DEFAULT NULL,
  `RUN_AT` bigint(20) DEFAULT NULL,
  `NEXT_FIRE_AT` bigint(20) DEFAULT NULL,
  `UPDATED_AT` bigint(20) NOT NULL,
  PRIMARY KEY (`WORKSPACE_ID`),
  KEY `IDX_ETL_SCHEDULE_DUE` (`ENABLED`,`NEXT_FIRE_AT`),
  KEY `IDX_ETL_SCHEDULE_USER` (`USER_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='ETL工作区定时计划';

/*Data for the table `lm_etl_schedule` */

/*Table structure for table `lm_etl_schedule_fire` */

DROP TABLE IF EXISTS `lm_etl_schedule_fire`;

CREATE TABLE `lm_etl_schedule_fire` (
  `ID` varchar(32) NOT NULL,
  `WORKSPACE_ID` bigint(20) NOT NULL,
  `USER_ID` bigint(20) NOT NULL,
  `OWNER_TYPE` varchar(16) NOT NULL,
  `ROLE_ID` bigint(20) NOT NULL,
  `PUBLISHED_VERSION` int(11) NOT NULL,
  `PIPELINE_IDS_JSON` longtext NOT NULL,
  `JOBS_JSON` longtext COMMENT '展开后的有序作业快照（workspaceId+version+pipelineId）',
  `RUN_IDS_JSON` longtext NOT NULL,
  `NEXT_INDEX` int(11) NOT NULL DEFAULT '0',
  `CURRENT_RUN_ID` varchar(32) DEFAULT NULL,
  `STATUS` varchar(16) NOT NULL,
  `MESSAGE` varchar(500) DEFAULT NULL,
  `SCHEDULED_AT` bigint(20) NOT NULL,
  `CREATED_AT` bigint(20) NOT NULL,
  `FINISHED_AT` bigint(20) DEFAULT NULL,
  `ACTIVE_KEY` varchar(64) DEFAULT NULL,
  `LEASE_TOKEN` varchar(36) DEFAULT NULL,
  `LEASE_UNTIL` bigint(20) DEFAULT NULL,
  PRIMARY KEY (`ID`),
  UNIQUE KEY `UK_ETL_SCHEDULE_ACTIVE` (`ACTIVE_KEY`),
  KEY `IDX_ETL_SCHEDULE_FIRE_ACTIVE` (`STATUS`,`LEASE_UNTIL`),
  KEY `IDX_ETL_SCHEDULE_FIRE_USER` (`USER_ID`,`WORKSPACE_ID`,`CREATED_AT`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='ETL定时触发审计及串行批次';

/*Data for the table `lm_etl_schedule_fire` */

/*Table structure for table `lm_etl_workspace` */

DROP TABLE IF EXISTS `lm_etl_workspace`;

CREATE TABLE `lm_etl_workspace` (
  `ID` bigint(20) NOT NULL COMMENT '任务区ID',
  `USER_ID` bigint(20) NOT NULL COMMENT '创建用户ID',
  `WORKSPACE_NAME` varchar(100) NOT NULL COMMENT '任务区名称',
  `DESCRIPTION` varchar(500) DEFAULT NULL COMMENT '任务区说明',
  `DRAFT_JSON` longtext NOT NULL COMMENT '当前草稿JSON',
  `REVISION` int(11) NOT NULL DEFAULT '1' COMMENT '草稿乐观锁版本',
  `PUBLISHED_VERSION` int(11) NOT NULL DEFAULT '0' COMMENT '最近发布版本号',
  `STATUS` varchar(16) NOT NULL DEFAULT 'DRAFT' COMMENT 'DRAFT/PUBLISHED',
  `DEL_FLAG` tinyint(4) NOT NULL DEFAULT '0' COMMENT '逻辑删除',
  `CREATE_BY` varchar(64) DEFAULT NULL,
  `CREATE_TIME` datetime DEFAULT NULL,
  `UPDATE_BY` varchar(64) DEFAULT NULL,
  `UPDATE_TIME` datetime DEFAULT NULL,
  PRIMARY KEY (`ID`),
  KEY `IDX_ETL_WORKSPACE_USER` (`USER_ID`,`DEL_FLAG`,`UPDATE_TIME`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='ETL任务区';

/*Data for the table `lm_etl_workspace` */


/*Table structure for table `lm_etl_workspace_version` */

DROP TABLE IF EXISTS `lm_etl_workspace_version`;

CREATE TABLE `lm_etl_workspace_version` (
  `ID` bigint(20) NOT NULL COMMENT '版本ID',
  `WORKSPACE_ID` bigint(20) NOT NULL COMMENT '任务区ID',
  `USER_ID` bigint(20) NOT NULL COMMENT '发布用户ID',
  `VERSION_NO` int(11) NOT NULL COMMENT '版本号',
  `CONFIG_JSON` longtext NOT NULL COMMENT '不可变配置JSON',
  `CONTENT_HASH` char(64) NOT NULL COMMENT '配置SHA-256',
  `CREATE_BY` varchar(64) DEFAULT NULL,
  `CREATE_TIME` datetime DEFAULT NULL,
  `UPDATE_BY` varchar(64) DEFAULT NULL,
  `UPDATE_TIME` datetime DEFAULT NULL,
  PRIMARY KEY (`ID`),
  UNIQUE KEY `UK_ETL_WORKSPACE_VERSION` (`WORKSPACE_ID`,`VERSION_NO`),
  KEY `IDX_ETL_VERSION_USER` (`USER_ID`,`CREATE_TIME`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='ETL任务区发布版本';

/*Data for the table `lm_etl_workspace_version` */

/*Table structure for table `lm_invite_code` */

DROP TABLE IF EXISTS `lm_invite_code`;

CREATE TABLE `lm_invite_code` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '邀请码ID',
  `invite_code` varchar(32) NOT NULL COMMENT '邀请码',
  `member_user_id` bigint(20) NOT NULL COMMENT '所属会员用户ID',
  `parent_invite_code` varchar(32) DEFAULT NULL COMMENT '父邀请码',
  `GIFT_API_COUNT` int(11) DEFAULT '0' COMMENT '福利API次数（使用该邀请码注册的用户可获得的免费API调用次数）',
  `status` int(1) DEFAULT '0' COMMENT '状态 0正常 1停用',
  `expire_time` date DEFAULT NULL COMMENT '过期时间',
  `used` int(1) DEFAULT '0' COMMENT '是否已使用 0未使用 1已使用',
  `used_by_member_user_id` bigint(20) DEFAULT NULL COMMENT '使用者会员用户ID',
  `used_time` datetime DEFAULT NULL COMMENT '使用时间',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_invite_code` (`invite_code`),
  KEY `idx_member_user_id` (`member_user_id`),
  KEY `idx_parent_invite_code` (`parent_invite_code`),
  KEY `idx_used_by_member_user_id` (`used_by_member_user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='邀请码表';

/*Data for the table `lm_invite_code` */

/*Table structure for table `lm_jeepay_merchant_config` */

DROP TABLE IF EXISTS `lm_jeepay_merchant_config`;

CREATE TABLE `lm_jeepay_merchant_config` (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `CONFIG_NAME` varchar(100) NOT NULL COMMENT '配置名称',
  `MCH_NO` varchar(50) NOT NULL COMMENT '商户号',
  `APP_ID` varchar(50) NOT NULL COMMENT '应用ID',
  `API_KEY` varchar(500) NOT NULL COMMENT 'API密钥（加密存储）',
  `API_BASE` varchar(200) NOT NULL COMMENT 'API基础地址',
  `NOTIFY_URL` varchar(500) NOT NULL COMMENT '支付通知回调地址',
  `RETURN_URL` varchar(500) DEFAULT NULL COMMENT '支付成功跳转地址',
  `ORDER_EXPIRE_SECONDS` int(11) NOT NULL DEFAULT '1800' COMMENT '订单超时时间（秒）',
  `SANDBOX` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否沙箱环境（0-否 1-是）',
  `STATUS` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否启用（0-禁用 1-启用）',
  `IS_DEFAULT` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否默认配置（0-否 1-是）',
  `pay_channels` varchar(200) DEFAULT NULL COMMENT '支持的支付通道（多个用逗号分隔，如：ALI_QR,WX_NATIVE 或 ALI_APP,WX_APP，留空表示支持所有通道）',
  `REMARK` varchar(500) DEFAULT NULL COMMENT '备注',
  `DELETED` tinyint(1) NOT NULL DEFAULT '0' COMMENT '删除标记（0-未删除 1-已删除）',
  `CREATE_TIME` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `UPDATE_TIME` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `CREATE_USER_ID` bigint(20) DEFAULT NULL COMMENT '创建人ID',
  `UPDATE_USER_ID` bigint(20) DEFAULT NULL COMMENT '更新人ID',
  PRIMARY KEY (`ID`),
  KEY `IDX_MCH_NO` (`MCH_NO`),
  KEY `IDX_APP_ID` (`APP_ID`),
  KEY `IDX_STATUS` (`STATUS`),
  KEY `IDX_IS_DEFAULT` (`IS_DEFAULT`),
  KEY `IDX_DELETED` (`DELETED`),
  KEY `idx_pay_channels` (`pay_channels`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COMMENT='JEEPAY商户配置表';

/*Data for the table `lm_jeepay_merchant_config` */


/*Table structure for table `lm_member_level` */

DROP TABLE IF EXISTS `lm_member_level`;

CREATE TABLE `lm_member_level` (
  `ID` bigint(11) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `LEVEL` int(3) DEFAULT NULL COMMENT '等级权重',
  `LEVEL_NAME` varchar(50) DEFAULT NULL COMMENT '等级名称',
  `MIN_INTEGRAL` int(9) DEFAULT NULL COMMENT '最小所需积分',
  `MAX_INTEGRAL` int(9) DEFAULT NULL COMMENT '最大所需积分',
  `DISCOUNT` decimal(3,2) DEFAULT NULL COMMENT '等级权益',
  `ORDER_NUM` int(5) DEFAULT NULL COMMENT '排序',
  `REMARK` varchar(500) DEFAULT NULL COMMENT '备注',
  `DATA_STATUS` int(1) DEFAULT NULL COMMENT '状态',
  `DEL_FLAG` int(1) DEFAULT NULL COMMENT '删除标识',
  `CREATE_BY` varchar(50) DEFAULT NULL COMMENT '创建人',
  `CREATE_TIME` datetime DEFAULT NULL COMMENT '创建时间',
  `UPDATE_BY` varchar(50) DEFAULT NULL COMMENT '更新人',
  `UPDATE_TIME` datetime DEFAULT NULL COMMENT '更新时间',
  `level_code` varchar(20) DEFAULT NULL COMMENT '等级编码',
  `month_price` decimal(10,2) DEFAULT NULL COMMENT '月费价格',
  `quarter_price` decimal(10,2) DEFAULT NULL COMMENT '季费价格',
  `year_price` decimal(10,2) DEFAULT NULL COMMENT '年费价格',
  `level_desc` varchar(1000) DEFAULT NULL COMMENT '等级描述',
  `permissions` varchar(2000) DEFAULT NULL COMMENT '等级权限配置',
  `half_year_price` decimal(10,2) DEFAULT NULL COMMENT '半年费价格',
  `MONTH_API_QUOTA` int(11) DEFAULT '30' COMMENT '月费API调用次数（-1表示无限）',
  `QUARTER_API_QUOTA` int(11) DEFAULT '90' COMMENT '季费API调用次数（-1表示无限）',
  `HALF_YEAR_API_QUOTA` int(11) DEFAULT '180' COMMENT '半年费API调用次数（-1表示无限）',
  `YEAR_API_QUOTA` int(11) DEFAULT '-1' COMMENT '年费API调用次数（-1表示无限）',
  `DISCOUNT_DISPLAY` decimal(3,2) DEFAULT '1.00' COMMENT '折扣显示（1为不显示折扣，小于1显示折扣信息，如0.9表示9折）',
  `MONTH_CHAT_QUOTA` int(11) DEFAULT '50' COMMENT '月费对话额度（-1表示无限，单位为总量非次数）',
  `QUARTER_CHAT_QUOTA` int(11) DEFAULT '150' COMMENT '季费对话额度（-1表示无限）',
  `HALF_YEAR_CHAT_QUOTA` int(11) DEFAULT '300' COMMENT '半年费对话额度（-1表示无限）',
  `YEAR_CHAT_QUOTA` int(11) DEFAULT '-1' COMMENT '年费对话额度（-1表示无限）',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE KEY `uk_level_code` (`level_code`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COMMENT='会员等级表-支持积分制和付费制';

/*Data for the table `lm_member_level` */


/*Table structure for table `lm_member_order` */

DROP TABLE IF EXISTS `lm_member_order`;

CREATE TABLE `lm_member_order` (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '订单ID',
  `ORDER_NO` varchar(64) NOT NULL COMMENT '订单号',
  `MEMBER_USER_ID` bigint(20) NOT NULL COMMENT '会员用户ID',
  `ORDER_TYPE` tinyint(2) NOT NULL DEFAULT '1' COMMENT '订单类型：1-会员套餐 2-单次接口',
  `MEMBER_LEVEL_ID` bigint(20) DEFAULT NULL COMMENT '会员等级ID（会员套餐订单时必填）',
  `PACKAGE_TYPE` tinyint(2) DEFAULT NULL COMMENT '套餐类型：1-月费 2-季费 3-半年费 4-年费（会员套餐订单时必填）',
  `API_COUNT` int(11) DEFAULT NULL COMMENT 'API调用次数（单次接口订单时必填）',
  `ORDER_AMOUNT` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '订单金额',
  `DISCOUNT_AMOUNT` decimal(10,2) DEFAULT '0.00' COMMENT '优惠金额',
  `ACTUAL_AMOUNT` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '实际支付金额',
  `ORDER_STATUS` tinyint(2) NOT NULL DEFAULT '1' COMMENT '订单状态：1-待支付 2-已支付 3-已取消 4-已退款 5-已过期',
  `PAY_STATUS` tinyint(2) NOT NULL DEFAULT '0' COMMENT '支付状态：0-未支付 1-支付中 2-支付成功 3-支付失败',
  `PAY_TIME` datetime DEFAULT NULL COMMENT '支付时间',
  `EXPIRE_TIME` datetime DEFAULT NULL COMMENT '订单过期时间',
  `CANCEL_TIME` datetime DEFAULT NULL COMMENT '取消时间',
  `ORDER_DESC` varchar(500) DEFAULT NULL COMMENT '订单描述',
  `REMARK` varchar(500) DEFAULT NULL COMMENT '备注',
  `CREATE_BY` varchar(64) DEFAULT NULL COMMENT '创建者',
  `CREATE_TIME` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `UPDATE_BY` varchar(64) DEFAULT NULL COMMENT '更新者',
  `UPDATE_TIME` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `DEL_FLAG` tinyint(1) DEFAULT '0' COMMENT '删除标识：0-未删除 1-已删除',
  `REFUND_TIME` datetime DEFAULT NULL COMMENT '退款时间',
  PRIMARY KEY (`ID`),
  UNIQUE KEY `UK_ORDER_NO` (`ORDER_NO`),
  KEY `IDX_MEMBER_USER_ID` (`MEMBER_USER_ID`),
  KEY `IDX_ORDER_STATUS` (`ORDER_STATUS`),
  KEY `IDX_PAY_STATUS` (`PAY_STATUS`),
  KEY `IDX_CREATE_TIME` (`CREATE_TIME`),
  KEY `IDX_REFUND_TIME` (`REFUND_TIME`)
) ENGINE=InnoDB AUTO_INCREMENT=108 DEFAULT CHARSET=utf8mb4 COMMENT='会员订单表';

/*Data for the table `lm_member_order` */


/*Table structure for table `lm_member_subscription` */

DROP TABLE IF EXISTS `lm_member_subscription`;

CREATE TABLE `lm_member_subscription` (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '订阅ID',
  `MEMBER_USER_ID` bigint(20) NOT NULL COMMENT '会员用户ID',
  `ORDER_NO` varchar(64) NOT NULL COMMENT '订单号',
  `MEMBER_LEVEL_ID` bigint(20) NOT NULL COMMENT '会员等级ID',
  `PACKAGE_TYPE` tinyint(2) NOT NULL COMMENT '套餐类型：1-月费 2-季费 3-半年费 4-年费',
  `START_TIME` datetime NOT NULL COMMENT '生效时间',
  `END_TIME` datetime NOT NULL COMMENT '到期时间',
  `STATUS` tinyint(2) NOT NULL DEFAULT '1' COMMENT '状态：1-生效中 2-已过期 3-已取消',
  `IS_AUTO_RENEW` tinyint(1) DEFAULT '0' COMMENT '是否自动续费：0-否 1-是',
  `CANCEL_TIME` datetime DEFAULT NULL COMMENT '取消时间',
  `REMARK` varchar(500) DEFAULT NULL COMMENT '备注',
  `CREATE_BY` varchar(64) DEFAULT NULL COMMENT '创建者',
  `CREATE_TIME` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `UPDATE_BY` varchar(64) DEFAULT NULL COMMENT '更新者',
  `UPDATE_TIME` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `DEL_FLAG` tinyint(1) DEFAULT '0' COMMENT '删除标识：0-未删除 1-已删除',
  `TOTAL_API_QUOTA` int(11) DEFAULT '0' COMMENT '总API调用次数配额（-1表示无限）',
  `REMAIN_API_QUOTA` int(11) DEFAULT '0' COMMENT '剩余API调用次数（-1表示无限）',
  `STOP_COUNT` int(11) DEFAULT '0' COMMENT '中止返还次数：用户主动中止时归还到此池，下次鉴权优先消耗，为0则消耗普通次数',
  `USED_REFUND_COUNT` int(11) NOT NULL DEFAULT '0' COMMENT '已使用的返还次数（消耗stopCount时+1，程序异常归还时-1，不能超过stopCount总量）',
  `TOTAL_CHAT_QUOTA` int(11) DEFAULT '0' COMMENT '总对话额度（-1表示无限，单位为总量非次数）',
  `REMAIN_CHAT_QUOTA` int(11) DEFAULT '0' COMMENT '剩余对话额度（-1表示无限）',
  PRIMARY KEY (`ID`),
  UNIQUE KEY `UK_MEMBER_SUBSCRIPTION_ORDER_NO` (`ORDER_NO`),
  KEY `IDX_MEMBER_USER_ID` (`MEMBER_USER_ID`),
  KEY `IDX_ORDER_NO` (`ORDER_NO`),
  KEY `IDX_STATUS` (`STATUS`),
  KEY `IDX_END_TIME` (`END_TIME`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COMMENT='会员订阅记录表';

/*Data for the table `lm_member_subscription` */


/*Table structure for table `lm_member_user` */

DROP TABLE IF EXISTS `lm_member_user`;

CREATE TABLE `lm_member_user` (
  `ID` bigint(11) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `AVATAR` text COMMENT '头像',
  `USER_NAME` varchar(30) DEFAULT NULL COMMENT '用户名',
  `PASSWORD` varchar(50) DEFAULT NULL COMMENT '密码',
  `REAL_NAME` varchar(30) DEFAULT NULL COMMENT '真实名称',
  `EMAIL` varchar(50) DEFAULT NULL COMMENT '邮箱',
  `PHONE_NUMBER` varchar(11) DEFAULT NULL COMMENT '手机号',
  `USER_GROUP` varchar(40) DEFAULT NULL COMMENT '会员组',
  `USER_LEVEL` varchar(10) DEFAULT NULL COMMENT '会员等级',
  `INTEGRAL` decimal(13,2) DEFAULT NULL COMMENT '会员积分',
  `SEX` varchar(1) DEFAULT NULL COMMENT '性别',
  `USER_STATUS` varchar(1) DEFAULT NULL COMMENT '会员状态',
  `PERSONAL_SIGNATURE` varchar(500) DEFAULT NULL COMMENT '个性签名',
  `DEL_FLAG` int(1) DEFAULT NULL COMMENT '删除标识',
  `CREATE_BY` varchar(50) DEFAULT NULL COMMENT '创建人',
  `CREATE_TIME` datetime DEFAULT NULL COMMENT '创建时间',
  `UPDATE_BY` varchar(50) DEFAULT NULL COMMENT '更新人',
  `UPDATE_TIME` datetime DEFAULT NULL COMMENT '更新时间',
  `SCHOOL` varchar(50) DEFAULT NULL,
  `ROLE_ID` bigint(11) DEFAULT NULL COMMENT '角色',
  `member_level_id` bigint(20) DEFAULT NULL COMMENT '会员等级ID',
  `INVITE_CODE` varchar(20) DEFAULT NULL COMMENT '用户邀请码',
  `OPEN_PERMISSION` int(1) DEFAULT '0' COMMENT '是否开放权限（0-否 1-是）',
  `OPEN_PERMISSION_EXPIRE_TIME` datetime DEFAULT NULL COMMENT '开放权限到期时间',
  `REGISTER_SOURCE` varchar(20) DEFAULT NULL,
  `REGISTER_IP` varchar(50) DEFAULT NULL,
  `IP_WHITELIST` varchar(2000) DEFAULT NULL COMMENT 'login ip whitelist',
  `WX_UNION_ID` varchar(64) DEFAULT NULL COMMENT '微信 unionid（跨端统一标识）',
  `WX_MP_OPEN_ID` varchar(64) DEFAULT NULL COMMENT '微信小程序 openid',
  `WX_APP_OPEN_ID` varchar(64) DEFAULT NULL COMMENT '微信移动应用 openid',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE KEY `UK_MEMBER_WX_UNION_ID` (`WX_UNION_ID`),
  UNIQUE KEY `UK_MEMBER_WX_MP_OPEN_ID` (`WX_MP_OPEN_ID`),
  UNIQUE KEY `UK_MEMBER_WX_APP_OPEN_ID` (`WX_APP_OPEN_ID`),
  KEY `idx_member_level_id` (`member_level_id`)
) ENGINE=InnoDB AUTO_INCREMENT=1418813380748421 DEFAULT CHARSET=utf8mb4 COMMENT='会员用户表-支持会员等级关联';

/*Data for the table `lm_member_user` */


/*Table structure for table `lm_member_user_group` */

DROP TABLE IF EXISTS `lm_member_user_group`;

CREATE TABLE `lm_member_user_group` (
  `ID` bigint(20) NOT NULL COMMENT '主键',
  `GROUP_NAME` varchar(100) NOT NULL COMMENT '组名称',
  `DESCRIPTION` varchar(500) DEFAULT NULL COMMENT '描述',
  `ORDER_NUM` int(4) DEFAULT '0' COMMENT '排序',
  `DEL_FLAG` tinyint(1) DEFAULT '0' COMMENT '删除标识',
  `CREATE_BY` varchar(64) DEFAULT NULL,
  `CREATE_TIME` datetime DEFAULT NULL,
  `UPDATE_BY` varchar(64) DEFAULT NULL,
  `UPDATE_TIME` datetime DEFAULT NULL,
  PRIMARY KEY (`ID`),
  KEY `IDX_GROUP_NAME` (`GROUP_NAME`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='会员组(部门)';

/*Data for the table `lm_member_user_group` */


/*Table structure for table `lm_notify_channel` */

DROP TABLE IF EXISTS `lm_notify_channel`;

CREATE TABLE `lm_notify_channel` (
  `ID` bigint(20) NOT NULL,
  `USER_ID` bigint(20) NOT NULL,
  `CHANNEL_TYPE` varchar(16) NOT NULL COMMENT 'WECOM/DINGTALK/FEISHU',
  `CHANNEL_NAME` varchar(64) NOT NULL,
  `ENABLED` tinyint(4) NOT NULL DEFAULT '1',
  `WEBHOOK_URL` varchar(1000) NOT NULL,
  `SECRET` varchar(255) DEFAULT NULL COMMENT '加签密钥，可空',
  `KEYWORD` varchar(64) DEFAULT NULL COMMENT '安全关键词，发送时若正文没有则自动追加',
  `DEL_FLAG` tinyint(4) NOT NULL DEFAULT '0',
  `CREATE_BY` varchar(64) DEFAULT NULL,
  `CREATE_TIME` datetime DEFAULT NULL,
  `UPDATE_BY` varchar(64) DEFAULT NULL,
  `UPDATE_TIME` datetime DEFAULT NULL,
  PRIMARY KEY (`ID`),
  KEY `IDX_NOTIFY_CHANNEL_USER` (`USER_ID`,`DEL_FLAG`,`ENABLED`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='消息通知渠道';

/*Data for the table `lm_notify_channel` */

/*Table structure for table `lm_parameter` */

DROP TABLE IF EXISTS `lm_parameter`;

CREATE TABLE `lm_parameter` (
  `ID` bigint(11) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `TITLE` varchar(50) DEFAULT NULL COMMENT '标题',
  `CODE` varchar(30) DEFAULT NULL COMMENT '编码',
  `VALUE1` varchar(200) DEFAULT NULL COMMENT '值1',
  `VALUE2` varchar(200) DEFAULT NULL COMMENT '值2',
  `ORDER_NUM` int(4) DEFAULT NULL COMMENT '排序',
  `REMARK` varchar(500) DEFAULT NULL COMMENT '描述',
  `DEL_FLAG` int(1) DEFAULT NULL COMMENT '删除标识',
  `CREATE_BY` varchar(50) DEFAULT NULL COMMENT '创建人',
  `CREATE_TIME` datetime DEFAULT NULL COMMENT '创建时间',
  `UPDATE_BY` varchar(50) DEFAULT NULL COMMENT '更新人',
  `UPDATE_TIME` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

/*Data for the table `lm_parameter` */

/*Table structure for table `lm_payment_record` */

DROP TABLE IF EXISTS `lm_payment_record`;

CREATE TABLE `lm_payment_record` (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '支付记录ID',
  `ORDER_NO` varchar(64) NOT NULL COMMENT '订单号',
  `PAYMENT_NO` varchar(64) NOT NULL COMMENT '支付流水号',
  `MEMBER_USER_ID` bigint(20) NOT NULL COMMENT '会员用户ID',
  `PAY_CHANNEL` varchar(20) NOT NULL COMMENT '支付渠道：ALI_QR-支付宝扫码 WX_NATIVE-微信扫码 ALI_APP-支付宝APP WX_APP-微信APP',
  `PAY_METHOD` varchar(20) NOT NULL COMMENT '支付方式：ALIPAY-支付宝 WECHAT-微信',
  `PAY_AMOUNT` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '支付金额',
  `PAY_STATUS` tinyint(2) NOT NULL DEFAULT '0' COMMENT '支付状态：0-未支付 1-支付中 2-支付成功 3-支付失败 4-已关闭',
  `JEEPAY_ORDER_ID` varchar(64) DEFAULT NULL COMMENT 'JEEPAY订单ID',
  `JEEPAY_RESPONSE` text COMMENT 'JEEPAY响应数据',
  `QR_CODE_URL` varchar(500) DEFAULT NULL COMMENT '二维码URL（扫码支付时使用）',
  `pay_data` text COMMENT '支付订单数据（APP支付时使用）',
  `PAY_TIME` datetime DEFAULT NULL COMMENT '支付完成时间',
  `CALLBACK_TIME` datetime DEFAULT NULL COMMENT '回调时间',
  `CALLBACK_DATA` text COMMENT '回调数据',
  `ERROR_CODE` varchar(64) DEFAULT NULL COMMENT '错误码',
  `ERROR_MSG` varchar(500) DEFAULT NULL COMMENT '错误信息',
  `REFUND_STATUS` tinyint(2) DEFAULT '0' COMMENT '退款状态：0-未退款 1-退款中 2-退款成功 3-退款失败',
  `REFUND_AMOUNT` decimal(10,2) DEFAULT '0.00' COMMENT '退款金额',
  `REFUND_TIME` datetime DEFAULT NULL COMMENT '退款时间',
  `REMARK` varchar(500) DEFAULT NULL COMMENT '备注',
  `CREATE_BY` varchar(64) DEFAULT NULL COMMENT '创建者',
  `CREATE_TIME` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `UPDATE_BY` varchar(64) DEFAULT NULL COMMENT '更新者',
  `UPDATE_TIME` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `DEL_FLAG` tinyint(1) DEFAULT '0' COMMENT '删除标识：0-未删除 1-已删除',
  `CHANNEL_ORDER_NO` varchar(128) DEFAULT NULL COMMENT '渠道订单号（支付宝/微信的交易流水号）',
  PRIMARY KEY (`ID`),
  UNIQUE KEY `UK_PAYMENT_NO` (`PAYMENT_NO`),
  UNIQUE KEY `UK_PAYMENT_RECORD_CHANNEL_ORDER_NO` (`CHANNEL_ORDER_NO`),
  KEY `IDX_ORDER_NO` (`ORDER_NO`),
  KEY `IDX_MEMBER_USER_ID` (`MEMBER_USER_ID`),
  KEY `IDX_PAY_STATUS` (`PAY_STATUS`),
  KEY `IDX_JEEPAY_ORDER_ID` (`JEEPAY_ORDER_ID`),
  KEY `IDX_CREATE_TIME` (`CREATE_TIME`),
  KEY `IDX_CHANNEL_ORDER_NO` (`CHANNEL_ORDER_NO`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='支付记录表';

/*Data for the table `lm_payment_record` */

/*Table structure for table `lm_privacy_policy` */

DROP TABLE IF EXISTS `lm_privacy_policy`;

CREATE TABLE `lm_privacy_policy` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `policy_type` varchar(50) NOT NULL COMMENT '政策类型：privacy_policy-隐私政策, user_agreement-用户协议, cancellation_process-注销流程, children_policy-儿童隐私政策',
  `title` varchar(200) NOT NULL COMMENT '政策标题',
  `content` longtext NOT NULL COMMENT '政策内容',
  `version` varchar(20) NOT NULL COMMENT '版本号',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态：0-禁用，1-启用',
  `sort_order` int(11) DEFAULT '0' COMMENT '排序',
  `effective_date` datetime DEFAULT NULL COMMENT '生效日期',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_by` varchar(64) DEFAULT NULL COMMENT '创建人',
  `update_by` varchar(64) DEFAULT NULL COMMENT '更新人',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`),
  KEY `idx_policy_type` (`policy_type`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COMMENT='隐私政策表';

/*Data for the table `lm_privacy_policy` */


/*Table structure for table `lm_redis_connection` */

DROP TABLE IF EXISTS `lm_redis_connection`;

CREATE TABLE `lm_redis_connection` (
  `ID` bigint(20) NOT NULL,
  `CONNECTION_NAME` varchar(120) NOT NULL,
  `MODE` varchar(16) NOT NULL DEFAULT 'STANDALONE' COMMENT 'STANDALONE/CLUSTER',
  `HOST_NAME` varchar(255) DEFAULT NULL,
  `PORT` int(11) DEFAULT '6379',
  `CLUSTER_NODES` varchar(2000) DEFAULT NULL COMMENT '逗号或换行分隔 host:port',
  `USERNAME` varchar(128) DEFAULT NULL,
  `PASSWORD_ENC` varchar(1000) DEFAULT NULL,
  `TLS_ENABLED` tinyint(1) NOT NULL DEFAULT '0',
  `TIMEOUT_MS` int(11) NOT NULL DEFAULT '5000',
  `DATABASE_COUNT` int(11) NOT NULL DEFAULT '16',
  `ORDER_NUM` int(11) NOT NULL DEFAULT '0' COMMENT '连接列表排序，越小越靠前',
  `VALUE_CHARSET` varchar(16) NOT NULL DEFAULT 'UTF-8' COMMENT '键值文本解码字符集',
  `DISPLAY_MODE` varchar(16) NOT NULL DEFAULT 'TEXT' COMMENT '键值显示模式 TEXT/HEX/BASE64',
  `OWNER_USER_ID` bigint(20) NOT NULL,
  `IS_PUBLIC` tinyint(1) NOT NULL DEFAULT '0' COMMENT '公开连接只读',
  `DEL_FLAG` tinyint(1) NOT NULL DEFAULT '0',
  `CREATE_BY` varchar(64) DEFAULT NULL,
  `CREATE_TIME` datetime DEFAULT NULL,
  `UPDATE_BY` varchar(64) DEFAULT NULL,
  `UPDATE_TIME` datetime DEFAULT NULL,
  PRIMARY KEY (`ID`),
  KEY `IDX_REDIS_OWNER` (`OWNER_USER_ID`),
  KEY `IDX_REDIS_PUBLIC` (`IS_PUBLIC`,`DEL_FLAG`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Redis 管理连接';

/*Data for the table `lm_redis_connection` */


/*Table structure for table `lm_secret_key_config` */

DROP TABLE IF EXISTS `lm_secret_key_config`;

CREATE TABLE `lm_secret_key_config` (
  `ID` bigint(11) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `CLIENT_ID` varchar(50) DEFAULT NULL COMMENT '客户端id',
  `CLIENT_NAME` varchar(50) DEFAULT NULL COMMENT '客户端名称',
  `PRIVATE_KEY` varchar(1800) DEFAULT NULL COMMENT '私钥',
  `PUBLIC_KEY` varchar(1500) DEFAULT NULL COMMENT '公钥',
  `CLIENT_PRIVATE_KEY` varchar(1800) DEFAULT NULL COMMENT '客户端私钥',
  `CLIENT_PUBLIC_KEY` varchar(1500) DEFAULT NULL COMMENT '客户端公钥',
  `OPEN` int(1) DEFAULT NULL COMMENT '开启加解密',
  `SHOW_LOG` int(1) DEFAULT NULL COMMENT '打印日志',
  `ALLOW_REQUEST_NO_ENCRYPT` varchar(1) DEFAULT NULL COMMENT '允许请求不加密',
  `CHARSET` varchar(10) DEFAULT NULL COMMENT '字符编码',
  `TYPE` varchar(20) DEFAULT NULL COMMENT '加密方式',
  `SECRET_KEY` varchar(16) DEFAULT NULL COMMENT 'AES秘钥',
  `DEL_FLAG` int(1) DEFAULT NULL COMMENT '删除标识',
  `CREATE_BY` varchar(50) DEFAULT NULL COMMENT '创建人',
  `CREATE_TIME` datetime DEFAULT NULL COMMENT '创建时间',
  `UPDATE_BY` varchar(50) DEFAULT NULL COMMENT '更新人',
  `UPDATE_TIME` datetime DEFAULT NULL COMMENT '更新时间',
  `SYSTEM_DEFAULT` int(1) DEFAULT NULL COMMENT '是否为默认密码',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4;

/*Data for the table `lm_secret_key_config` */


/*Table structure for table `lm_sensitive_word` */

DROP TABLE IF EXISTS `lm_sensitive_word`;

CREATE TABLE `lm_sensitive_word` (
  `ID` bigint(20) NOT NULL COMMENT '主键',
  `WORD` varchar(50) NOT NULL COMMENT '敏感词',
  `STATUS` tinyint(4) DEFAULT '1' COMMENT '状态：1-启用，0-禁用',
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='敏感词表';

/*Data for the table `lm_sensitive_word` */


/*Table structure for table `lm_sql_audit_rule` */

DROP TABLE IF EXISTS `lm_sql_audit_rule`;

CREATE TABLE `lm_sql_audit_rule` (
  `ID` bigint(20) NOT NULL COMMENT '主键',
  `CODE` varchar(64) NOT NULL COMMENT '规则编码',
  `NAME` varchar(128) NOT NULL COMMENT '规则名称',
  `DESCRIPTION` varchar(1000) DEFAULT NULL COMMENT '说明',
  `SEVERITY` varchar(16) NOT NULL DEFAULT 'WARNING' COMMENT 'ERROR/WARNING/OFF',
  `DIALECTS` varchar(255) DEFAULT '*' COMMENT '方言族，逗号分隔或 *',
  `ENABLED` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1启用 0禁用',
  `SCORE_WEIGHT` int(11) NOT NULL DEFAULT '20' COMMENT '风险分权重',
  `DEL_FLAG` tinyint(1) NOT NULL DEFAULT '0',
  `CREATE_BY` varchar(64) DEFAULT NULL,
  `CREATE_TIME` datetime DEFAULT NULL,
  `UPDATE_BY` varchar(64) DEFAULT NULL,
  `UPDATE_TIME` datetime DEFAULT NULL,
  PRIMARY KEY (`ID`),
  UNIQUE KEY `UK_SQL_AUDIT_RULE_CODE` (`CODE`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='SQL工单审计规则（覆盖内置默认）';

/*Data for the table `lm_sql_audit_rule` */

/*Table structure for table `lm_sql_work_order` */

DROP TABLE IF EXISTS `lm_sql_work_order`;

CREATE TABLE `lm_sql_work_order` (
  `ID` bigint(20) NOT NULL COMMENT '主键',
  `TITLE` varchar(160) NOT NULL COMMENT '工单标题',
  `DB_CONFIG_ID` bigint(20) NOT NULL COMMENT '目标数据库连接',
  `INSTANCE_NAME` varchar(128) NOT NULL COMMENT '目标实例/库/schema',
  `DB_TYPE` varchar(40) NOT NULL COMMENT '提交时数据库类型快照',
  `SCRIPT_TEXT` longtext NOT NULL COMMENT '当前版本 SQL',
  `SCRIPT_HASH` char(64) NOT NULL COMMENT '当前版本 SHA-256',
  `STATUS` varchar(24) NOT NULL COMMENT 'DRAFT/PENDING/APPROVED/REJECTED/EXECUTING/SUCCESS/FAILED',
  `CURRENT_VERSION` int(11) NOT NULL DEFAULT '1',
  `RISK_LEVEL` varchar(16) DEFAULT NULL,
  `RISK_SCORE` int(11) DEFAULT NULL,
  `AI_MODEL_ID` bigint(20) DEFAULT NULL,
  `AI_AUDIT_REPORT` longtext,
  `RULE_HITS_JSON` longtext COMMENT 'rule hits JSON',
  `STATEMENT_FINDINGS_JSON` longtext COMMENT 'per-statement findings JSON',
  `AUDIT_DETAIL` longtext COMMENT 'audit summary',
  `FORCE_SUBMITTED` tinyint(1) DEFAULT '0' COMMENT 'force submit',
  `IGNORE_WARNINGS` tinyint(1) DEFAULT '0' COMMENT 'ignore warnings',
  `FAIL_FAST` tinyint(1) DEFAULT '1' COMMENT 'fail fast',
  `SCHEDULED_EXECUTE_AT` datetime DEFAULT NULL COMMENT 'scheduled execute',
  `SUBMITTER_ID` bigint(20) NOT NULL,
  `SUBMITTER_NAME` varchar(100) DEFAULT NULL,
  `REVIEWER_ID` bigint(20) DEFAULT NULL,
  `REVIEWER_NAME` varchar(100) DEFAULT NULL,
  `REVIEW_COMMENT` varchar(1000) DEFAULT NULL,
  `ROLLBACK_FILE` varchar(500) DEFAULT NULL,
  `ROLLBACK_COMPLETE` tinyint(1) DEFAULT NULL,
  `EXECUTION_MESSAGE` varchar(2000) DEFAULT NULL,
  `SUBMITTED_AT` datetime DEFAULT NULL,
  `REVIEWED_AT` datetime DEFAULT NULL,
  `EXECUTED_AT` datetime DEFAULT NULL,
  `LOCK_VERSION` int(11) NOT NULL DEFAULT '0',
  `DEL_FLAG` tinyint(1) NOT NULL DEFAULT '0',
  `CREATE_BY` varchar(64) DEFAULT NULL,
  `CREATE_TIME` datetime DEFAULT NULL,
  `UPDATE_BY` varchar(64) DEFAULT NULL,
  `UPDATE_TIME` datetime DEFAULT NULL,
  PRIMARY KEY (`ID`),
  KEY `IDX_SQL_WO_SUBMITTER` (`SUBMITTER_ID`,`CREATE_TIME`),
  KEY `IDX_SQL_WO_STATUS` (`STATUS`,`CREATE_TIME`),
  KEY `IDX_SQL_WO_DB` (`DB_CONFIG_ID`,`INSTANCE_NAME`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='SQL 上线工单';

/*Data for the table `lm_sql_work_order` */


/*Table structure for table `lm_sql_work_order_event` */

DROP TABLE IF EXISTS `lm_sql_work_order_event`;

CREATE TABLE `lm_sql_work_order_event` (
  `ID` bigint(20) NOT NULL,
  `ORDER_ID` bigint(20) NOT NULL,
  `ACTION` varchar(32) NOT NULL,
  `ACTOR_ID` bigint(20) NOT NULL,
  `ACTOR_NAME` varchar(100) DEFAULT NULL,
  `FROM_STATUS` varchar(24) DEFAULT NULL,
  `TO_STATUS` varchar(24) DEFAULT NULL,
  `COMMENT_TEXT` varchar(2000) DEFAULT NULL,
  `DETAIL_TEXT` longtext,
  `CREATE_TIME` datetime DEFAULT NULL,
  PRIMARY KEY (`ID`),
  KEY `IDX_SQL_WO_EVENT_ORDER` (`ORDER_ID`,`CREATE_TIME`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='SQL 工单审计事件';

/*Data for the table `lm_sql_work_order_event` */


/*Table structure for table `lm_sql_work_order_notification` */

DROP TABLE IF EXISTS `lm_sql_work_order_notification`;

CREATE TABLE `lm_sql_work_order_notification` (
  `ID` bigint(20) NOT NULL COMMENT '主键',
  `RECIPIENT_ID` bigint(20) NOT NULL COMMENT '接收用户ID',
  `RECIPIENT_TYPE` varchar(16) NOT NULL COMMENT 'ADMIN/MEMBER',
  `DEPARTMENT_ID` bigint(20) DEFAULT NULL COMMENT '提交时部门或会员组快照',
  `SENDER_ID` bigint(20) NOT NULL COMMENT '发送用户ID',
  `SENDER_NAME` varchar(100) DEFAULT NULL COMMENT '发送人名称',
  `SENDER_AVATAR` varchar(500) DEFAULT NULL COMMENT '发送人头像',
  `NOTIFICATION_TYPE` varchar(64) NOT NULL COMMENT '通知类型',
  `TITLE` varchar(160) NOT NULL COMMENT '通知标题快照',
  `CONTENT` varchar(1000) NOT NULL COMMENT '通知内容快照',
  `BUSINESS_ID` bigint(20) NOT NULL COMMENT '关联工单ID',
  `BUSINESS_TITLE` varchar(160) DEFAULT NULL COMMENT '关联工单标题',
  `BUSINESS_ROUTE` varchar(255) DEFAULT NULL COMMENT '前端业务路由',
  `IS_READ` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0未读 1已读',
  `READ_TIME` datetime DEFAULT NULL COMMENT '阅读时间',
  `IS_DELETED` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0显示 1已清除',
  `CREATE_BY` varchar(64) DEFAULT NULL,
  `CREATE_TIME` datetime DEFAULT NULL,
  `UPDATE_BY` varchar(64) DEFAULT NULL,
  `UPDATE_TIME` datetime DEFAULT NULL,
  PRIMARY KEY (`ID`),
  KEY `IDX_SQL_WO_NOTICE_RECIPIENT` (`RECIPIENT_TYPE`,`RECIPIENT_ID`,`IS_DELETED`,`IS_READ`,`CREATE_TIME`),
  KEY `IDX_SQL_WO_NOTICE_BUSINESS` (`BUSINESS_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='SQL 工单站内通知';

/*Data for the table `lm_sql_work_order_notification` */


/*Table structure for table `lm_sql_work_order_version` */

DROP TABLE IF EXISTS `lm_sql_work_order_version`;

CREATE TABLE `lm_sql_work_order_version` (
  `ID` bigint(20) NOT NULL,
  `ORDER_ID` bigint(20) NOT NULL,
  `VERSION_NO` int(11) NOT NULL,
  `SCRIPT_TEXT` longtext NOT NULL,
  `SCRIPT_HASH` char(64) NOT NULL,
  `CHANGE_NOTE` varchar(500) DEFAULT NULL,
  `CREATED_BY_ID` bigint(20) NOT NULL,
  `CREATED_BY_NAME` varchar(100) DEFAULT NULL,
  `CREATE_TIME` datetime DEFAULT NULL,
  PRIMARY KEY (`ID`),
  UNIQUE KEY `UK_SQL_WO_VERSION` (`ORDER_ID`,`VERSION_NO`),
  KEY `IDX_SQL_WO_VERSION_ORDER` (`ORDER_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='SQL 工单脚本版本';

/*Data for the table `lm_sql_work_order_version` */


/*Table structure for table `lm_vq_change_window` */

DROP TABLE IF EXISTS `lm_vq_change_window`;

CREATE TABLE `lm_vq_change_window` (
  `ID` bigint(20) NOT NULL COMMENT '主键（雪花）',
  `SCOPE_TYPE` varchar(16) NOT NULL COMMENT 'ENV=按环境 CONNECTION=单个连接',
  `SCOPE_KEY` varchar(64) NOT NULL COMMENT 'ENV 时为环境码，CONNECTION 时为连接ID',
  `ENV` varchar(16) DEFAULT NULL COMMENT 'SCOPE_TYPE=ENV 时的环境',
  `DB_CONFIG_ID` bigint(20) DEFAULT NULL COMMENT 'SCOPE_TYPE=CONNECTION 时的连接ID',
  `ENABLED` tinyint(4) NOT NULL DEFAULT '1' COMMENT '1启用 0停用（停用的连接级配置回退到环境级）',
  `TIMEZONE` varchar(64) NOT NULL DEFAULT 'Asia/Shanghai' COMMENT 'IANA 时区',
  `RULES_JSON` text COMMENT '开放时段 [{"days":[1..7],"start":"HH:mm","end":"HH:mm"}]，空=全天开放',
  `FREEZES_JSON` text COMMENT '封网时段 [{"start":"yyyy-MM-dd[ HH:mm]","end":"...","reason":""}]',
  `REMARK` varchar(255) DEFAULT NULL COMMENT '备注',
  `CREATE_BY` varchar(64) DEFAULT NULL,
  `CREATE_TIME` datetime DEFAULT NULL,
  `UPDATE_BY` varchar(64) DEFAULT NULL,
  `UPDATE_TIME` datetime DEFAULT NULL,
  PRIMARY KEY (`ID`),
  UNIQUE KEY `UK_VQ_CHANGE_WINDOW_SCOPE` (`SCOPE_TYPE`,`SCOPE_KEY`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='数据库变更窗口（窗口外禁止直接执行写操作）';

/*Data for the table `lm_vq_change_window` */

/*Table structure for table `lm_vq_client_session` */

DROP TABLE IF EXISTS `lm_vq_client_session`;

CREATE TABLE `lm_vq_client_session` (
  `ID` bigint(20) NOT NULL COMMENT '主键ID（雪花）',
  `USER_ID` bigint(20) NOT NULL COMMENT '登录用户ID（权限隔离）',
  `ALIAS_NAME` varchar(100) NOT NULL COMMENT '现场别名',
  `CLIENT_LABEL` varchar(200) DEFAULT NULL COMMENT '保存时的客户端说明，便于在另一台电脑辨认',
  `SNAPSHOT_JSON` mediumtext NOT NULL COMMENT '已打开连接与 SQL 页签',
  `CONNECTION_COUNT` int(11) NOT NULL DEFAULT '0' COMMENT '连接数',
  `TAB_COUNT` int(11) NOT NULL DEFAULT '0' COMMENT '查询页签数',
  `DEL_FLAG` tinyint(1) NOT NULL DEFAULT '0' COMMENT '删除标识 0正常 1删除',
  `CREATE_BY` varchar(64) DEFAULT NULL COMMENT '创建者',
  `CREATE_TIME` datetime DEFAULT NULL COMMENT '创建时间',
  `UPDATE_BY` varchar(64) DEFAULT NULL COMMENT '更新者',
  `UPDATE_TIME` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`ID`),
  KEY `IDX_VQ_CLIENT_SESSION_USER` (`USER_ID`,`DEL_FLAG`,`UPDATE_TIME`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='SQL编辑器工作现场快照（按用户隔离，可多份）';

/*Data for the table `lm_vq_client_session` */


/*Table structure for table `lm_vq_db_config` */

DROP TABLE IF EXISTS `lm_vq_db_config`;

CREATE TABLE `lm_vq_db_config` (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `DB_NAME` varchar(100) DEFAULT NULL COMMENT 'db name',
  `DB_TYPE` varchar(20) NOT NULL COMMENT '数据库类型',
  `DB_HOST` varchar(50) NOT NULL DEFAULT '-' COMMENT 'host',
  `DB_PORT` int(6) NOT NULL DEFAULT '0' COMMENT 'port',
  `JDBC_URL` varchar(1024) NOT NULL DEFAULT '' COMMENT 'jdbc url',
  `USERNAME` varchar(100) NOT NULL DEFAULT '-' COMMENT 'username',
  `PASSWORD` varchar(100) NOT NULL DEFAULT '' COMMENT 'password',
  `DESCRIPTION` varchar(500) DEFAULT NULL COMMENT '描述',
  `IS_PUBLIC` tinyint(1) DEFAULT '0' COMMENT '是否公开库：1=登录用户可用(默认不可改画布)',
  `OWNER_USER_ID` bigint(20) DEFAULT NULL COMMENT '创建者/所有者用户ID',
  `ORDER_NUM` int(4) NOT NULL DEFAULT '0' COMMENT 'order',
  `DEL_FLAG` tinyint(1) DEFAULT '0' COMMENT '删除标识',
  `CREATE_BY` varchar(64) DEFAULT NULL COMMENT '创建者',
  `CREATE_TIME` datetime DEFAULT NULL COMMENT '创建时间',
  `UPDATE_BY` varchar(64) DEFAULT NULL COMMENT '更新者',
  `UPDATE_TIME` datetime DEFAULT NULL COMMENT '更新时间',
  `SCHEMA_NAME` varchar(512) DEFAULT NULL COMMENT 'schema or file path',
  `CONNECTION_STATUS` int(11) DEFAULT '0' COMMENT '连接状态（0-未连接 1-已连接）',
  `LAST_CHECK_TIME` datetime DEFAULT NULL COMMENT '最后连接检测时间',
  `SSH_ENABLED` tinyint(1) DEFAULT '0' COMMENT '是否启用 SSH 隧道(0否1是)',
  `SSH_HOST` varchar(128) DEFAULT NULL COMMENT 'SSH 跳板机主机',
  `SSH_PORT` int(6) DEFAULT '22' COMMENT 'SSH 端口',
  `SSH_USERNAME` varchar(64) DEFAULT NULL COMMENT 'SSH 用户名',
  `SSH_PASSWORD` varchar(256) DEFAULT NULL COMMENT 'SSH 密码(与私钥二选一)',
  `SSH_PRIVATE_KEY` text COMMENT 'SSH 私钥 PEM 文本',
  `SSH_PASSPHRASE` varchar(256) DEFAULT NULL COMMENT 'SSH 私钥口令',
  `AI_ALLOW_SAMPLE_DATA` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'AI 工具是否允许读取真实行数据（sample_rows/run_sql 返回行）',
  `AI_ENABLED` tinyint(1) NOT NULL DEFAULT '1' COMMENT '该连接是否允许 AI 访问',
  `ENV` varchar(16) DEFAULT NULL COMMENT '环境标签 DEV/TEST/UAT/PROD，空=未标记（按名称关键词兜底识别生产）',
  `ENV_LABEL` varchar(32) DEFAULT NULL COMMENT '环境自定义显示名',
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB AUTO_INCREMENT=40 DEFAULT CHARSET=utf8mb4 COMMENT='数据库配置信息表';

