  `CONFIG_ID` bigint(20) NOT NULL COMMENT '原查询配置ID',
  `CONFIG_NAME` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '查询配置名称',
  `CONFIG_DESCRIPTION` text COLLATE utf8mb4_unicode_ci COMMENT '查询配置描述',
  `CONFIG_DATA` json DEFAULT NULL COMMENT 'QueryConfig完整数据（JSON格式）',
  `ITEMS_DATA` json DEFAULT NULL COMMENT 'QueryConfigItem列表数据（JSON格式）',
  `BACKUP_REASON` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT 'UPDATE' COMMENT '备份原因：UPDATE-更新前备份, DELETE-删除前备份',
  `BACKUP_TIME` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '备份时间',
  `BACKUP_BY` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备份操作用户',
  `ITEMS_COUNT` int(11) DEFAULT '0' COMMENT '备份的配置项数量',
  `DEL_FLAG` tinyint(1) DEFAULT '0' COMMENT '删除标志（0存在 1删除）',
  `CREATE_BY` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建者',
  `CREATE_TIME` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `UPDATE_BY` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '更新者',
  `UPDATE_TIME` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`ID`),
  KEY `idx_config_id` (`CONFIG_ID`),
  KEY `idx_backup_time` (`BACKUP_TIME`),
  KEY `idx_backup_reason` (`BACKUP_REASON`),
  KEY `idx_del_flag` (`DEL_FLAG`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='查询配置备份表';

