  `MAPPING_ID` varchar(50) DEFAULT NULL COMMENT '业务映射码',
  PRIMARY KEY (`ID`),
  KEY `IDX_RELATIONSHIP_ID` (`RELATIONSHIP_ID`),
  KEY `IDX_SOURCE_FIELD_ID` (`SOURCE_FIELD_ID`),
  KEY `IDX_TARGET_FIELD_ID` (`TARGET_FIELD_ID`)
