/*Data for the table `lm_vq_relationship_field` */


/*Table structure for table `lm_vq_saved_query` */

DROP TABLE IF EXISTS `lm_vq_saved_query`;

CREATE TABLE `lm_vq_saved_query` (
  `ID` bigint(20) NOT NULL COMMENT '主键ID（雪花）',
  `QUERY_NAME` varchar(100) NOT NULL COMMENT '查询名称',
  `SQL_TEXT` mediumtext NOT NULL COMMENT 'SQL 内容',
  `DB_CONFIG_ID` bigint(20) NOT NULL COMMENT '连接配置ID（LM_VQ_DB_CONFIG.ID）',
  `INSTANCE_NAME` varchar(128) NOT NULL COMMENT '数据库/Schema/实例名（因库类型而异）',
  `SCHEMA_NAME` varchar(128) DEFAULT NULL COMMENT 'PG/Oracle Schema/Owner',
  `GROUP_ID` bigint(20) DEFAULT NULL COMMENT '所属分组ID（LM_VQ_SAVED_QUERY_GROUP.ID）',
  `USER_ID` bigint(20) NOT NULL COMMENT '登录用户ID（权限隔离）',
  `DESCRIPTION` varchar(500) DEFAULT NULL COMMENT '备注',
  `ORDER_NUM` int(4) NOT NULL DEFAULT '0' COMMENT '排序',
  `DEL_FLAG` tinyint(1) DEFAULT '0' COMMENT '删除标识 0正常 1删除',
  `CREATE_BY` varchar(64) DEFAULT NULL COMMENT '创建者',
  `CREATE_TIME` datetime DEFAULT NULL COMMENT '创建时间',
  `UPDATE_BY` varchar(64) DEFAULT NULL COMMENT '更新者',
  `UPDATE_TIME` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`ID`),
  KEY `IDX_SAVED_QUERY_SCOPE` (`USER_ID`,`DB_CONFIG_ID`,`INSTANCE_NAME`),
  KEY `IDX_SAVED_QUERY_CONFIG` (`DB_CONFIG_ID`),
  KEY `IDX_SAVED_QUERY_GROUP` (`GROUP_ID`),
  KEY `IDX_SAVED_QUERY_SCHEMA_SCOPE` (`USER_ID`,`DB_CONFIG_ID`,`INSTANCE_NAME`,`SCHEMA_NAME`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='SQL编辑器已保存查询（按用户+连接+库隔离）';

/*Data for the table `lm_vq_saved_query` */


/*Table structure for table `lm_vq_saved_query_group` */

DROP TABLE IF EXISTS `lm_vq_saved_query_group`;

CREATE TABLE `lm_vq_saved_query_group` (
  `ID` bigint(20) NOT NULL COMMENT '主键ID（雪花）',
  `GROUP_NAME` varchar(100) NOT NULL COMMENT '分组名称',
  `PARENT_ID` bigint(20) DEFAULT NULL COMMENT '父分组ID，空=根节点',
  `USER_ID` bigint(20) NOT NULL COMMENT '登录用户ID（权限隔离）',
  `DESCRIPTION` varchar(500) DEFAULT NULL COMMENT '备注',
  `ORDER_NUM` int(4) NOT NULL DEFAULT '0' COMMENT '排序',
  `DEL_FLAG` tinyint(1) DEFAULT '0' COMMENT '删除标识 0正常 1删除',
  `CREATE_BY` varchar(64) DEFAULT NULL COMMENT '创建者',
  `CREATE_TIME` datetime DEFAULT NULL COMMENT '创建时间',
  `UPDATE_BY` varchar(64) DEFAULT NULL COMMENT '更新者',
  `UPDATE_TIME` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`ID`),
  KEY `IDX_SQG_USER_PARENT` (`USER_ID`,`PARENT_ID`),
  KEY `IDX_SQG_USER` (`USER_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='SQL已保存查询分组（按用户隔离，可嵌套）';

/*Data for the table `lm_vq_saved_query_group` */


/*Table structure for table `lm_vq_sql_history` */

DROP TABLE IF EXISTS `lm_vq_sql_history`;

CREATE TABLE `lm_vq_sql_history` (
  `ID` bigint(20) NOT NULL,
  `USER_ID` bigint(20) NOT NULL,
  `DB_CONFIG_ID` bigint(20) NOT NULL,
  `INSTANCE_NAME` varchar(128) DEFAULT NULL,
  `SQL_TEXT` mediumtext NOT NULL,
  `SQL_HASH` char(32) NOT NULL COMMENT 'MD5(规范化 SQL)，用于去重/频次统计',
  `SQL_KIND` varchar(16) DEFAULT 'SELECT' COMMENT 'SELECT/DML/DDL/CALL/OTHER',
  `SOURCE` varchar(16) NOT NULL DEFAULT 'manual' COMMENT 'manual=用户手写 / ai=Agent 生成 / agent_tool=Agent 内部 run_sql',
  `STATUS` tinyint(1) NOT NULL COMMENT '1 成功 0 失败',
  `ERROR_MSG` varchar(2000) DEFAULT NULL,
  `ROW_COUNT` int(11) DEFAULT NULL,
  `ELAPSED_MS` bigint(20) DEFAULT NULL,
  `TABLES_JSON` text COMMENT '解析出的表名数组 JSON，如 ["t_order","t_user"]',
  `ANALYZED` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否已被 Schema 文档分析消费',
  `EXECUTED_AT` datetime NOT NULL,
  PRIMARY KEY (`ID`),
  KEY `IDX_SQLHIS_SCOPE` (`USER_ID`,`DB_CONFIG_ID`,`INSTANCE_NAME`,`EXECUTED_AT`),
  KEY `IDX_SQLHIS_HASH` (`DB_CONFIG_ID`,`SQL_HASH`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='SQL 执行历史';

/*Data for the table `lm_vq_sql_history` */


/*Table structure for table `lm_vq_table_group` */

