CREATE TABLE `lm_vq_table_group` (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `DB_CONFIG_ID` bigint(20) NOT NULL COMMENT '所属数据库ID',
  `GROUP_NAME` varchar(100) NOT NULL COMMENT '分组名称',
  `DESCRIPTION` varchar(500) DEFAULT NULL COMMENT '分组描述',
  `DEL_FLAG` tinyint(1) DEFAULT '0' COMMENT '删除标识',
  `ORDER_NUM` int(4) NOT NULL COMMENT '排序',
  `CREATE_BY` varchar(64) DEFAULT NULL COMMENT '创建者',
  `CREATE_TIME` datetime DEFAULT NULL COMMENT '创建时间',
  `UPDATE_BY` varchar(64) DEFAULT NULL COMMENT '更新者',
  `UPDATE_TIME` datetime DEFAULT NULL COMMENT '更新时间',
  `SCHEMA_NAME` varchar(50) DEFAULT NULL COMMENT '所属数据库实例',
  `IS_PUBLIC` tinyint(1) DEFAULT '1' COMMENT '1=有库权限可见；0=仅创建者',
  `OWNER_USER_ID` bigint(20) DEFAULT NULL COMMENT '创建者用户ID',
  PRIMARY KEY (`ID`),
  KEY `IDX_DB_CONFIG_ID` (`DB_CONFIG_ID`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COMMENT='表分组表';

