/*Table structure for table `sys_menu` */

DROP TABLE IF EXISTS `sys_menu`;

CREATE TABLE `sys_menu` (
  `menu_id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '菜单ID',
  `menu_name` varchar(50) NOT NULL COMMENT '菜单名称',
  `parent_id` bigint(20) DEFAULT '0' COMMENT '父菜单ID',
  `order_num` int(4) DEFAULT '0' COMMENT '显示顺序',
  `path` varchar(200) DEFAULT '' COMMENT '路由地址',
  `component` varchar(255) DEFAULT NULL COMMENT '组件路径',
  `query_param` varchar(255) DEFAULT NULL COMMENT '路由参数',
  `redirect` varchar(200) DEFAULT NULL COMMENT '路由重定向',
  `active_path` varchar(200) DEFAULT NULL COMMENT '高亮菜单 path(对应 vben meta.activePath)',
  `is_frame` int(1) DEFAULT '1' COMMENT '是否为外链（1是 0否）',
  `is_cache` int(1) DEFAULT '0' COMMENT '是否缓存（1缓存 0不缓存）',
  `affix_tab` tinyint(1) DEFAULT NULL COMMENT '固定标签(1是 0否，空则按旧规则 path=index)',
  `hide_in_tab` tinyint(1) DEFAULT '0' COMMENT '不在标签页显示(1是 0否)',
  `hide_in_breadcrumb` tinyint(1) DEFAULT '0' COMMENT '不在面包屑显示(1是 0否)',
  `hide_children_in_menu` tinyint(1) DEFAULT '0' COMMENT '隐藏子菜单(1是 0否)',
  `open_in_new_window` tinyint(1) DEFAULT NULL COMMENT '新窗口打开(1是 0否，空则外链默认是)',
  `iframe_src` varchar(500) DEFAULT NULL COMMENT '内嵌 iframe 地址(对应 vben meta.iframeSrc)',
  `badge` varchar(50) DEFAULT NULL COMMENT '徽标文本',
  `badge_type` varchar(20) DEFAULT NULL COMMENT '徽标类型 normal|dot',
  `badge_variants` varchar(50) DEFAULT NULL COMMENT '徽标色 primary|success|warning|destructive 等',
  `menu_type` char(1) DEFAULT '' COMMENT '菜单类型（M目录 C菜单 F按钮）',
  `visible` int(1) DEFAULT '0' COMMENT '菜单状态（1显示 0隐藏）',
  `status` int(1) DEFAULT '0' COMMENT '菜单状态（1正常 0停用）',
  `icon` varchar(100) DEFAULT '#' COMMENT '菜单图标',
  `active_icon` varchar(100) DEFAULT NULL COMMENT '激活图标(对应 vben meta.activeIcon)',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) DEFAULT '' COMMENT '备注',
  `name` varchar(50) DEFAULT NULL COMMENT '路由名称',
  PRIMARY KEY (`menu_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=245 DEFAULT CHARSET=utf8 COMMENT='菜单权限表';

/*Data for the table `sys_menu` */


/*Table structure for table `sys_menu_module` */

