CREATE TABLE `sys_menu_module` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `menu_id` bigint(20) NOT NULL COMMENT '页面菜单ID(sys_menu.menu_id)',
  `module_code` varchar(64) NOT NULL COMMENT '后端 @Module.code',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_menu_module` (`menu_id`,`module_code`),
  KEY `idx_module_code` (`module_code`)
) ENGINE=InnoDB AUTO_INCREMENT=99 DEFAULT CHARSET=utf8mb4 COMMENT='菜单挂载的后端权限模块';

