  `module_code` varchar(40) DEFAULT NULL COMMENT '模块编码，关联菜单表',
  `operation_code` varchar(60) DEFAULT NULL COMMENT '操作编码',
  `operation_name` varchar(50) DEFAULT NULL COMMENT '操作名称',
