  PRIMARY KEY (`id`) USING BTREE,
  KEY `INDEX_OPERATION_MODULE_CODE` (`module_code`) USING BTREE,
  KEY `INDEX_OPERATION_CODE` (`operation_code`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=538 DEFAULT CHARSET=utf8mb4 COMMENT='操作权限表';

