/* Procedure structure for procedure `VQ_ADD_COLUMN_IF_NOT_EXISTS` */

/*!50003 DROP PROCEDURE IF EXISTS  `VQ_ADD_COLUMN_IF_NOT_EXISTS` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`%` PROCEDURE `VQ_ADD_COLUMN_IF_NOT_EXISTS`(
    IN tblName VARCHAR(128),
    IN colName VARCHAR(128),
    IN colDef  VARCHAR(512)
)
BEGIN
    IF NOT EXISTS(
        SELECT 1 FROM INFORMATION_SCHEMA.COLUMNS
        WHERE TABLE_SCHEMA = DATABASE()
          AND TABLE_NAME = tblName
          AND COLUMN_NAME = colName
    ) THEN
        SET @ddl = CONCAT('ALTER TABLE `', tblName, '` ADD COLUMN ', colDef);
        PREPARE stmt FROM @ddl;
        EXECUTE stmt;
        DEALLOCATE PREPARE stmt;
    END IF;
END */$$
DELIMITER ;

